    /**
     * @description Apply MyCAP out-year uplift defaulting and Deal Desk approval flagging.
     *              Runs only on RENEWAL quote lines (QuoteAction.Type = 'Renew').
     *              COLA uplift is a renewal-time concept; MyCAP only modifies COLA uplift
     *              values, so new-business quotes are not affected.
     *
     *              Qualifying line: on a renewal QuoteAction
     *              AND multi-year (PricingTerm > 1 OR SubscriptionTerm > 1)
     *              AND annually billed (BillingFrequency = 'Annual')
     *              AND NOT fully prepaid (QLI attribute PS_Service_Type != 'Prepaid').
     *
     *              For qualifying lines that are not already overridden, defaults
     *              COLAUpliftPercent__c to the CMDT-configured value (default 3%).
     *
     *              If any qualifying line's effective uplift is below the CMDT minimum
     *              threshold, sets Quote.Mycap__c = true (triggering the existing
     *              Fortra_Quote_MYCAP_Sale_Approval_Criteria_Record_Triggered flow).
     *              Otherwise sets Quote.Mycap__c = false.
     *
     * @param ctxInstanceId Context instance ID
     * @param rule Global MyCAP rule CMDT record (already null/active checked)
     * @return Number of distinct Quotes evaluated
     */
    @TestVisible
    private Integer processMyCAPEligibility(String ctxInstanceId, MyCAP_Rules__mdt rule) {
        try {
            Context.IndustriesContext ctx = new Context.IndustriesContext();
            List<Object> rawLineItems = fetchSalesTransactionItems(ctx, ctxInstanceId);
            return processMyCAPEligibility(rawLineItems, rule);
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'MyCAP processing error: ' + e.getMessage());
            System.debug(LoggingLevel.ERROR, 'Stack: ' + e.getStackTraceString());
            return 0;
        }
    }

    @TestVisible
    private Integer processMyCAPEligibility(List<Object> rawLineItems, MyCAP_Rules__mdt rule) {
        Decimal defaultUplift = rule.Default_Out_Year_Uplift_Percent__c != null
            ? rule.Default_Out_Year_Uplift_Percent__c : 3;
        Decimal minimumUplift = rule.Minimum_Out_Year_Uplift_Percent__c != null
            ? rule.Minimum_Out_Year_Uplift_Percent__c : 3;

        try {
            if (rawLineItems == null || rawLineItems.isEmpty()) {
                return 0;
            }

            // First pass: collect qualifying lines (renewal + multi-year + annual).
            // Renewal gate uses SalesTransactionActionType per-line context tag
            // (verified key in pricing context as of 2026-04-15). The legacy
            // QuoteActionId tag isn't hydrated, so we can't query QuoteAction by Id.
            // Track ALL renewal QLIs (for audit-field context writes) and the
            // subset that qualifies for MyCAP defaulting (multi-year + annual).
            Set<Id> qliIds = new Set<Id>();                   // qualifying only (for prepaid lookup)
            Set<Id> allRenewalQliIds = new Set<Id>();          // all renewal lines
            Set<Id> quoteIds = new Set<Id>();
            List<Map<String, Object>> allRenewalWrappers = new List<Map<String, Object>>();
            Set<Object> qualifyingWrapperSet = new Set<Object>(); // identity-based set
            Map<Map<String, Object>, Id> wrapperToQliId = new Map<Map<String, Object>, Id>();
            Map<Map<String, Object>, Id> wrapperToQuoteId = new Map<Map<String, Object>, Id>();
            Map<Map<String, Object>, Decimal> wrapperCurrentUplift = new Map<Map<String, Object>, Decimal>();
            Map<Map<String, Object>, Decimal> wrapperDefaultUplift = new Map<Map<String, Object>, Decimal>();
            Map<Map<String, Object>, Decimal> wrapperUnitPrice = new Map<Map<String, Object>, Decimal>();
            Map<Map<String, Object>, String> wrapperSolCat = new Map<Map<String, Object>, String>();
            Map<Map<String, Object>, Boolean> wrapperIsOverridden = new Map<Map<String, Object>, Boolean>();
            Map<Map<String, Object>, Decimal> wrapperPricingTermCount = new Map<Map<String, Object>, Decimal>();

            for (Object rawItem : rawLineItems) {
                Map<String, Object> itemWrapper = (rawItem instanceof Map<String, Object>)
                    ? (Map<String, Object>) rawItem : null;
                if (itemWrapper == null) continue;

                Map<String, Object> lineItem = extractLineItemData(rawItem);
                if (lineItem == null) continue;

                // Renewal gate
                String stActionType = getStringFromTag(lineItem, 'SalesTransactionActionType');
                if (stActionType != 'Renew') continue;

                // Extract QLI / Quote Ids from dataPath
                Id qliId;
                Id quoteId;
                Object dpObj = itemWrapper.get('dataPath');
                if (dpObj instanceof List<Object>) {
                    List<Object> dp = (List<Object>) dpObj;
                    if (dp.size() >= 1) {
                        try { qliId = Id.valueOf(String.valueOf(dp.get(dp.size() - 1))); } catch (Exception e) {}
                    }
                    if (dp.size() >= 2) {
                        try { quoteId = Id.valueOf(String.valueOf(dp.get(dp.size() - 2))); } catch (Exception e) {}
                    }
                }
                if (qliId == null) continue;

                // Read pricing context tags
                Decimal pricingTermCount = getDecimalFromTag(lineItem, 'PricingTermCount');
                String pricingTermUnit = getStringFromTag(lineItem, 'PricingTermUnit');
                Decimal itemSubscriptionTerm = getDecimalFromTag(lineItem, 'ItemSubscriptionTerm');
                Boolean isAnnualUnit = pricingTermUnit == 'Annual';
                Boolean isMultiYearAnnual = isAnnualUnit
                    && ((pricingTermCount != null && pricingTermCount > 1)
                        || (itemSubscriptionTerm != null && itemSubscriptionTerm > 1));

                allRenewalQliIds.add(qliId);
                if (quoteId != null) quoteIds.add(quoteId);
                allRenewalWrappers.add(itemWrapper);
                wrapperToQliId.put(itemWrapper, qliId);
                wrapperToQuoteId.put(itemWrapper, quoteId);
                wrapperCurrentUplift.put(itemWrapper, getDecimalFromTag(lineItem, 'COLA_Uplift_Percent__c'));
                wrapperDefaultUplift.put(itemWrapper, getDecimalFromTag(lineItem, 'Default_COLA_Uplift_Percent__c'));
                wrapperUnitPrice.put(itemWrapper, getDecimalFromTag(lineItem, 'UnitPrice'));
                wrapperSolCat.put(itemWrapper, getStringFromTag(lineItem, 'COLA_Solution_Category__c'));
                wrapperIsOverridden.put(itemWrapper, getBooleanFromTag(lineItem, 'IsCOLAOverridden__c'));
                wrapperPricingTermCount.put(itemWrapper, pricingTermCount);

                if (isMultiYearAnnual) {
                    qliIds.add(qliId);
                    qualifyingWrapperSet.add(itemWrapper);
                }
            }

            if (allRenewalWrappers.isEmpty()) {
                System.debug(LoggingLevel.INFO, 'MyCAP: no renewal lines found');
                return 0;
            }

            // Fill in missing Quote Ids and get Default_COLA_Uplift_Percent__c
            // for override detection. The IsCOLAOverridden__c context tag has a
            // timing gap: users edit COLA% in the TLE but the flag isn't set until
            // the COLAUpliftHandler trigger fires AFTER pricing write-back.
            // So we compare context COLA% against the persisted default to detect
            // overrides that the boolean flag hasn't caught yet.
            Map<Id, Id> qliIdToQuoteId = new Map<Id, Id>();
            Map<Id, Decimal> qliIdToDefaultPct = new Map<Id, Decimal>();
            Map<Id, Decimal> qliIdToOutyearPct = new Map<Id, Decimal>();
            for (QuoteLineItem qli : [SELECT Id, QuoteId, Default_COLA_Uplift_Percent__c, COLA_Outyear_Uplift_Percent__c FROM QuoteLineItem WHERE Id IN :allRenewalQliIds]) {
                qliIdToQuoteId.put(qli.Id, qli.QuoteId);
                qliIdToDefaultPct.put(qli.Id, qli.Default_COLA_Uplift_Percent__c);
                qliIdToOutyearPct.put(qli.Id, qli.COLA_Outyear_Uplift_Percent__c);
                quoteIds.add(qli.QuoteId);
            }

            // Bulk prepaid lookup via QuoteLineItemAttribute.
            // Two-step: resolve the PS_Service_Type AttributeDefinition and the
            // 'Prepaid' AttributePicklistValue Ids, then filter QLAs by Id.
            // AttributeValue is not reliably filterable in WHERE clauses on this
            // entity, and AttributeName stores the display label ("PS Service Type")
            // rather than the DeveloperName. Id-based filtering is portable.
            Set<Id> prepaidQliIds = new Set<Id>();
            Id psAdId;
            Id psPicklistId;
            for (AttributeDefinition ad : [
                SELECT Id, PicklistId FROM AttributeDefinition
                WHERE DeveloperName = 'PS_Service_Type' LIMIT 1
            ]) {
                psAdId = ad.Id;
                psPicklistId = ad.PicklistId;
            }
            Id prepaidApvId;
            if (psPicklistId != null) {
                for (AttributePicklistValue apv : [
                    SELECT Id FROM AttributePicklistValue
                    WHERE PicklistId = :psPicklistId AND Value = 'Prepaid' LIMIT 1
                ]) {
                    prepaidApvId = apv.Id;
                }
            }
            if (psAdId != null && prepaidApvId != null) {
                for (QuoteLineItemAttribute qla : [
                    SELECT QuoteLineItemId FROM QuoteLineItemAttribute
                    WHERE QuoteLineItemId IN :qliIds
                      AND AttributeDefinitionId = :psAdId
                      AND AttributePicklistValueId = :prepaidApvId
                ]) {
                    prepaidQliIds.add(qla.QuoteLineItemId);
                }
            } else {
                System.debug(LoggingLevel.INFO, 'MyCAP: PS_Service_Type/Prepaid not found in org - skipping prepaid bypass');
            }
            System.debug(LoggingLevel.INFO, 'MyCAP: ' + prepaidQliIds.size() + ' of ' + qliIds.size() + ' qualifying lines are Prepaid (bypassed)');

            // Second pass: for EACH renewal QLI, build a context update so
            // RC pricing's write-back populates the audit fields correctly.
            // MyCAP-qualifying lines get COLA% defaulted to 3; others keep
            // their current COLA%. All lines get Pre-COLA / CalcPrice /
            // Source / Category / AppliedDate written via hydrated context
            // attributes so they survive the reprice cycle.
            Map<Id, Decimal> qliCOLADefaults = new Map<Id, Decimal>();
            Set<Id> quotesToFlagTrue = new Set<Id>();
            Set<Id> quotesToFlagFalse = new Set<Id>();

            for (Map<String, Object> itemWrapper : allRenewalWrappers) {
                Id qliId = wrapperToQliId.get(itemWrapper);
                Id quoteId = wrapperToQuoteId.get(itemWrapper);
                if (quoteId == null) quoteId = qliIdToQuoteId.get(qliId);

                Boolean isOverridden = wrapperIsOverridden.get(itemWrapper) == true;
                Decimal currentUplift = wrapperCurrentUplift.get(itemWrapper);
                Decimal defaultPct = wrapperDefaultUplift.get(itemWrapper);
                Decimal unitPrice = wrapperUnitPrice.get(itemWrapper);
                String solCat = wrapperSolCat.get(itemWrapper);
                Decimal pricingTermCount = wrapperPricingTermCount.get(itemWrapper);
                Boolean isQualifying = qualifyingWrapperSet.contains(itemWrapper);
                Boolean isPrepaid = prepaidQliIds.contains(qliId);

                // Detect overrides: IsCOLAOverridden__c has a timing gap in the
                // TLE (flag only set by trigger AFTER pricing write-back). Also
                // compare context COLA% against the persisted Default to catch
                // edits the boolean hasn't reflected yet.
                Decimal persistedDefault = qliIdToDefaultPct.get(qliId);
                Boolean isEffectivelyOverridden = isOverridden
                    || (currentUplift != null && persistedDefault != null && currentUplift != persistedDefault);

                // Determine target uplift for this line
                Decimal targetUplift = currentUplift;
                String source = isEffectivelyOverridden ? 'Line Override' : 'CMDT Lookup';

                if (isQualifying && !isPrepaid && !isEffectivelyOverridden) {
                    // MyCAP-qualifying, not overridden -> default to 3%
                    if (currentUplift == null || currentUplift != defaultUplift) {
                        targetUplift = defaultUplift;
                        source = 'MyCAP Default';
                        qliCOLADefaults.put(qliId, defaultUplift);
                    } else {
                        targetUplift = defaultUplift; // already at 3%
                        source = 'MyCAP Default';
                    }
                }

                // Flag evaluation for MyCAP-qualifying lines.
                // Flag if EITHER year-1 COLA% OR outyear COLA% is below minimum.
                if (isQualifying && !isPrepaid && quoteId != null) {
                    Decimal effectiveUplift = isEffectivelyOverridden ? currentUplift : targetUplift;
                    Decimal outyearPct = qliIdToOutyearPct.get(qliId);
                    Boolean year1BelowMin = effectiveUplift != null && effectiveUplift < minimumUplift;
                    Boolean outyearBelowMin = outyearPct != null && outyearPct < minimumUplift;
                    if (year1BelowMin || outyearBelowMin) {
                        quotesToFlagTrue.add(quoteId);
                    }
                }

                // D-COLA-6: the per-line COLA audit context write is owned by processLineItems /
                // buildItemUpdate (Asset-price-anchored). The old buildCOLAContextUpdate accumulation
                // here fed a list that was never submitted (dead), and it reverse-derives Pre-COLA from
                // UnitPrice — a §11 r1 base-price-invariant violation if ever re-wired. Removed; MyCAP
                // here only evaluates the flag. Do NOT re-add a context write from this loop without
                // sourcing Pre-COLA from the Asset price.
            }
            for (Id qId : quoteIds) {
                if (!quotesToFlagTrue.contains(qId)) quotesToFlagFalse.add(qId);
            }

            // Context writes for COLA audit fields are handled by processLineItems
            // via buildItemUpdate. A second updateContextAttributes call here
            // overwrites those values with recomputed amounts that lack Asset
            // price data, causing blank fields. MyCAP only evaluates the flag.
            System.debug(LoggingLevel.INFO, 'MyCAP: evaluated ' + allRenewalWrappers.size()
                + ' renewal lines, ' + qliCOLADefaults.size() + ' defaulted');

            // Quote.Mycap__c cannot be written from a QLI pricing context,
            // so we defer it to a Queueable. Quote-level DML does NOT trigger
            // the pricing engine, so no repricing loop.
            if (!quotesToFlagTrue.isEmpty() || !quotesToFlagFalse.isEmpty()) {
                System.enqueueJob(new MyCAPFlagApplier(quotesToFlagTrue, quotesToFlagFalse));
                System.debug(LoggingLevel.INFO, 'MyCAP: enqueued - Quotes flag=true:' + quotesToFlagTrue.size()
                    + ' flag=false:' + quotesToFlagFalse.size());
            }

            return quoteIds.size();
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'MyCAP processing error: ' + e.getMessage());
            System.debug(LoggingLevel.ERROR, 'Stack: ' + e.getStackTraceString());
            return 0;
        }
    }

    /**
     * @description Query the SalesTransactionItem raw line item list from context.
     *              Mirrors the extraction pattern in processLineItems so both branches
     *              work off the same context shape.
     */
    private List<Object> fetchSalesTransactionItems(Context.IndustriesContext ctx, String ctxInstanceId) {
        Map<String, Object> queryInput = new Map<String, Object>{
            'contextId' => ctxInstanceId,
            'tags' => new List<String>{ 'SalesTransactionItem' }
        };
        Map<String, Object> apiResponse = ctx.queryTags(queryInput);
        if (apiResponse == null) return null;

        Map<String, Object> queryResult;
        if (apiResponse.containsKey('queryResult')) {
            Object qrObj = apiResponse.get('queryResult');
            if (qrObj instanceof Map<String, Object>) {
                queryResult = (Map<String, Object>) qrObj;
            } else {
                return null;
            }
        } else if (apiResponse.containsKey('SalesTransactionItem')) {
            queryResult = apiResponse;
        } else {
            return null;
        }

        if (!queryResult.containsKey('SalesTransactionItem')) return null;
        Object itemsObj = queryResult.get('SalesTransactionItem');
        if (itemsObj instanceof List<Object>) {
            return (List<Object>) itemsObj;
        }
        return new List<Object>{ itemsObj };
    }

    /**
     * @description Queueable that sets Quote.Mycap__c after the prehook returns.
     *              Pricing context forbids DML on Quote from inside a prehook;
     *              deferring to a Queueable lets the DML run in its own transaction.
     *              QLI field updates are handled by context writes + pricing
     *              engine write-back — no QLI DML here to avoid repricing loops.
     */
    public class MyCAPFlagApplier implements Queueable {
        private Set<Id> flagTrueIds;
        private Set<Id> flagFalseIds;

        public MyCAPFlagApplier(Set<Id> flagTrueIds, Set<Id> flagFalseIds) {
            this.flagTrueIds = flagTrueIds == null ? new Set<Id>() : flagTrueIds;
            this.flagFalseIds = flagFalseIds == null ? new Set<Id>() : flagFalseIds;
        }

        public void execute(QueueableContext ctx) {
            // QLI field updates (COLA%, audit fields) are handled entirely by
            // the prehook's context writes + the pricing engine's write-back
            // phase. Doing QLI DML here triggers a repricing cycle, which fires
            // the prehook again and creates a DML→reprice→DML loop that flashes
            // the "prices aren't up to date" banner 2-3 times before converging.
            //
            // This Queueable now ONLY handles Quote.Mycap__c — a Quote-level
            // field that cannot be written from a QLI pricing context and whose
            // DML does not trigger the pricing engine.

            // Quote.Mycap__c flag flip
            Set<Id> all = new Set<Id>();
            all.addAll(flagTrueIds);
            all.addAll(flagFalseIds);
            if (!all.isEmpty()) {
                List<Quote> toUpdate = new List<Quote>();
                for (Quote q : [SELECT Id, Mycap__c FROM Quote WHERE Id IN :all]) {
                    Boolean desired = flagTrueIds.contains(q.Id);
                    Boolean current = q.Mycap__c == true;
                    if (desired != current) {
                        toUpdate.add(new Quote(Id = q.Id, Mycap__c = desired));
                    }
                }
                if (!toUpdate.isEmpty()) {
                    Database.SaveResult[] qRes = Database.update(toUpdate, false);
                    for (Integer i = 0; i < qRes.size(); i++) {
                        if (!qRes[i].isSuccess()) {
                            for (Database.Error e : qRes[i].getErrors()) {
                                System.debug(LoggingLevel.WARN, 'MyCAP Quote update FAIL: ' + toUpdate[i].Id + ' ' + e.getStatusCode() + ' - ' + e.getMessage());
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * @description Shared builder for COLA context attribute updates. All
     *              hydration-mapped attributes only - no QLI-only fields.
     */
    private Map<String, Object> buildCOLAContextUpdate(Map<String, Object> itemWrapper, Decimal uplift, String source, Decimal unitPrice, Decimal defaultPct, String solCat, Decimal pricingTermCount) {
        return COLAUpliftCalculator.buildCOLAContextUpdate(itemWrapper, uplift, source, unitPrice, defaultPct, solCat, pricingTermCount);
    }
}

public class CurrencyCodeExtractor {

    @InvocableMethod(label='Extract Currency ISO Code' 
                     description='Extract ISO code from currency strings like "AUD - Australian Dollar"')
    public static List<Result> extractCode(List<Request> requests) {
        List<Result> results = new List<Result>();

        for (Request req : requests) {
            Result res = new Result();

            if (String.isNotBlank(req.currencyText)) {
                String trimmed = req.currencyText.trim();

                // Check if it's already just a 3-letter code
                if (trimmed.length() == 3 && trimmed.isAlpha()) {
                    res.isoCode = trimmed.toUpperCase();
                }
                // Handle format "AUD - Australian Dollar"
                else if (trimmed.contains('-')) {
                    String code = trimmed.substringBefore('-').trim();
                    if (code.length() == 3 && code.isAlpha()) {
                        res.isoCode = code.toUpperCase();
                    }
                }
                // Handle format "AUD Australian Dollar"
                else if (trimmed.contains(' ')) {
                    String code = trimmed.substringBefore(' ').trim();
                    if (code.length() == 3 && code.isAlpha()) {
                        res.isoCode = code.toUpperCase();
                    }
                }
            }

            results.add(res);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(label='Currency Text' required=true 
                          description='Text like "AUD - Australian Dollar"')
        public String currencyText;
    }

    public class Result {
        @InvocableVariable(label='ISO Code' 
                          description='3-letter ISO currency code')
        public String isoCode;
    }
}

/**
 * Invocable action that looks up exchange rates from a given currency to USD.
 *
 * Queries DatedConversionRate (Advanced Currency Management) for the given
 * ISO code and date, with CurrencyType fallback when no dated rate exists.
 * Returns the raw Salesforce ConversionRate value (the dated exchange rate
 * for the currency).
 *
 * Called from the QuoteLineItemExchangeRateTrigger to populate
 * Exchange_Rate_To_USD__c on QuoteLineItem at pricing time.
 */
public with sharing class DatedConversionRateLookup {

    @InvocableMethod(label='Get Dated Exchange Rate to USD'
                     description='Looks up the exchange rate from a given currency to USD using DatedConversionRate (ACM) with CurrencyType fallback'
                     category='Pricing')
    public static List<Result> getExchangeRates(List<Request> requests) {
        List<Result> results = new List<Result>();

        // Step 1: Default null lookupDates to today and collect unique non-USD ISO codes
        // Note: Uses the maximum lookupDate across all requests for a single SOQL query.
        // This is safe because the flow invokes this once per transaction with today's date.
        Set<String> isoCodes = new Set<String>();
        Date maxDate = System.today();

        for (Request req : requests) {
            if (req.lookupDate == null) {
                req.lookupDate = System.today();
            }
            if (req.lookupDate > maxDate) {
                maxDate = req.lookupDate;
            }
            if (String.isNotBlank(req.currencyIsoCode) && req.currencyIsoCode != 'USD') {
                isoCodes.add(req.currencyIsoCode);
            }
        }

        // Step 2: Query DatedConversionRate for all non-USD codes
        Map<String, Decimal> rateMap = new Map<String, Decimal>();

        if (!isoCodes.isEmpty()) {
            for (DatedConversionRate dcr : [
                SELECT IsoCode, ConversionRate
                FROM DatedConversionRate
                WHERE IsoCode IN :isoCodes
                AND StartDate <= :maxDate
                AND NextStartDate > :maxDate
            ]) {
                rateMap.put(dcr.IsoCode, dcr.ConversionRate);
            }

            // Step 3: Fallback to CurrencyType for any codes not found
            Set<String> missingCodes = new Set<String>();
            for (String code : isoCodes) {
                if (!rateMap.containsKey(code)) {
                    missingCodes.add(code);
                }
            }

            if (!missingCodes.isEmpty()) {
                for (CurrencyType ct : [
                    SELECT IsoCode, ConversionRate
                    FROM CurrencyType
                    WHERE IsoCode IN :missingCodes
                    AND IsActive = true
                ]) {
                    rateMap.put(ct.IsoCode, ct.ConversionRate);
                }
            }
        }

        // Step 4: Build results — return the raw SF ConversionRate
        for (Request req : requests) {
            Result res = new Result();

            if (String.isBlank(req.currencyIsoCode) || req.currencyIsoCode == 'USD') {
                res.exchangeRate = 1.0;
            } else if (rateMap.containsKey(req.currencyIsoCode)) {
                res.exchangeRate = rateMap.get(req.currencyIsoCode);
            } else {
                res.exchangeRate = null;
            }

            results.add(res);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(label='Currency ISO Code' required=true
                          description='3-letter ISO currency code (e.g., EUR, GBP, JPY)')
        public String currencyIsoCode;

        @InvocableVariable(label='Lookup Date' required=false
                          description='Date for rate lookup. Defaults to today if not provided.')
        public Date lookupDate;
    }

    public class Result {
        @InvocableVariable(label='Exchange Rate'
                          description='Dated exchange rate from DatedConversionRate or CurrencyType')
        public Decimal exchangeRate;
    }
}

/**
 * @description Service class for currency conversion operations.
 *              Provides reusable methods for querying Currency_Conversion_Formula__mdt
 *              and applying conversion formulas to prices.
 *
 *              This service is used by:
 *              - Fortra_BulkPriceUpdateBatch for bulk product price updates
 *              - Flow-based single product currency price updates
 *
 *              Formula Format: Simple arithmetic expressions like "* 0.92" or "* 1.0"
 *              The formula is applied to the USD price to get the target currency price.
 *
 * @author Marc DeBrey
 * @version 1.0
 * @since 2026-01
 */
public with sharing class Fortra_CurrencyConversionService {

    // Cached formula records to avoid repeated CMDT queries
    private static Map<String, Currency_Conversion_Formula__mdt> formulaCache;

    /**
     * @description Get all active currency conversion formulas from Custom Metadata
     *              Results are cached for the transaction to minimize SOQL queries
     * @return Map of currency formulas keyed by ISO Code (EUR, GBP, etc.)
     */
    public static Map<String, Currency_Conversion_Formula__mdt> getActiveFormulas() {
        if (formulaCache == null) {
            formulaCache = new Map<String, Currency_Conversion_Formula__mdt>();

            for (Currency_Conversion_Formula__mdt formula : [
                SELECT MasterLabel, DeveloperName, ISO_Code__c, Conversion_Formula__c,
                       Conversion_Rate__c, Is_Active__c, Description__c
                FROM Currency_Conversion_Formula__mdt
                WHERE Is_Active__c = true
            ]) {
                if (String.isNotBlank(formula.ISO_Code__c)) {
                    formulaCache.put(formula.ISO_Code__c.toUpperCase(), formula);
                }
            }

            System.debug(LoggingLevel.INFO, 'CurrencyConversionService: Loaded ' +
                formulaCache.size() + ' active currency formulas');
        }

        return formulaCache;
    }

    /**
     * @description Get the formula record for a specific currency code
     * @param currencyCode The ISO currency code (e.g., EUR, GBP)
     * @return The Currency_Conversion_Formula__mdt record or null if not found
     */
    public static Currency_Conversion_Formula__mdt getFormula(String currencyCode) {
        if (String.isBlank(currencyCode)) {
            return null;
        }

        Map<String, Currency_Conversion_Formula__mdt> formulas = getActiveFormulas();
        return formulas.get(currencyCode.toUpperCase());
    }

    /**
     * @description Convert a USD price to a target currency using the stored formula
     * @param usdPrice The price in USD
     * @param targetCurrencyCode The target currency ISO code (e.g., EUR)
     * @return The converted price, or null if conversion not possible
     */
    public static Decimal convertPrice(Decimal usdPrice, String targetCurrencyCode) {
        if (usdPrice == null || String.isBlank(targetCurrencyCode)) {
            return null;
        }

        Currency_Conversion_Formula__mdt formula = getFormula(targetCurrencyCode);
        if (formula == null) {
            System.debug(LoggingLevel.WARN, 'CurrencyConversionService: No formula found for ' +
                targetCurrencyCode);
            return null;
        }

        if (formula.Conversion_Rate__c != null) {
            return usdPrice * formula.Conversion_Rate__c;
        }

        if (String.isBlank(formula.Conversion_Formula__c)) {
            System.debug(LoggingLevel.WARN, 'CurrencyConversionService: No rate or formula for ' +
                targetCurrencyCode);
            return null;
        }

        return applyFormula(usdPrice, formula.Conversion_Formula__c);
    }

    /**
     * @description Apply a formula string to a price value
     *              Supports simple arithmetic: * (multiply), / (divide), + (add), - (subtract)
     *              Examples: "* 0.92", "* 1.0", "* 1.15"
     * @param price The input price value
     * @param formulaString The formula to apply (e.g., "* 0.92")
     * @return The calculated result, or null if formula is invalid
     */
    @TestVisible
    public static Decimal applyFormula(Decimal price, String formulaString) {
        if (price == null || String.isBlank(formulaString)) {
            return null;
        }

        String formula = formulaString.trim();

        try {
            // Parse the operator and value
            String operator = formula.substring(0, 1);
            String valueStr = formula.substring(1).trim();
            Decimal value = Decimal.valueOf(valueStr);

            Decimal result;

            switch on operator {
                when '*' {
                    result = price * value;
                }
                when '/' {
                    if (value == 0) {
                        System.debug(LoggingLevel.ERROR, 'CurrencyConversionService: Division by zero in formula');
                        return null;
                    }
                    result = price / value;
                }
                when '+' {
                    result = price + value;
                }
                when '-' {
                    result = price - value;
                }
                when else {
                    System.debug(LoggingLevel.ERROR, 'CurrencyConversionService: Unknown operator: ' + operator);
                    return null;
                }
            }

            // Round to 2 decimal places
            return result.setScale(2, System.RoundingMode.HALF_UP);

        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'CurrencyConversionService: Error applying formula "' +
                formulaString + '": ' + e.getMessage());
            return null;
        }
    }

    /**
     * @description Get a list of all active currency codes
     * @return List of ISO currency codes (e.g., ['USD', 'EUR', 'GBP'])
     */
    public static List<String> getActiveCurrencyCodes() {
        return new List<String>(getActiveFormulas().keySet());
    }

    /**
     * @description Convert a USD price to all active currencies
     * @param usdPrice The price in USD
     * @return Map of currency code to converted price
     */
    public static Map<String, Decimal> convertToAllCurrencies(Decimal usdPrice) {
        Map<String, Decimal> results = new Map<String, Decimal>();

        if (usdPrice == null) {
            return results;
        }

        for (String currencyCode : getActiveFormulas().keySet()) {
            Decimal convertedPrice = convertPrice(usdPrice, currencyCode);
            if (convertedPrice != null) {
                results.put(currencyCode, convertedPrice);
            }
        }

        return results;
    }

    /**
     * @description Clear the formula cache (useful for testing)
     */
    @TestVisible
    public static void clearCache() {
        formulaCache = null;
    }

    /**
     * @description Wrapper class for currency conversion result with metadata
     */
    public class ConversionResult {
        public String currencyCode;
        public Decimal originalPrice;
        public Decimal convertedPrice;
        public String formulaApplied;
        public Boolean success;
        public String errorMessage;

        public ConversionResult(String code, Decimal original) {
            this.currencyCode = code;
            this.originalPrice = original;
            this.success = false;
        }
    }

    /**
     * @description Convert price with detailed result including success/error info
     * @param usdPrice The USD price to convert
     * @param targetCurrencyCode The target currency code
     * @return ConversionResult with full details
     */
    public static ConversionResult convertPriceWithDetails(Decimal usdPrice, String targetCurrencyCode) {
        ConversionResult result = new ConversionResult(targetCurrencyCode, usdPrice);

        if (usdPrice == null) {
            result.errorMessage = 'USD price is null';
            return result;
        }

        if (String.isBlank(targetCurrencyCode)) {
            result.errorMessage = 'Target currency code is blank';
            return result;
        }

        Currency_Conversion_Formula__mdt formula = getFormula(targetCurrencyCode);
        if (formula == null) {
            result.errorMessage = 'No conversion formula found for ' + targetCurrencyCode;
            return result;
        }

        if (String.isBlank(formula.Conversion_Formula__c)) {
            result.errorMessage = 'Conversion formula is blank for ' + targetCurrencyCode;
            return result;
        }

        Decimal converted = applyFormula(usdPrice, formula.Conversion_Formula__c);
        if (converted == null) {
            result.errorMessage = 'Failed to apply formula: ' + formula.Conversion_Formula__c;
            return result;
        }

        result.convertedPrice = converted;
        result.formulaApplied = formula.Conversion_Formula__c;
        result.success = true;
        return result;
    }
}

/**
 * @description Apex Before Hook for Revenue Cloud pricing that applies hardware attribute-based
 *              pricing adjustments for Power products. Uses pGroup, Model, System Type, and
 *              Users Per Partition to calculate pricing multipliers.
 *
 *              Pricing Formula:
 *              Hardware_Price = List_Price × pGroup_Multiplier × UserCount_Multiplier × (1 - SystemType_Discount)
 *
 *              v3.0 Design - Override Priority:
 *              1. QuoteLineItemAttribute (user configured in Product Configurator)
 *              2. Hardware__c defaults (from linked Hardware record)
 *              3. System defaults (P20, Production, 1)
 *
 *              This allows users to override hardware defaults in the configurator while
 *              still using hardware values as fallback when attributes aren't configured.
 *
 *              Reads: ListPrice or UnitPrice, Hardware_Reference__c, SalesTransactionItemAttribute
 *              Writes: UnitPrice, Pre_Hardware_Price__c, Hardware_Price_Multiplier__c,
 *                      Hardware_Pricing_Applied__c, Hardware_Pricing_Detail__c,
 *                      pGroup_Applied__c, System_Type_Applied__c, Users_Per_Partition_Applied__c
 *
 * @author Marc DeBrey
 * @date January 2026
 *
 * @note Executes AFTER List Price lookup and BEFORE Regional/Partner Pricing in the waterfall.
 * @note Only applies to Power products or products with hardware linkage.
 *
 * @version 3.0 - Read QuoteLineItemAttribute for user overrides, fallback to Hardware__c
 */
global class HardwareAttributePricingPrehook implements RevSignaling.SignalingApexProcessor {

    // Recursion guard (normalized to the other prehooks): prevents re-entrant execution.
    private static Boolean isProcessing = false;

    // System defaults when neither user config nor hardware provides values
    private static final String DEFAULT_PGROUP = 'P20';
    private static final String DEFAULT_SYSTEM_TYPE = 'Production';
    private static final Decimal DEFAULT_USERS = 1;

    // Override-tier source labels — the three SDD-canonical values Hardware_Pricing_Source__c may
    // hold (Hardware SDD §8 Rule 5: "record which won ... Configurator | Hardware Default | System
    // Default"). The winning tier when the Product Configurator supplies the attribute is
    // 'Configurator' (NOT the legacy 'User Override', which is not an SDD-valid value).
    private static final String SOURCE_CONFIGURATOR = 'Configurator';
    private static final String SOURCE_HARDWARE = 'Hardware Default';
    private static final String SOURCE_SYSTEM = 'System Default';

    // Attribute names as they appear in Product Configurator (SalesTransactionItemAttribute)
    // These match the AttributeDefinition.DeveloperName values
    private static final String ATTR_PGROUP = 'Pgroup';
    private static final String ATTR_SERVER_TYPE = 'Server_Type';
    private static final String ATTR_USERS = 'Users';


    /**
     * @description Inner class to hold hardware pricing calculation details
     *              v3.0: Added source tracking for each attribute
     */
    @TestVisible
    private class HardwarePricingDetail {
        public String pGroup;
        public String pGroupSource;
        public String model;
        public String systemType;
        public String systemTypeSource;
        public Integer usersPerPartition;
        public String usersSource;
        public String hardwareId;
        public Decimal pGroupMultiplier;
        public Decimal userTierMultiplier;
        public Decimal systemTypeDiscount;
        public Decimal combinedMultiplier;
        public Decimal listPrice;
        public Decimal hardwareAdjustedPrice;
        public String source;
        public Datetime pricingTimestamp;

        public Map<String, Object> toMap() {
            return new Map<String, Object>{
                'pricingTimestamp' => this.pricingTimestamp != null ? this.pricingTimestamp.formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'') : null,
                'hardwareId' => this.hardwareId,
                'version' => 'v3.0',
                'attributes' => new Map<String, Object>{
                    'pGroup' => new Map<String, Object>{
                        'value' => this.pGroup,
                        'source' => this.pGroupSource
                    },
                    'model' => this.model,
                    'systemType' => new Map<String, Object>{
                        'value' => this.systemType,
                        'source' => this.systemTypeSource
                    },
                    'usersPerPartition' => new Map<String, Object>{
                        'value' => this.usersPerPartition,
                        'source' => this.usersSource
                    }
                },
                'multipliers' => new Map<String, Object>{
                    'pGroupMultiplier' => this.pGroupMultiplier,
                    'userTierMultiplier' => this.userTierMultiplier,
                    'systemTypeDiscount' => this.systemTypeDiscount,
                    'combinedMultiplier' => this.combinedMultiplier
                },
                'priceCalculation' => new Map<String, Object>{
                    'listPrice' => this.listPrice,
                    'hardwareAdjustedPrice' => this.hardwareAdjustedPrice
                },
                'source' => this.source
            };
        }
    }

    /**
     * @description Execute method called by Revenue Cloud pricing orchestration
     * @param request The transaction request containing pricing context
     * @return TransactionResponse indicating success or failure
     */
    public RevSignaling.TransactionResponse execute(RevSignaling.TransactionRequest request) {
        System.debug(LoggingLevel.INFO, '==========================================================');
        System.debug(LoggingLevel.INFO, '=== HardwareAttributePricingPrehook v3.0 START ===');
        System.debug(LoggingLevel.INFO, '=== Priority: User Config > Hardware > System Default ===');
        System.debug(LoggingLevel.INFO, '==========================================================');

        String contextId = request.ctxInstanceId;
        System.debug(LoggingLevel.INFO, 'Context ID: ' + contextId);

        String message = '';
        Integer updatedCount = 0;

        // Skip on re-entry so a context write that re-triggers pricing cannot recurse.
        if (isProcessing) {
            RevSignaling.TransactionResponse skip = new RevSignaling.TransactionResponse();
            skip.status = RevSignaling.TransactionStatus.SUCCESS;
            skip.message = 'Hardware pricing skipped (re-entrant call)';
            return skip;
        }
        isProcessing = true;

        try {
            // Create Context API instance
            Context.IndustriesContext industriesContext = new Context.IndustriesContext();

            // Query line items and process hardware pricing
            updatedCount = processLineItems(industriesContext, contextId);
            message = updatedCount + ' items updated with hardware attribute pricing';

        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error: ' + e.getMessage());
            System.debug(LoggingLevel.ERROR, 'Stack: ' + e.getStackTraceString());
            message = 'Hardware pricing completed with warnings: ' + e.getMessage();
            // D-18: surface the swallowed degrade (fire-and-forget; never throws; status unchanged).
            PricingHookLogger.logPrehook('HardwareAttributePricingPrehook', contextId, e);
        } finally {
            isProcessing = false;
        }

        System.debug(LoggingLevel.INFO, '=== HardwareAttributePricingPrehook v3.0 END ===');
        System.debug(LoggingLevel.INFO, 'Result: ' + message);

        RevSignaling.TransactionResponse response = new RevSignaling.TransactionResponse();
        response.status = RevSignaling.TransactionStatus.SUCCESS;
        response.message = message;
        return response;
    }

    /**
     * @description Process line items and apply hardware attribute pricing
     *              v3.0: Queries SalesTransactionItemAttribute for user overrides,
     *                    falls back to Hardware__c defaults, then system defaults
     * @param industriesContext Context API instance
     * @param contextId Context instance ID
     * @return Number of items updated
     */
    @TestVisible
    private Integer processLineItems(Context.IndustriesContext industriesContext, String contextId) {
        // Query for SalesTransactionItem (Quote Line Items)
        Map<String, Object> queryInput = new Map<String, Object>{
            'contextId' => contextId,
            'tags' => new List<String>{ 'SalesTransactionItem' }
        };

        Map<String, Object> queryOutput = industriesContext.queryTags(queryInput);

        // Handle nested response structure
        List<Object> rawLineItems = normalizeLineItems(queryOutput);
        if (rawLineItems == null) {
            return 0;
        }

        System.debug(LoggingLevel.INFO, 'Found ' + rawLineItems.size() + ' line items');

        // v3.0: Query configured attributes from SalesTransactionItemAttribute
        Map<String, Map<String, String>> configuredAttributesByLineItem = queryConfiguredAttributes(industriesContext, contextId);
        System.debug(LoggingLevel.INFO, 'Found configured attributes for ' + configuredAttributesByLineItem.size() + ' line items');

        // First pass - collect all Hardware IDs
        Set<Id> hardwareIds = collectHardwareIds(rawLineItems);

        // Query Hardware__c records for attribute values (fallback)
        Map<Id, Hardware__c> hardwareMap = queryHardwareRecords(hardwareIds);
        System.debug(LoggingLevel.INFO, 'Queried ' + hardwareMap.size() + ' Hardware__c records');

        // Second pass - process line items with override priority
        List<Map<String, Object>> itemNodeUpdates = buildItemUpdates(
            rawLineItems, configuredAttributesByLineItem, hardwareMap
        );

        // Submit context updates
        if (!itemNodeUpdates.isEmpty()) {
            submitContextUpdates(industriesContext, contextId, itemNodeUpdates);
        }

        return itemNodeUpdates.size();
    }

    /**
     * @description Normalize the queryTags response into a flat list of line-item nodes.
     *              Handles {queryResult:{SalesTransactionItem:[...]}}, {SalesTransactionItem:...},
     *              and the single-object-not-list shape. Returns null when no items are present
     *              (caller treats this as "0 items updated").
     * @param queryOutput Raw response map from queryTags
     * @return List of line-item node objects, or null if none found
     */
    @TestVisible
    private List<Object> normalizeLineItems(Map<String, Object> queryOutput) {
        Map<String, Object> queryResult;
        if (queryOutput.containsKey('queryResult')) {
            Object qrObj = queryOutput.get('queryResult');
            if (qrObj instanceof Map<String, Object>) {
                queryResult = (Map<String, Object>) qrObj;
            } else {
                System.debug(LoggingLevel.INFO, 'queryResult is not a Map');
                return null;
            }
        } else if (queryOutput.containsKey('SalesTransactionItem')) {
            queryResult = queryOutput;
        } else {
            System.debug(LoggingLevel.INFO, 'No SalesTransactionItem in response');
            return null;
        }

        if (!queryResult.containsKey('SalesTransactionItem')) {
            System.debug(LoggingLevel.INFO, 'No line items found');
            return null;
        }

        Object itemsObj = queryResult.get('SalesTransactionItem');
        List<Object> rawLineItems;
        if (itemsObj instanceof List<Object>) {
            rawLineItems = (List<Object>) itemsObj;
        } else {
            rawLineItems = new List<Object>{ itemsObj };
        }

        return rawLineItems;
    }

    /**
     * @description First pass - collect all Hardware__c IDs referenced by the line items.
     * @param rawLineItems Normalized list of line-item nodes
     * @return Set of Hardware__c record IDs
     */
    @TestVisible
    private Set<Id> collectHardwareIds(List<Object> rawLineItems) {
        Set<Id> hardwareIds = new Set<Id>();
        for (Object itemObj : rawLineItems) {
            Map<String, Object> itemNode = (Map<String, Object>) itemObj;
            Map<String, Object> tagMap;
            if (itemNode.containsKey('tagValue')) {
                tagMap = (Map<String, Object>) itemNode.get('tagValue');
            } else {
                tagMap = itemNode;
            }

            String hardwareIdStr = getStringFromTag(tagMap, 'Hardware_Id__c');
            if (String.isNotBlank(hardwareIdStr)) {
                try {
                    hardwareIds.add(Id.valueOf(hardwareIdStr));
                } catch (Exception e) {
                    System.debug(LoggingLevel.DEBUG, 'Invalid Hardware ID: ' + hardwareIdStr);
                }
            }
        }
        return hardwareIds;
    }

    /**
     * @description Second pass - process each line item with override priority and build the
     *              list of context node updates. Pure of any live-context dependency.
     * @param rawLineItems Normalized list of line-item nodes
     * @param configuredAttributesByLineItem Configured attributes keyed by line-item id
     * @param hardwareMap Map of Hardware__c records by ID (fallback values)
     * @return List of node-update maps (one per line item that produced an update)
     */
    @TestVisible
    private List<Map<String, Object>> buildItemUpdates(
        List<Object> rawLineItems,
        Map<String, Map<String, String>> configuredAttributesByLineItem,
        Map<Id, Hardware__c> hardwareMap
    ) {
        List<Map<String, Object>> itemNodeUpdates = new List<Map<String, Object>>();

        for (Object itemObj : rawLineItems) {
            Map<String, Object> itemNode = (Map<String, Object>) itemObj;

            // Extract tagValue and dataPath
            Map<String, Object> tagMap;
            List<Object> dataPath;

            if (itemNode.containsKey('tagValue')) {
                tagMap = (Map<String, Object>) itemNode.get('tagValue');
                dataPath = (List<Object>) itemNode.get('dataPath');
            } else {
                tagMap = itemNode;
                dataPath = new List<Object>();
            }

            // Get line item ID for attribute lookup
            String lineItemId = getLineItemIdFromDataPath(dataPath);

            // Get configured attributes for this line (may be empty)
            Map<String, String> lineConfiguredAttrs = configuredAttributesByLineItem.get(lineItemId);
            if (lineConfiguredAttrs == null) {
                lineConfiguredAttrs = new Map<String, String>();
            }

            // Process the line item with override priority
            Map<String, Object> fieldUpdate = processLineItem(tagMap, dataPath, hardwareMap, lineConfiguredAttrs);
            if (fieldUpdate != null) {
                itemNodeUpdates.add(fieldUpdate);
            }
        }

        return itemNodeUpdates;
    }

    /**
     * @description Extract line item ID from dataPath
     * @param dataPath The dataPath list from context
     * @return Line item ID or null
     */
    private String getLineItemIdFromDataPath(List<Object> dataPath) {
        if (dataPath == null || dataPath.isEmpty()) {
            return null;
        }
        // Line item ID is typically the last element
        return String.valueOf(dataPath[dataPath.size() - 1]);
    }

    /**
     * @description Query configured attributes from SalesTransactionItemAttribute
     *              Returns a map of lineItemId -> (attributeName -> attributeValue)
     * @param industriesContext Context API instance
     * @param contextId Context instance ID
     * @return Map of configured attributes by line item
     */
    private Map<String, Map<String, String>> queryConfiguredAttributes(
        Context.IndustriesContext industriesContext,
        String contextId
    ) {
        // The live queryTags call (and the parse delegation) must stay inside this try/catch so that
        // any failure swallows-and-continues with an empty map, letting processLineItems fall back to
        // Hardware/system-default pricing rather than aborting the whole interaction in execute().
        try {
            Map<String, Object> queryInput = new Map<String, Object>{
                'contextId' => contextId,
                'tags' => new List<String>{ 'SalesTransactionItemAttribute' }
            };

            Map<String, Object> queryOutput = industriesContext.queryTags(queryInput);
            return parseConfiguredAttributes(queryOutput);
        } catch (Exception e) {
            System.debug(LoggingLevel.WARN, 'Error querying configured attributes: ' + e.getMessage() + '\n' + e.getStackTraceString());
            return new Map<String, Map<String, String>>();
        }
    }

    /**
     * @description Parse the queryTags response for SalesTransactionItemAttribute into a map of
     *              lineItemId -> (attributeName -> attributeValue). Split from queryConfiguredAttributes
     *              so the parse logic can be unit-tested with a hand-built response map (the live
     *              queryTags call cannot be exercised in a unit test).
     * @param queryOutput Raw response map from queryTags
     * @return Map of configured attributes by line item
     */
    @TestVisible
    private Map<String, Map<String, String>> parseConfiguredAttributes(Map<String, Object> queryOutput) {
        Map<String, Map<String, String>> result = new Map<String, Map<String, String>>();

        try {
            // Defensive null check for queryOutput
            if (queryOutput == null) {
                System.debug(LoggingLevel.INFO, 'queryTags returned null for SalesTransactionItemAttribute');
                return result;
            }

            // Try to get queryResult - may be nested or direct
            Map<String, Object> queryResult = null;
            if (queryOutput.containsKey('queryResult')) {
                Object qrObj = queryOutput.get('queryResult');
                if (qrObj instanceof Map<String, Object>) {
                    queryResult = (Map<String, Object>) qrObj;
                }
            } else if (queryOutput.containsKey('SalesTransactionItemAttribute')) {
                // Direct response without queryResult wrapper
                queryResult = queryOutput;
            }

            if (queryResult == null) {
                System.debug(LoggingLevel.INFO, 'No queryResult for SalesTransactionItemAttribute');
                return result;
            }

            Object attrObj = queryResult.get('SalesTransactionItemAttribute');
            if (attrObj == null) {
                System.debug(LoggingLevel.INFO, 'No SalesTransactionItemAttribute in result');
                return result;
            }

            List<Object> attributeData;
            if (attrObj instanceof List<Object>) {
                attributeData = (List<Object>) attrObj;
            } else {
                attributeData = new List<Object>{ attrObj };
            }

            System.debug(LoggingLevel.INFO, 'Processing ' + attributeData.size() + ' attribute records');

            for (Object attr : attributeData) {
                if (attr == null || !(attr instanceof Map<String, Object>)) {
                    continue;
                }

                Map<String, Object> attrNode = (Map<String, Object>) attr;
                Map<String, Object> tagMap = null;
                List<Object> dataPath = null;

                if (attrNode.containsKey('tagValue')) {
                    Object tvObj = attrNode.get('tagValue');
                    if (tvObj instanceof Map<String, Object>) {
                        tagMap = (Map<String, Object>) tvObj;
                    }
                    Object dpObj = attrNode.get('dataPath');
                    if (dpObj instanceof List<Object>) {
                        dataPath = (List<Object>) dpObj;
                    }
                } else {
                    tagMap = attrNode;
                    dataPath = new List<Object>();
                }

                if (tagMap == null) {
                    continue;
                }

                // Get parent line item ID from ParentReference or dataPath
                String parentLineItemId = getStringFromTag(tagMap, 'ParentReference');
                if (String.isBlank(parentLineItemId) && dataPath != null && dataPath.size() >= 2) {
                    // Parent ID is second-to-last element in dataPath
                    parentLineItemId = String.valueOf(dataPath[dataPath.size() - 2]);
                }

                if (String.isBlank(parentLineItemId)) {
                    continue;
                }

                // Get attribute name and value
                String attrName = getStringFromTag(tagMap, 'Attribute');
                if (String.isBlank(attrName)) {
                    attrName = getStringFromTag(tagMap, 'AttributeKeyName');
                }
                String attrValue = getStringFromTag(tagMap, 'AttributeValue');

                if (String.isNotBlank(attrName) && String.isNotBlank(attrValue)) {
                    if (!result.containsKey(parentLineItemId)) {
                        result.put(parentLineItemId, new Map<String, String>());
                    }
                    result.get(parentLineItemId).put(attrName, attrValue);

                    System.debug(LoggingLevel.DEBUG, 'Attribute: ' + parentLineItemId + ' -> ' + attrName + ' = ' + attrValue);
                }
            }

        } catch (Exception e) {
            System.debug(LoggingLevel.WARN, 'Error querying configured attributes: ' + e.getMessage() + '\n' + e.getStackTraceString());
        }

        return result;
    }

    /**
     * @description Query Hardware__c records for attribute values
     * @param hardwareIds Set of Hardware__c record IDs
     * @return Map of Hardware__c records by ID
     */
    @TestVisible
    private Map<Id, Hardware__c> queryHardwareRecords(Set<Id> hardwareIds) {
        if (hardwareIds.isEmpty()) {
            return new Map<Id, Hardware__c>();
        }

        List<Hardware__c> hardwareRecords = [
            SELECT Id,
                   Name,
                   P_Group_List__c,
                   Server_Type__c,
                   Users_Per_Partition__c,
                   Model_Number__c
            FROM Hardware__c
            WHERE Id IN :hardwareIds
        ];

        return new Map<Id, Hardware__c>(hardwareRecords);
    }

    /**
     * @description Process a single line item and calculate hardware pricing
     *              v3.0: Priority - User Configured > Hardware Default > System Default
     * @param tagMap Line item data from context
     * @param dataPath Path for context update
     * @param hardwareMap Map of Hardware__c records by ID
     * @param configuredAttrs User-configured attributes from SalesTransactionItemAttribute
     * @return Map of field updates or null if not applicable
     */
    @TestVisible
    private Map<String, Object> processLineItem(
        Map<String, Object> tagMap,
        List<Object> dataPath,
        Map<Id, Hardware__c> hardwareMap,
        Map<String, String> configuredAttrs
    ) {
        // Get Hardware ID from context (this is a lookup field value)
        String hardwareIdStr = getStringFromTag(tagMap, 'Hardware_Id__c');
        String productId = getStringFromTag(tagMap, 'ProductId');

        // Check if hardware pricing should apply (need either hardware link or configured attributes)
        if (String.isBlank(hardwareIdStr) && (configuredAttrs == null || configuredAttrs.isEmpty())) {
            System.debug(LoggingLevel.INFO, 'Product ' + productId + ': No hardware linkage and no configured attributes - skipping');
            return null;
        }

        // Get Hardware__c record if available (for fallback values)
        Hardware__c hardware = null;
        Id hardwareId = null;
        if (String.isNotBlank(hardwareIdStr)) {
            try {
                hardwareId = Id.valueOf(hardwareIdStr);
                hardware = hardwareMap.get(hardwareId);
            } catch (Exception e) {
                System.debug(LoggingLevel.DEBUG, 'Invalid Hardware ID: ' + hardwareIdStr);
            }
        }

        // v3.0: Apply override priority for each attribute
        // Priority: User Configured > Hardware Default > System Default
        String pGroup;
        String pGroupSource;
        String systemType;
        String systemTypeSource;
        Decimal usersPerPartition;
        String usersSource;

        // pGroup: Check configured, then hardware, then system default
        String configuredPGroup = configuredAttrs != null ? configuredAttrs.get(ATTR_PGROUP) : null;
        if (String.isNotBlank(configuredPGroup)) {
            pGroup = configuredPGroup;
            pGroupSource = SOURCE_CONFIGURATOR;
        } else if (hardware != null && String.isNotBlank(hardware.P_Group_List__c)) {
            pGroup = hardware.P_Group_List__c;
            pGroupSource = SOURCE_HARDWARE;
        } else {
            pGroup = DEFAULT_PGROUP;
            pGroupSource = SOURCE_SYSTEM;
        }

        // Server Type: Check configured, then hardware, then system default
        String configuredServerType = configuredAttrs != null ? configuredAttrs.get(ATTR_SERVER_TYPE) : null;
        if (String.isNotBlank(configuredServerType)) {
            systemType = configuredServerType;
            systemTypeSource = SOURCE_CONFIGURATOR;
        } else if (hardware != null && String.isNotBlank(hardware.Server_Type__c)) {
            systemType = hardware.Server_Type__c;
            systemTypeSource = SOURCE_HARDWARE;
        } else {
            systemType = DEFAULT_SYSTEM_TYPE;
            systemTypeSource = SOURCE_SYSTEM;
        }

        // Users Per Partition: Check configured, then hardware, then system default
        String configuredUsers = configuredAttrs != null ? configuredAttrs.get(ATTR_USERS) : null;
        if (String.isNotBlank(configuredUsers)) {
            try {
                usersPerPartition = Decimal.valueOf(configuredUsers);
                usersSource = SOURCE_CONFIGURATOR;
            } catch (Exception e) {
                usersPerPartition = DEFAULT_USERS;
                usersSource = SOURCE_SYSTEM + ' (parse error)';
            }
        } else if (hardware != null && hardware.Users_Per_Partition__c != null) {
            usersPerPartition = hardware.Users_Per_Partition__c;
            usersSource = SOURCE_HARDWARE;
        } else {
            usersPerPartition = DEFAULT_USERS;
            usersSource = SOURCE_SYSTEM;
        }

        String model = hardware != null ? hardware.Model_Number__c : null;

        System.debug(LoggingLevel.INFO, '--- Processing Product ' + productId + ' ---');
        System.debug(LoggingLevel.INFO, '  pGroup: ' + pGroup + ' (' + pGroupSource + ')');
        System.debug(LoggingLevel.INFO, '  Server Type: ' + systemType + ' (' + systemTypeSource + ')');
        System.debug(LoggingLevel.INFO, '  Users: ' + usersPerPartition + ' (' + usersSource + ')');
        if (hardware != null) {
            System.debug(LoggingLevel.INFO, '  Hardware: ' + hardware.Name);
        }

        // Get current price from context
        Decimal listPrice = getDecimalFromTag(tagMap, 'ListPrice');
        Decimal unitPrice = getDecimalFromTag(tagMap, 'UnitPrice');
        Decimal currentPrice = listPrice != null ? listPrice : unitPrice;

        if (currentPrice == null || currentPrice <= 0) {
            System.debug(LoggingLevel.INFO, 'Product ' + productId + ': No valid price - skipping');
            return null;
        }

        System.debug(LoggingLevel.INFO, '  Price: ' + currentPrice);

        // Wave-2 hook-thinning: hardware price math extracted to HardwarePricingCalculator
        // (behavior-identical: same tables + formula, now unit-testable in isolation).
        HardwarePricingCalculator.HardwarePriceResult hardwareCalc =
            HardwarePricingCalculator.calculate(currentPrice, pGroup, usersPerPartition, systemType);
        Decimal pGroupMultiplier = hardwareCalc.pGroupMultiplier;
        Decimal userTierMultiplier = hardwareCalc.userTierMultiplier;
        Decimal systemTypeDiscount = hardwareCalc.systemTypeDiscount;
        Decimal combinedMultiplier = hardwareCalc.combinedMultiplier;
        Decimal adjustedPrice = hardwareCalc.adjustedPrice;

        // Round to 2 decimal places
        adjustedPrice = adjustedPrice.setScale(2, System.RoundingMode.HALF_UP);

        System.debug(LoggingLevel.INFO, '  pGroup Multiplier: ' + pGroupMultiplier);
        System.debug(LoggingLevel.INFO, '  User Tier Multiplier: ' + userTierMultiplier);
        System.debug(LoggingLevel.INFO, '  System Type Discount: ' + systemTypeDiscount + '%');
        System.debug(LoggingLevel.INFO, '  Combined Multiplier: ' + combinedMultiplier);
        System.debug(LoggingLevel.INFO, '  Adjusted Price: ' + adjustedPrice);

        // Build audit trail with v3.0 source tracking
        HardwarePricingDetail detail = new HardwarePricingDetail();
        detail.pGroup = pGroup;
        detail.pGroupSource = pGroupSource;
        detail.model = model;
        detail.systemType = systemType;
        detail.systemTypeSource = systemTypeSource;
        detail.usersPerPartition = usersPerPartition != null ? usersPerPartition.intValue() : null;
        detail.usersSource = usersSource;
        detail.hardwareId = hardwareId != null ? String.valueOf(hardwareId) : null;
        detail.pGroupMultiplier = pGroupMultiplier;
        detail.userTierMultiplier = userTierMultiplier;
        detail.systemTypeDiscount = systemTypeDiscount;
        detail.combinedMultiplier = combinedMultiplier;
        detail.listPrice = currentPrice;
        detail.hardwareAdjustedPrice = adjustedPrice;
        detail.source = 'Pre-Hook v3.0';
        detail.pricingTimestamp = Datetime.now();

        // Build update path (dataPath minus first element)
        List<Object> updatePath = dataPath.clone();
        if (!updatePath.isEmpty()) {
            updatePath.remove(0);
        }

        // Build attributes for context update
        List<Object> attributes = new List<Object>();

        // UnitPrice - the adjusted price for downstream pricing steps
        attributes.add(new Map<String, Object>{
            'attributeName' => 'UnitPrice',
            'attributeValue' => adjustedPrice
        });

        // Pre_Hardware_Price__c - capture original price
        attributes.add(new Map<String, Object>{
            'attributeName' => 'Pre_Hardware_Price__c',
            'attributeValue' => currentPrice
        });

        // Hardware_Price_Multiplier__c - combined multiplier
        attributes.add(new Map<String, Object>{
            'attributeName' => 'Hardware_Price_Multiplier__c',
            'attributeValue' => combinedMultiplier
        });

        // Hardware_Pricing_Applied__c - flag
        attributes.add(new Map<String, Object>{
            'attributeName' => 'Hardware_Pricing_Applied__c',
            'attributeValue' => true
        });

        // Hardware_Pricing_Source__c - dominant tier that won (SDD §8 Rule 5 priority:
        // Configurator override > Hardware defaults > System defaults). Records exactly one of the
        // three SDD-canonical values; maps the resolved per-attribute tier, does not hardcode a tier.
        String dominantSource = SOURCE_SYSTEM;
        if (pGroupSource == SOURCE_CONFIGURATOR || systemTypeSource == SOURCE_CONFIGURATOR || usersSource == SOURCE_CONFIGURATOR) {
            dominantSource = SOURCE_CONFIGURATOR;
        } else if (pGroupSource == SOURCE_HARDWARE || systemTypeSource == SOURCE_HARDWARE || usersSource == SOURCE_HARDWARE) {
            dominantSource = SOURCE_HARDWARE;
        }
        attributes.add(new Map<String, Object>{
            'attributeName' => 'Hardware_Pricing_Source__c',
            'attributeValue' => dominantSource
        });

        // pGroup_Applied__c - pGroup value used
        attributes.add(new Map<String, Object>{
            'attributeName' => 'pGroup_Applied__c',
            'attributeValue' => pGroup
        });

        // System_Type_Applied__c - system type value used
        attributes.add(new Map<String, Object>{
            'attributeName' => 'System_Type_Applied__c',
            'attributeValue' => systemType
        });

        // Users_Per_Partition_Applied__c - user count used
        attributes.add(new Map<String, Object>{
            'attributeName' => 'Users_Per_Partition_Applied__c',
            'attributeValue' => usersPerPartition
        });

        // Hardware_Pricing_Detail__c - JSON audit trail
        attributes.add(new Map<String, Object>{
            'attributeName' => 'Hardware_Pricing_Detail__c',
            'attributeValue' => JSON.serialize(detail.toMap())
        });

        // === Pricing Procedure Waterfall Visibility Tags ===

        // HardwareCalculatedPrice__c - calculated price for Assignment element
        // This is the primary value consumed by the Pricing Procedure Assignment element
        attributes.add(new Map<String, Object>{
            'attributeName' => 'HardwareCalculatedPrice__c',
            'attributeValue' => adjustedPrice
        });

        // HardwarePricingExplainer__c - human-readable text for waterfall display
        // Shows in Calculation Details when shouldShowExplExternally=true
        String explainerText = buildHardwareExplainerText(pGroup, systemType, usersPerPartition, combinedMultiplier);
        attributes.add(new Map<String, Object>{
            'attributeName' => 'HardwarePricingExplainer__c',
            'attributeValue' => explainerText
        });

        // Build node update
        Map<String, Object> nodeUpdate = new Map<String, Object>{
            'nodePath' => new Map<String, Object>{ 'dataPath' => updatePath },
            'attributes' => attributes
        };

        return nodeUpdate;
    }

