    /**
     * @description Extract string value from tag map
     */
    @TestVisible
    private String getStringFromTag(Map<String, Object> tagMap, String attributeName) {
        if (tagMap == null || !tagMap.containsKey(attributeName)) {
            return null;
        }

        Object attrObj = tagMap.get(attributeName);

        if (attrObj instanceof Map<String, Object>) {
            Map<String, Object> attrMap = (Map<String, Object>) attrObj;
            if (attrMap.containsKey('tagValue')) {
                Object value = attrMap.get('tagValue');
                return value != null ? String.valueOf(value) : null;
            }
        }

        return attrObj != null ? String.valueOf(attrObj) : null;
    }

    /**
     * @description Extract decimal value from tag map
     */
    @TestVisible
    private Decimal getDecimalFromTag(Map<String, Object> tagMap, String attributeName) {
        if (tagMap == null || !tagMap.containsKey(attributeName)) {
            return null;
        }

        try {
            Object attrObj = tagMap.get(attributeName);

            if (attrObj instanceof Map<String, Object>) {
                Map<String, Object> attrMap = (Map<String, Object>) attrObj;
                if (attrMap.containsKey('tagValue')) {
                    Object value = attrMap.get('tagValue');
                    if (value != null) {
                        return Decimal.valueOf(String.valueOf(value));
                    }
                }
            }

            if (attrObj != null) {
                return Decimal.valueOf(String.valueOf(attrObj));
            }
        } catch (Exception e) {
            System.debug(LoggingLevel.DEBUG, 'Could not parse decimal: ' + e.getMessage());
        }

        return null;
    }

    /**
     * @description Build human-readable explainer text for pricing waterfall display
     * @param pGroup The hardware group (e.g., 'P30', 'P60')
     * @param systemType The system type (Production, Staging, Test)
     * @param usersPerPartition Number of users per partition
     * @param combinedMultiplier The combined multiplier applied
     * @return Formatted explainer string for Calculation Details
     */
    @TestVisible
    private String buildHardwareExplainerText(
        String pGroup,
        String systemType,
        Decimal usersPerPartition,
        Decimal combinedMultiplier
    ) {
        List<String> parts = new List<String>();

        // Add pGroup if present
        if (String.isNotBlank(pGroup)) {
            parts.add('Group: ' + pGroup);
        }

        // Add system type if not Production (default)
        if (String.isNotBlank(systemType) && systemType != 'Production') {
            parts.add('System: ' + systemType);
        }

        // Add users per partition
        if (usersPerPartition != null && usersPerPartition > 0) {
            parts.add(usersPerPartition.setScale(0).intValue() + ' Users');
        }

        // Add multiplier if not 1.0
        if (combinedMultiplier != null && combinedMultiplier != 1.0) {
            parts.add('Mult: ' + combinedMultiplier.setScale(2));
        }

        // Build final string
        if (parts.isEmpty()) {
            return 'Hardware Attribute Pricing Applied';
        }

        return 'Hardware: ' + String.join(parts, ', ');
    }
}

/**
 * @description FORTRA-PRODUCT-018 Step 5: persists maintenance dollar decomposition
 *              (Base, Partner$, Discretionary$) onto OrderItem at quote-to-order conversion
 *              so renewal pricing can carry real dollars forward.
 */
public with sharing class MaintenanceOrderDecompositionService {

    private static final Set<String> NEW_BUSINESS_QUOTE_TYPES = new Set<String>{
        'New', 'Net-New'
    };

    @TestVisible
    private static final String MAINTENANCE_TIER_ATTRIBUTE = 'Maintenance Type Defn';

    public class Decomposition {
        public Decimal maintenanceBase;
        public Decimal partnerDiscount;
        public Decimal discretionaryDiscount;
    }

    /**
     * @description Bulk-loaded order context shared by seed / patch operations so reprice
     *              does not repeat the same SOQL in a single transaction.
     */
    @TestVisible
    public class OrderMaintenanceWork {
        public Id orderId;
        public Boolean isNewBusiness = false;
        public Order orderRecord;
        public Map<Id, Places__c> placeById = new Map<Id, Places__c>();
        public List<OrderItem> allOrderItems = new List<OrderItem>();
        public Map<Id, QuoteLineItem> qliById = new Map<Id, QuoteLineItem>();
        public Set<Id> derivedPbeIds = new Set<Id>();
        public Map<Id, String> tierByQliId = new Map<Id, String>();
    }

    /**
     * @description Loads order-line and quote-line context for one or many orders in a single SOQL batch.
     */
    @TestVisible
    public static Map<Id, OrderMaintenanceWork> loadWorkBulk(Set<Id> orderIds) {
        Map<Id, OrderMaintenanceWork> workByOrderId = new Map<Id, OrderMaintenanceWork>();
        if (orderIds == null || orderIds.isEmpty()) {
            return workByOrderId;
        }

        for (Id orderId : orderIds) {
            if (orderId == null) {
                continue;
            }
            OrderMaintenanceWork work = new OrderMaintenanceWork();
            work.orderId = orderId;
            workByOrderId.put(orderId, work);
        }
        if (workByOrderId.isEmpty()) {
            return workByOrderId;
        }

        Set<Id> resolvedOrderIds = workByOrderId.keySet();
        Map<Id, Order> ordersById = new Map<Id, Order>([
            SELECT Id, QuoteId, Quote.QuoteTypeText__c, Quote.Quote_Type__c,
                   BillToContactId, ShipToContactId,
                   Bill_To_Account__c, Ship_To_Account__c,
                   Bill_To_Address__c, Ship_To_Address__c,
                   Quote.BillToContactId, Quote.ContactId,
                   Quote.Bill_To_Place__c, Quote.Ship_To_Place__c
            FROM Order
            WHERE Id IN :resolvedOrderIds
        ]);

        Set<Id> placeIds = new Set<Id>();
        for (Order ord : ordersById.values()) {
            OrderMaintenanceWork work = workByOrderId.get(ord.Id);
            work.orderRecord = ord;
            work.isNewBusiness = isNewBusinessQuote(ord.Quote);
            if (ord.Quote?.Bill_To_Place__c != null) {
                placeIds.add(ord.Quote.Bill_To_Place__c);
            }
            if (ord.Quote?.Ship_To_Place__c != null) {
                placeIds.add(ord.Quote.Ship_To_Place__c);
            }
        }

        Map<Id, Places__c> globalPlaceById = new Map<Id, Places__c>();
        if (!placeIds.isEmpty()) {
            globalPlaceById = new Map<Id, Places__c>([
                SELECT Id, Account__c
                FROM Places__c
                WHERE Id IN :placeIds
            ]);
        }
        for (Order ord : ordersById.values()) {
            workByOrderId.get(ord.Id).placeById = buildPlaceByIdForOrder(ord, globalPlaceById);
        }

        Map<Id, List<OrderItem>> orderItemsByOrderId = new Map<Id, List<OrderItem>>();
        Set<Id> qliIds = new Set<Id>();
        Set<Id> pbeIds = new Set<Id>();
        for (OrderItem oi : [
            SELECT Id, OrderId, QuoteLineItemId, PricebookEntryId, Quantity,
                   Hardware__c, Hardware_ID__c, Partition_Record__c, Ship_To_Address__c,
                   Source_List_Price__c, ABA_Raw_Net__c, PartnerDiscountPercent
            FROM OrderItem
            WHERE OrderId IN :resolvedOrderIds
        ]) {
            if (!orderItemsByOrderId.containsKey(oi.OrderId)) {
                orderItemsByOrderId.put(oi.OrderId, new List<OrderItem>());
            }
            orderItemsByOrderId.get(oi.OrderId).add(oi);
            if (oi.QuoteLineItemId != null) {
                qliIds.add(oi.QuoteLineItemId);
            }
            if (oi.PricebookEntryId != null) {
                pbeIds.add(oi.PricebookEntryId);
            }
        }

        Map<Id, QuoteLineItem> qliById = new Map<Id, QuoteLineItem>();
        if (!qliIds.isEmpty()) {
            qliById = new Map<Id, QuoteLineItem>([
                SELECT Id, Base_Price__c, UnitPrice, NetUnitPrice, PartnerUnitPrice,
                       Fortra_Product_Type__c, Product2.Fortra_Product_Type__c, PricebookEntryId,
                       Source_List_Price__c, ABA_Raw_Net__c,
                       Prior_Partner_Discount__c, Prior_Discretionary_Discount__c,
                       COLACalculatedPrice__c, COLA_Uplift_Percent__c,
                       Hardware__c, Hardware_ID__c, Partition_Reference__c,
                       Quote.Ship_To_Place__c
                FROM QuoteLineItem
                WHERE Id IN :qliIds
            ]);
        }

        Set<Id> derivedPbeIds = loadDerivedPricebookEntryIds(pbeIds);

        Set<Id> newBusinessQliIds = new Set<Id>();
        for (Id orderId : resolvedOrderIds) {
            OrderMaintenanceWork work = workByOrderId.get(orderId);
            if (!work.isNewBusiness || !orderItemsByOrderId.containsKey(orderId)) {
                continue;
            }
            for (OrderItem oi : orderItemsByOrderId.get(orderId)) {
                if (oi.QuoteLineItemId != null) {
                    newBusinessQliIds.add(oi.QuoteLineItemId);
                }
            }
        }
        Map<Id, String> tierByQliId = loadMaintenanceTierByQliId(newBusinessQliIds);

        for (Id orderId : resolvedOrderIds) {
            OrderMaintenanceWork work = workByOrderId.get(orderId);
            work.allOrderItems = orderItemsByOrderId.containsKey(orderId)
                ? orderItemsByOrderId.get(orderId)
                : new List<OrderItem>();
            work.derivedPbeIds = derivedPbeIds;

            for (OrderItem oi : work.allOrderItems) {
                if (oi.QuoteLineItemId != null && qliById.containsKey(oi.QuoteLineItemId)) {
                    work.qliById.put(oi.QuoteLineItemId, qliById.get(oi.QuoteLineItemId));
                }
            }
            if (work.isNewBusiness) {
                for (Id qliId : work.qliById.keySet()) {
                    if (tierByQliId.containsKey(qliId)) {
                        work.tierByQliId.put(qliId, tierByQliId.get(qliId));
                    }
                }
            }
        }

        return workByOrderId;
    }

    /**
     * @description Copies Bill To / Ship To header fields from the source Quote onto the Order.
     *              Uses header data already loaded on OrderMaintenanceWork (no extra SOQL).
     */
    @TestVisible
    public static Boolean applyOrderHeaderFromWork(OrderMaintenanceWork work) {
        if (work == null || work.orderRecord == null || work.orderRecord.QuoteId == null) {
            return false;
        }

        Order ord = work.orderRecord;
        Quote sourceQuote = ord.Quote;
        if (sourceQuote == null) {
            return false;
        }

        Order patch = new Order(Id = ord.Id);
        Boolean changed = false;

        if (sourceQuote.Bill_To_Place__c != null) {
            Places__c billPlace = work.placeById.get(sourceQuote.Bill_To_Place__c);
            if (billPlace != null && billPlace.Account__c != null && ord.Bill_To_Account__c != billPlace.Account__c) {
                patch.Bill_To_Account__c = billPlace.Account__c;
                changed = true;
            }
            if (ord.Bill_To_Address__c != sourceQuote.Bill_To_Place__c) {
                patch.Bill_To_Address__c = sourceQuote.Bill_To_Place__c;
                changed = true;
            }
        }

        if (sourceQuote.Ship_To_Place__c != null) {
            Places__c shipPlace = work.placeById.get(sourceQuote.Ship_To_Place__c);
            if (shipPlace != null && shipPlace.Account__c != null && ord.Ship_To_Account__c != shipPlace.Account__c) {
                patch.Ship_To_Account__c = shipPlace.Account__c;
                changed = true;
            }
            if (ord.Ship_To_Address__c != sourceQuote.Ship_To_Place__c) {
                patch.Ship_To_Address__c = sourceQuote.Ship_To_Place__c;
                changed = true;
            }
        }

        if (sourceQuote.BillToContactId != null && ord.BillToContactId != sourceQuote.BillToContactId) {
            patch.BillToContactId = sourceQuote.BillToContactId;
            changed = true;
        }

        if (sourceQuote.ContactId != null && ord.ShipToContactId != sourceQuote.ContactId) {
            patch.ShipToContactId = sourceQuote.ContactId;
            changed = true;
        }

        if (!changed) {
            return false;
        }

        update patch;
        return true;
    }

    @TestVisible
    private static Map<Id, Places__c> buildPlaceByIdForOrder(Order ord, Map<Id, Places__c> globalPlaceById) {
        Map<Id, Places__c> placeById = new Map<Id, Places__c>();
        if (ord.Quote?.Bill_To_Place__c != null && globalPlaceById.containsKey(ord.Quote.Bill_To_Place__c)) {
            placeById.put(ord.Quote.Bill_To_Place__c, globalPlaceById.get(ord.Quote.Bill_To_Place__c));
        }
        if (ord.Quote?.Ship_To_Place__c != null && globalPlaceById.containsKey(ord.Quote.Ship_To_Place__c)) {
            placeById.put(ord.Quote.Ship_To_Place__c, globalPlaceById.get(ord.Quote.Ship_To_Place__c));
        }
        return placeById;
    }

    /**
     * @description Loads all order-line and quote-line data needed for derived maintenance
     *              seeding and decomposition in one pass.
     */
    @TestVisible
    public static OrderMaintenanceWork loadWork(Id orderId) {
        OrderMaintenanceWork work = new OrderMaintenanceWork();
        work.orderId = orderId;

        if (orderId == null) {
            return work;
        }

        Map<Id, OrderMaintenanceWork> workByOrderId = loadWorkBulk(new Set<Id>{ orderId });
        return workByOrderId.containsKey(orderId) ? workByOrderId.get(orderId) : work;
    }

    /**
     * @return OrderItem patches keyed by OrderItem Id (Id-only stubs with decomposition fields set).
     */
    public static Map<Id, OrderItem> buildPatches(Id orderId) {
        return buildPatchesFromWork(loadWork(orderId));
    }

    @TestVisible
    public static Map<Id, OrderItem> buildPatchesFromWork(OrderMaintenanceWork work) {
        Map<Id, OrderItem> patches = new Map<Id, OrderItem>();

        if (work == null || !work.isNewBusiness || work.allOrderItems.isEmpty()) {
            return patches;
        }

        for (OrderItem oi : work.allOrderItems) {
            if (oi.QuoteLineItemId == null) {
                continue;
            }

            QuoteLineItem qli = work.qliById.get(oi.QuoteLineItemId);
            if (qli == null || qli.Base_Price__c == null) {
                continue;
            }
            if (!isDerivedMaintenanceLine(work, qli, oi)) {
                continue;
            }

            Decomposition decomp = compute(
                qli.Base_Price__c,
                qli.UnitPrice,
                qli.PartnerUnitPrice,
                qli.NetUnitPrice,
                resolveTierForLine(work, qli)
            );

            if (decomp.maintenanceBase == null || decomp.maintenanceBase <= 0) {
                continue;
            }

            Decimal commercialNet = resolveNetPrice(
                qli.UnitPrice,
                qli.NetUnitPrice,
                decomp.maintenanceBase
            );
            Decimal quantity = oi.Quantity != null && oi.Quantity > 0 ? oi.Quantity : 1;

            patches.put(oi.Id, new OrderItem(
                Id = oi.Id,
                Base_Price__c = decomp.maintenanceBase,
                Prior_Partner_Discount__c = decomp.partnerDiscount,
                Prior_Discretionary_Discount__c = decomp.discretionaryDiscount,
                UnitPrice = commercialNet,
                NetUnitPrice = commercialNet,
                PartnerUnitPrice = qli.PartnerUnitPrice,
                TotalLineAmount = (commercialNet * quantity).setScale(2, RoundingMode.HALF_UP)
            ));
        }

        return patches;
    }

    /**
     * @description Persists renewal carry-forward pricing inputs from QuoteLineItem onto OrderItem
     *              at quote-to-order conversion. The stamp flow writes these onto QLI before save;
     *              standard createOrderFromQuote does not map custom carry-forward fields.
     */
    @TestVisible
    public static Map<Id, OrderItem> buildRenewalCarryForwardPatchesFromWork(OrderMaintenanceWork work) {
        Map<Id, OrderItem> patches = new Map<Id, OrderItem>();

        if (work == null || work.isNewBusiness || work.allOrderItems.isEmpty()) {
            return patches;
        }

        for (OrderItem oi : work.allOrderItems) {
            if (oi.QuoteLineItemId == null) {
                continue;
            }

            QuoteLineItem qli = work.qliById.get(oi.QuoteLineItemId);
            if (qli == null || qli.Base_Price__c == null || qli.Base_Price__c <= 0) {
                continue;
            }
            if (!isDerivedMaintenanceLine(work, qli, oi)) {
                continue;
            }

            Decimal commercialNet = resolveRenewalCommercialUnitPrice(qli);
            if (commercialNet == null || commercialNet <= 0) {
                continue;
            }

            Decimal quantity = oi.Quantity != null && oi.Quantity > 0 ? oi.Quantity : 1;
            Decimal partnerUnit = qli.PartnerUnitPrice != null && qli.PartnerUnitPrice > 0
                ? qli.PartnerUnitPrice
                : commercialNet;

            patches.put(oi.Id, new OrderItem(
                Id = oi.Id,
                Base_Price__c = qli.Base_Price__c,
                Prior_Partner_Discount__c = qli.Prior_Partner_Discount__c,
                Prior_Discretionary_Discount__c = qli.Prior_Discretionary_Discount__c,
                UnitPrice = commercialNet,
                NetUnitPrice = commercialNet,
                PartnerUnitPrice = partnerUnit,
                TotalLineAmount = (commercialNet * quantity).setScale(2, RoundingMode.HALF_UP)
            ));
        }

        return patches;
    }

    @TestVisible
    private static Boolean isNewBusinessQuote(Quote sourceQuote) {
        if (sourceQuote == null) {
            return false;
        }
        return isNewBusinessQuoteType(sourceQuote.QuoteTypeText__c)
            || isNewBusinessQuoteType(sourceQuote.Quote_Type__c);
    }

    @TestVisible
    private static Boolean isNewBusinessQuoteType(String quoteType) {
        return String.isNotBlank(quoteType) && NEW_BUSINESS_QUOTE_TYPES.contains(quoteType.trim());
    }

    @TestVisible
    private static Boolean isMaintenanceProductType(String productType) {
        return productType == 'New Maintenance' || productType == 'Renewal Maintenance';
    }

    /**
     * @description Resolves maintenance tier from stamped QLI attributes, inferring from pricing
     *              when attributes are absent so decomposition still overwrites license base.
     */
    @TestVisible
    private static String resolveTierForLine(OrderMaintenanceWork work, QuoteLineItem qli) {
        if (work != null && work.tierByQliId.containsKey(qli.Id)) {
            return work.tierByQliId.get(qli.Id);
        }
        String inferred = inferTierFromPricing(
            qli.Base_Price__c,
            qli.UnitPrice,
            qli.PartnerUnitPrice,
            qli.NetUnitPrice
        );
        return inferred != null ? inferred : 'Standard';
    }

    /**
     * @description Picks the tier whose maintenance base best fits stamped partner/commercial net.
     *              Prefers the smallest valid maintenance base >= partner unit price.
     */
    @TestVisible
    public static String inferTierFromPricing(
        Decimal sourceBase,
        Decimal unitPrice,
        Decimal partnerUnitPrice,
        Decimal netUnitPrice
    ) {
        if (sourceBase == null || sourceBase <= 0) {
            return null;
        }

        String bestTier = null;
        Decimal bestMaintenanceBase = null;
        for (String tier : new List<String>{ 'Standard', 'Professional', 'Premier' }) {
            Decomposition candidate = compute(
                sourceBase,
                unitPrice,
                partnerUnitPrice,
                netUnitPrice,
                tier
            );
            if (candidate.maintenanceBase == null || candidate.maintenanceBase <= 0) {
                continue;
            }
            if (partnerUnitPrice != null && partnerUnitPrice > 0
                && candidate.maintenanceBase < partnerUnitPrice) {
                continue;
            }

            if (bestMaintenanceBase == null || candidate.maintenanceBase < bestMaintenanceBase) {
                bestMaintenanceBase = candidate.maintenanceBase;
                bestTier = tier;
            }
        }
        return bestTier;
    }

    @TestVisible
    private static Boolean isDerivedMaintenanceLine(
        OrderMaintenanceWork work,
        QuoteLineItem qli,
        OrderItem oi
    ) {
        Id pbeId = qli.PricebookEntryId != null ? qli.PricebookEntryId : oi.PricebookEntryId;
        if (pbeId != null && work.derivedPbeIds != null && work.derivedPbeIds.contains(pbeId)) {
            return true;
        }

        if (isMaintenanceProductType(qli.Fortra_Product_Type__c)) {
            return true;
        }
        return isMaintenanceProductType(qli.Product2?.Fortra_Product_Type__c);
    }

    @TestVisible
    private static Decimal resolveRenewalCommercialUnitPrice(QuoteLineItem qli) {
        Decimal fromQuote = resolveCommercialUnitPrice(qli);
        if (fromQuote != null && fromQuote > 0) {
            return fromQuote;
        }
        if (qli.COLACalculatedPrice__c != null && qli.COLACalculatedPrice__c > 0) {
            return qli.COLACalculatedPrice__c;
        }
        if (qli.Base_Price__c == null || qli.Base_Price__c <= 0) {
            return null;
        }

        Decimal priorPartner = qli.Prior_Partner_Discount__c != null ? qli.Prior_Partner_Discount__c : 0;
        Decimal priorDisc = qli.Prior_Discretionary_Discount__c != null ? qli.Prior_Discretionary_Discount__c : 0;
        Decimal colaPct = qli.COLA_Uplift_Percent__c != null ? qli.COLA_Uplift_Percent__c : 0;
        return ((qli.Base_Price__c - priorPartner - priorDisc) * (1 + (colaPct / 100)))
            .setScale(2, RoundingMode.HALF_UP);
    }

    /**
     * @description Re-applies quote commercial net on every linked order line after reprice.
     *              Merges derived-maintenance decomposition fields when present.
     */
    @TestVisible
    public static Map<Id, OrderItem> buildCommercialPatchesFromWork(OrderMaintenanceWork work) {
        Map<Id, OrderItem> patches = new Map<Id, OrderItem>();

        if (work == null || !work.isNewBusiness || work.allOrderItems.isEmpty()) {
            return patches;
        }

        Map<Id, OrderItem> decompositionPatches = buildPatchesFromWork(work);

        for (OrderItem oi : work.allOrderItems) {
            if (oi.QuoteLineItemId == null) {
                continue;
            }

            QuoteLineItem qli = work.qliById.get(oi.QuoteLineItemId);
            if (qli == null) {
                continue;
            }

            Decimal commercialNet;
            if (qli.Fortra_Product_Type__c == 'New Maintenance'
                && (qli.NetUnitPrice == null || qli.NetUnitPrice <= 0)) {
                // SC-3346 NB-DERIVED: the quote left this New-Maintenance derived net at $0 (Amend/
                // asset-copy node). Compute it from Source List Price x maintenance rate, less the
                // partner discount - mirrors the PartnerNetPricePosthook quote-side fallback - instead
                // of inheriting the pre-discount base (qli.UnitPrice) from resolveCommercialUnitPrice.
                commercialNet = resolveNewMaintenanceNet(work, qli, oi);
            } else {
                OrderItem decompPatch = decompositionPatches.get(oi.Id);
                commercialNet = decompPatch != null && decompPatch.UnitPrice != null
                    ? decompPatch.UnitPrice
                    : resolveCommercialUnitPrice(qli);
            }
            if (commercialNet == null || commercialNet <= 0) {
                continue;
            }

            Decimal quantity = oi.Quantity != null && oi.Quantity > 0 ? oi.Quantity : 1;
            Decimal lineTotal = (commercialNet * quantity).setScale(2, RoundingMode.HALF_UP);
            Decimal partnerUnit = qli.PartnerUnitPrice != null && qli.PartnerUnitPrice > 0
                ? qli.PartnerUnitPrice
                : commercialNet;

            patches.put(oi.Id, new OrderItem(
                Id = oi.Id,
                UnitPrice = commercialNet,
                NetUnitPrice = commercialNet,
                PartnerUnitPrice = partnerUnit,
                TotalLineAmount = lineTotal
            ));
        }

        for (Id orderItemId : decompositionPatches.keySet()) {
            OrderItem decompPatch = decompositionPatches.get(orderItemId);
            if (patches.containsKey(orderItemId)) {
                OrderItem patch = patches.get(orderItemId);
                patch.Base_Price__c = decompPatch.Base_Price__c;
                patch.Prior_Partner_Discount__c = decompPatch.Prior_Partner_Discount__c;
                patch.Prior_Discretionary_Discount__c = decompPatch.Prior_Discretionary_Discount__c;
            } else {
                patches.put(orderItemId, decompPatch);
            }
        }

        return patches;
    }

    @TestVisible
    private static Decimal resolveCommercialUnitPrice(QuoteLineItem qli) {
        if (qli == null) {
            return null;
        }
        if (qli.PartnerUnitPrice != null && qli.PartnerUnitPrice > 0) {
            return qli.PartnerUnitPrice;
        }
        if (qli.UnitPrice != null && qli.UnitPrice > 0) {
            return qli.UnitPrice;
        }
        if (qli.NetUnitPrice != null && qli.NetUnitPrice > 0) {
            return qli.NetUnitPrice;
        }
        return null;
    }

    /**
     * @description SC-3346 order-side New-Maintenance net fallback. When the source quote line left the
     *              derived net at $0 (Amend/asset-copy node), compute it from Source List Price x the
     *              maintenance-tier rate, less the partner discount. Gated to New Maintenance lines.
     */
    @TestVisible
    private static Decimal resolveNewMaintenanceNet(OrderMaintenanceWork work, QuoteLineItem qli, OrderItem oi) {
        if (work == null || qli == null || qli.Fortra_Product_Type__c != 'New Maintenance') {
            return null;
        }
        String tier = work.tierByQliId != null ? work.tierByQliId.get(qli.Id) : null;
        Decimal rate = String.isNotBlank(tier) ? maintenanceRateByTier().get(tier) : null;
        if (rate == null || rate <= 0) {
            return null;
        }

        Decimal contributorNet = qli.Base_Price__c;
        Decimal pricingBase = (contributorNet != null && contributorNet > 0)
            ? contributorNet
            : qli.Source_List_Price__c;
        if (pricingBase == null || pricingBase <= 0) {
            return null;
        }

        Decimal net = (pricingBase * rate).setScale(2, RoundingMode.HALF_UP);
        if (contributorNet == null || contributorNet <= 0) {
            Decimal partnerPercent = (oi != null && oi.PartnerDiscountPercent != null) ? oi.PartnerDiscountPercent : 0;
            if (partnerPercent > 0) {
                net = (net * (1 - (partnerPercent / 100))).setScale(2, RoundingMode.HALF_UP);
            }
        }
        return net > 0 ? net : null;
    }

    private static Map<String, Decimal> rateByTierCache;

    @TestVisible
    private static Map<String, Decimal> maintenanceRateByTier() {
        if (rateByTierCache != null) {
            return rateByTierCache;
        }
        rateByTierCache = new Map<String, Decimal>();
        for (Maintenance_Rate__mdt rateRecord : [
            SELECT MaintenanceType__c, Rate__c FROM Maintenance_Rate__mdt
        ]) {
            if (String.isNotBlank(rateRecord.MaintenanceType__c) && rateRecord.Rate__c != null) {
                rateByTierCache.put(rateRecord.MaintenanceType__c, rateRecord.Rate__c);
            }
        }
        return rateByTierCache;
    }

    /**
     * @description Copies quote commercial pricing onto order lines before RCA reprice so
     *              PartnerNetPricePosthook can align TotalPrice with quote net during pricing.
     */
    public static Integer seedOrderItemsFromQuote(Id orderId) {
        return seedFromWork(loadWork(orderId));
    }

    @TestVisible
    public static Integer seedFromWork(OrderMaintenanceWork work) {
        if (work == null || !work.isNewBusiness || work.allOrderItems.isEmpty()) {
            return 0;
        }

        List<OrderItem> seeds = new List<OrderItem>();
        for (OrderItem oi : work.allOrderItems) {
            if (oi.QuoteLineItemId == null) {
                continue;
            }

            QuoteLineItem qli = work.qliById.get(oi.QuoteLineItemId);
            if (qli == null) {
                continue;
            }

            OrderItem seed = new OrderItem(Id = oi.Id);
            Boolean changed = false;

            if (qli.PartnerUnitPrice != null && qli.PartnerUnitPrice > 0) {
                seed.PartnerUnitPrice = qli.PartnerUnitPrice;
                changed = true;
            }
            if (qli.NetUnitPrice != null && qli.NetUnitPrice > 0) {
                seed.NetUnitPrice = qli.NetUnitPrice;
                seed.UnitPrice = qli.NetUnitPrice;
                changed = true;
            } else if (qli.UnitPrice != null && qli.UnitPrice > 0) {
                seed.UnitPrice = qli.UnitPrice;
                changed = true;
            }
            if (String.isNotBlank(qli.Fortra_Product_Type__c)) {
                seed.Fortra_Product_Type__c = qli.Fortra_Product_Type__c;
                changed = true;
            }

            if (changed) {
                seeds.add(seed);
            }
        }

        if (seeds.isEmpty()) {
            return 0;
        }
        update seeds;
        return seeds.size();
    }

    /**
     * @description Re-applies derived maintenance decomposition and commercial net prices.
     *              Called after order reprice so RCA Force pricing cannot leave the line total
     *              at the discount-immune maintenance base instead of the quote net.
     */
    public static Integer persistPatches(Id orderId) {
        return persistFromWork(loadWork(orderId));
    }

    @TestVisible
    public static Integer persistFromWork(OrderMaintenanceWork work) {
        Map<Id, OrderItem> patches = buildCommercialPatchesFromWork(work);
        if (patches.isEmpty()) {
            return 0;
        }
        update patches.values();
        return patches.size();
    }

    /**
     * @description Re-applies Base / Prior Partner$ / Prior Disc$ without touching UnitPrice.
     *              Use for backfill on activated orders that have Order Product Detail records.
     */
    public static Integer backfillCarryForwardFields(Id orderId) {
        Map<Id, Integer> counts = backfillCarryForwardFieldsBulk(new Set<Id>{ orderId });
        return counts.containsKey(orderId) ? counts.get(orderId) : 0;
    }

    public static Map<Id, Integer> backfillCarryForwardFieldsBulk(Set<Id> orderIds) {
        Map<Id, Integer> countsByOrderId = new Map<Id, Integer>();
        if (orderIds == null || orderIds.isEmpty()) {
            return countsByOrderId;
        }

        Map<Id, OrderMaintenanceWork> workByOrderId = loadWorkBulk(orderIds);
        // D-16: accumulate every order's patches into one list so the DML is hoisted out of the
        // per-order loop (bulk-safe for the invocable). Per-order counts are recorded before the
        // single update; patches are OrderItem-Id keyed so cross-order flattening cannot collide.
        List<OrderItem> allPatches = new List<OrderItem>();
        for (Id orderId : orderIds) {
            if (orderId == null) {
                continue;
            }
            OrderMaintenanceWork work = workByOrderId.get(orderId);
            Map<Id, OrderItem> patches = buildCarryForwardFieldPatchesFromWork(work);
            countsByOrderId.put(orderId, patches.size());
            allPatches.addAll(patches.values());
        }

        if (!allPatches.isEmpty()) {
            update allPatches;
        }
        return countsByOrderId;
    }

    @TestVisible
    public static Map<Id, OrderItem> buildCarryForwardFieldPatchesFromWork(OrderMaintenanceWork work) {
        Map<Id, OrderItem> patches = new Map<Id, OrderItem>();
        mergeCarryForwardOnlyPatches(patches, buildPatchesFromWork(work));
        mergeCarryForwardOnlyPatches(patches, buildRenewalCarryForwardPatchesFromWork(work));
        return patches;
    }

    @TestVisible
    private static void mergeCarryForwardOnlyPatches(
        Map<Id, OrderItem> target,
        Map<Id, OrderItem> additional
    ) {
        for (Id orderItemId : additional.keySet()) {
            OrderItem extra = additional.get(orderItemId);
            OrderItem patch = target.containsKey(orderItemId)
                ? target.get(orderItemId)
                : new OrderItem(Id = orderItemId);

            if (extra.Base_Price__c != null) {
                patch.Base_Price__c = extra.Base_Price__c;
            }
            if (extra.Prior_Partner_Discount__c != null) {
                patch.Prior_Partner_Discount__c = extra.Prior_Partner_Discount__c;
            }
            if (extra.Prior_Discretionary_Discount__c != null) {
                patch.Prior_Discretionary_Discount__c = extra.Prior_Discretionary_Discount__c;
            }
            target.put(orderItemId, patch);
        }
    }

    public class BackfillRequest {
        @InvocableVariable(required=true label='Order ID')
        public Id orderId;
    }

    public class BackfillResult {
        @InvocableVariable(label='Order ID')
        public Id orderId;

        @InvocableVariable(label='Items Updated')
        public Integer itemsUpdated;
    }

    @InvocableMethod(
        label='Backfill OrderItem Carry-Forward Fields'
        description='Re-applies maintenance Base / Prior Partner$ / Prior Disc$ on existing orders without changing UnitPrice'
        category='Order Management'
    )
    public static List<BackfillResult> backfillCarryForwardInvocable(List<BackfillRequest> requests) {
        List<BackfillResult> results = new List<BackfillResult>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        Set<Id> orderIds = new Set<Id>();
        for (BackfillRequest request : requests) {
            if (request != null && request.orderId != null) {
                orderIds.add(request.orderId);
            }
        }
        Map<Id, Integer> countsByOrderId = backfillCarryForwardFieldsBulk(orderIds);

        for (BackfillRequest request : requests) {
            BackfillResult result = new BackfillResult();
            if (request != null) {
                result.orderId = request.orderId;
                result.itemsUpdated = request.orderId != null
                    ? countsByOrderId.get(request.orderId)
                    : 0;
            }
            if (result.itemsUpdated == null) {
                result.itemsUpdated = 0;
            }
            results.add(result);
        }
        return results;
    }

    /**
     * @description Single-transaction reprice helper: load once, seed, return work for persist after reprice.
     */
    @TestVisible
    public static OrderMaintenanceWork prepareForReprice(Id orderId) {
        OrderMaintenanceWork work = loadWork(orderId);
        seedFromWork(work);
        return work;
    }

    @TestVisible
    private static Set<Id> loadDerivedPricebookEntryIds(Set<Id> pbeIds) {
        Set<Id> derivedPbeIds = new Set<Id>();
        if (pbeIds.isEmpty()) {
            return derivedPbeIds;
        }

        for (PriceBookEntryDerivedPrice dp : [
            SELECT PricebookEntryId
            FROM PriceBookEntryDerivedPrice
            WHERE PricebookEntryId IN :pbeIds
        ]) {
            derivedPbeIds.add(dp.PricebookEntryId);
        }
        return derivedPbeIds;
    }

    /**
     * @description QuoteLineItemAttribute.AttributeValue is not reliably filterable in SOQL;
     *              load all attributes for the lines and resolve tier in Apex.
     *              Prefer "Maintenance Type Defn" over other tier-like attributes (e.g. Feature Options).
     */
    @TestVisible
    private static Map<Id, String> loadMaintenanceTierByQliId(Set<Id> qliIds) {
        Map<Id, String> tierByQliId = new Map<Id, String>();
        if (qliIds.isEmpty()) {
            return tierByQliId;
        }

        for (QuoteLineItemAttribute qlia : [
            SELECT QuoteLineItemId, AttributeName, AttributeValue
            FROM QuoteLineItemAttribute
            WHERE QuoteLineItemId IN :qliIds
        ]) {
            String tierValue = normalizeTierValue(qlia.AttributeValue);
            if (tierValue == null) {
                continue;
            }

            if (tierByQliId.containsKey(qlia.QuoteLineItemId)) {
                if (qlia.AttributeName != MAINTENANCE_TIER_ATTRIBUTE) {
                    continue;
                }
            }

            tierByQliId.put(qlia.QuoteLineItemId, tierValue);
        }
        return tierByQliId;
    }

    @TestVisible
    private static String normalizeTierValue(String attributeValue) {
        if (String.isBlank(attributeValue)) {
            return null;
        }

        String normalized = attributeValue.trim();
        if (normalized.equalsIgnoreCase('Premier')) {
            return 'Premier';
        }
        if (normalized.equalsIgnoreCase('Standard')) {
            return 'Standard';
        }
        if (normalized.equalsIgnoreCase('Professional')) {
            return 'Professional';
        }
        return null;
    }

    /**
     * Mirrors Rev Mgmt Default Pricing V9 new-business formula tier mapping.
     */
    @TestVisible
    public static Decimal resolveTierRate(String attributeValue) {
        String tierValue = normalizeTierValue(attributeValue);
        if (tierValue == 'Premier') {
            return 0.30;
        }
        if (tierValue == 'Standard' || tierValue == 'Professional') {
            return 0.20;
        }
        return 0;
    }

    @TestVisible
    public static Decomposition compute(
        Decimal sourceBase,
        Decimal unitPrice,
        Decimal partnerUnitPrice,
        Decimal netUnitPrice,
        String tierAttributeValue
    ) {
        Decomposition result = new Decomposition();
        result.partnerDiscount = 0;
        result.discretionaryDiscount = 0;

        if (sourceBase == null || sourceBase <= 0) {
            return result;
        }

        Decimal tierRate = resolveTierRate(tierAttributeValue);
        result.maintenanceBase = (sourceBase * tierRate).setScale(2, RoundingMode.HALF_UP);

        if (result.maintenanceBase <= 0) {
            return result;
        }

        Decimal netPrice = resolveNetPrice(unitPrice, netUnitPrice, result.maintenanceBase);
        Decimal afterPartnerPrice = partnerUnitPrice != null && partnerUnitPrice > 0
            ? partnerUnitPrice
            : result.maintenanceBase;

        if (afterPartnerPrice < result.maintenanceBase) {
            result.partnerDiscount = (result.maintenanceBase - afterPartnerPrice)
                .setScale(2, RoundingMode.HALF_UP);
        }

        Decimal discretionaryBase = result.partnerDiscount > 0 ? afterPartnerPrice : result.maintenanceBase;
        if (netPrice < discretionaryBase) {
            result.discretionaryDiscount = (discretionaryBase - netPrice)
                .setScale(2, RoundingMode.HALF_UP);
        }

        return result;
    }

    @TestVisible
    private static Decimal resolveNetPrice(Decimal unitPrice, Decimal netUnitPrice, Decimal maintenanceBase) {
        if (unitPrice != null && unitPrice > 0) {
            return unitPrice;
        }
        if (netUnitPrice != null && netUnitPrice > 0) {
            return netUnitPrice;
        }
        return maintenanceBase;
    }
}

/**
 * @description Aligns OrderItem commercial unit prices before assetization so RCA copies
 *              negotiated net (TotalPrice) onto assets instead of stale NetUnitPrice from
 *              the pricing waterfall.
 *
 *              Does not call PartnerNetPricePosthook here — pricing context is already
 *              stamped during quote reprice / Q2O. Re-running the posthook at activation
 *              can gack or leave createOrUpdateAssetFromOrder stuck at ContextPersistence
 *              without spawning AssetizationAsyncJob.
 */
public with sharing class OrderCommercialNetService {

    /**
     * @description Patches order lines whose UnitPrice/NetUnitPrice are stale vs TotalPrice.
     *              Call immediately before createOrUpdateAssetFromOrder in Fortra_Assetize_Order.
     */
    public static Integer finalizeOrderForAssetization(Id orderId) {
        return patchOrderItemCommercialUnitPrices(orderId);
    }

    /**
     * @description When TotalPrice reflects commercial net but NetUnitPrice is stale (e.g.
     *              perpetual $15,300 total vs $355 unit), align unit fields before assets copy pricing.
     */
    @TestVisible
    public static Integer patchOrderItemCommercialUnitPrices(Id orderId) {
        if (orderId == null) {
            return 0;
        }

        List<OrderItem> patches = new List<OrderItem>();
        for (OrderItem oi : [
            SELECT Id, Quantity, TotalPrice, NetUnitPrice, UnitPrice
            FROM OrderItem
            WHERE OrderId = :orderId
        ]) {
            Decimal commercialUnit = resolveCommercialUnitPrice(oi);
            if (commercialUnit == null) {
                continue;
            }
            if (oi.NetUnitPrice == commercialUnit && oi.UnitPrice == commercialUnit) {
                continue;
            }
            patches.add(new OrderItem(
                Id = oi.Id,
                NetUnitPrice = commercialUnit,
                UnitPrice = commercialUnit
            ));
        }

        if (patches.isEmpty()) {
            return 0;
        }
        update patches;
        return patches.size();
    }

    @TestVisible
    public static Decimal resolveCommercialUnitPrice(OrderItem oi) {
        if (oi == null) {
            return null;
        }

        Map<String, Object> populated = oi.getPopulatedFieldsAsMap();
        if (!populated.containsKey('TotalPrice')) {
            return null;
        }

        if (oi.TotalPrice == null || oi.TotalPrice <= 0) {
            return null;
        }

        Decimal quantity = oi.Quantity != null && oi.Quantity > 0 ? oi.Quantity : 1;
        Decimal commercialUnit = (oi.TotalPrice / quantity).setScale(2, RoundingMode.HALF_UP);
        Decimal listUnit = oi.NetUnitPrice != null && oi.NetUnitPrice > 0 ? oi.NetUnitPrice : null;

        if (listUnit == null) {
            return commercialUnit;
        }

        Decimal listLineTotal = (listUnit * quantity).setScale(2, RoundingMode.HALF_UP);
        if (oi.TotalPrice != listLineTotal) {
            return commercialUnit;
        }

        return listUnit;
    }

    public class FlowInput {
        @InvocableVariable(required=true label='Order Id')
        public Id orderId;
    }

    @InvocableMethod(
        label='Finalize Order Commercial Net for Assetization'
        description='Aligns OrderItem unit prices to commercial net before createOrUpdateAssetFromOrder'
        category='Revenue'
    )
    public static void finalizeForAssetization(List<FlowInput> inputs) {
        if (inputs == null) {
            return;
        }
        for (FlowInput input : inputs) {
            if (input?.orderId != null) {
                finalizeOrderForAssetization(input.orderId);
            }
        }
    }
}

/**
 * @description Reprices an Order in place via the RCA order pricing engine
 * (commerceorders.PlaceOrderExecutor with PricingPreferenceEnum.Force — the programmatic
 * "Reprice All") so it is CompletedWithPricing before activation. Invocable for the
 * Quote-to-Order flow: call it before Activate_Order, then gate activation on the returned
 * Calculation Status / Validation Result.
 * @author Liam Jeong <liam.jeong@coastalcloud.us>
 */
public without sharing class OrderRepriceInvocable {

    public class Request {
        @InvocableVariable(required=true label='Order Id')
        public Id orderId;
    }

    public class Result {
        @InvocableVariable(label='Success') public Boolean success = false;
        @InvocableVariable(label='Calculation Status') public String calculationStatus;
        @InvocableVariable(label='Validation Result') public String validationResult;
        @InvocableVariable(label='Pricing Ready') public Boolean pricingReady = false;
        @InvocableVariable(label='Error Message') public String errorMessage;
    }

    /**
     * @description Invocable entry point that reprices each requested Order in place, returning
     * one Result per Request describing success, calculation status, validation result and
     * pricing readiness.
     * @param requests The list of Requests, each carrying the Id of an Order to reprice
     * @return A list of Results, one per input Request, in the same order
     */
    @InvocableMethod(label='Reprice Order (RCA Force)'
        description='Reprices an order in place via PlaceOrderExecutor so it is CompletedWithPricing before activation')
    public static List<Result> reprice(List<Request> requests) {
        List<Result> out = new List<Result>();
        for (Request req : requests) {
            out.add(repriceOne(req.orderId));
        }
        return out;
    }

    /**
     * @description Reprices a single Order: decomposes and persists maintenance work, patches
     * commercial unit prices, and — only when the order total does not already match the quote
     * total — applies partner net prices and runs a Force reprice through PlaceOrderExecutor,
     * then clears the validation result and reports the resulting pricing state.
     * @param orderId The Id of the Order to reprice
     * @return A Result capturing success, calculation status, validation result, pricing
     * readiness and any error message
     */
    private static Result repriceOne(Id orderId) {
        Result res = new Result();
        try {
            MaintenanceOrderDecompositionService.OrderMaintenanceWork work =
                MaintenanceOrderDecompositionService.prepareForReprice(orderId);
            MaintenanceOrderDecompositionService.persistFromWork(work);
            if (work != null && work.allOrderItems != null && !work.allOrderItems.isEmpty()) {
                OrderCommercialNetService.patchOrderItemCommercialUnitPrices(orderId);
            }

            Decimal quoteTotal = resolveQuoteTotal(orderId);
            Decimal orderTotal = resolveOrderTotal(orderId);
            Boolean totalsAlreadyMatch = totalsMatch(quoteTotal, orderTotal);

            // Quote commercial nets are already on the order — skip RCA context posthook and
            // Force reprice (the original stamp-without-reprice path).
            if (!totalsAlreadyMatch && work != null && work.allOrderItems != null && !work.allOrderItems.isEmpty()) {
                PartnerNetPricePosthook.applyNetPricesToOrder(orderId);

                List<commerceorders.RecordWithReferenceRequest> records =
                    new List<commerceorders.RecordWithReferenceRequest>();
                records.add(new commerceorders.RecordWithReferenceRequest('refOrder',
                    new commerceorders.RecordResource(Order.getSObjectType(), 'PATCH', orderId)));

                Integer i = 0;
                for (OrderItem oi : work.allOrderItems) {
                    records.add(new commerceorders.RecordWithReferenceRequest('refOI' + (i++),
                        new commerceorders.RecordResource(OrderItem.getSObjectType(), 'PATCH', oi.Id)));
                }
                commerceorders.GraphRequest graph = new commerceorders.GraphRequest('SC3308_Reprice', records);

                commerceorders.PlaceOrderResult r = commerceorders.PlaceOrderExecutor.execute(
                    graph,
                    commerceorders.PricingPreferenceEnum.Force,
                    commerceorders.ConfigurationInputEnum.Skip,
                    new commerceorders.ConfigurationOptionsInput());

                res.success = (r != null && r.success == true);
                if (!res.success && r != null) {
                    res.errorMessage = String.valueOf(r.responseError);
                    populateResultFromOrder(orderId, res);
                    return res;
                }

                MaintenanceOrderDecompositionService.persistFromWork(work);
            } else {
                res.success = true;
            }

            clearOrderValidationResult(orderId);
            populateResultFromOrder(orderId, res);
            res.pricingReady = isPricingReady(orderId, quoteTotal);
        } catch (Exception e) {
            res.success = false;
            res.errorMessage = e.getTypeName() + ': ' + e.getMessage();
            populateResultFromOrder(orderId, res);
        }
        return res;
    }

    /**
     * @description Loads the Order's calculation status and validation result and copies them
     * onto the given Result.
     * @param orderId The Id of the Order to read
     * @param res The Result to populate with the order's calculation status and validation result
     */
    @TestVisible
    private static void populateResultFromOrder(Id orderId, Result res) {
        for (Order o : [
            SELECT CalculationStatus, ValidationResult, TotalAmount
            FROM Order
            WHERE Id = :orderId
        ]) {
            res.calculationStatus = o.CalculationStatus;
            res.validationResult = o.ValidationResult;
        }
    }

    /**
     * @description Determines whether the Order is ready for activation: false if a validation
     * result is present, true if the calculation status is CompletedWithPricing, otherwise true
     * only when the order total matches the quote total.
     * @param orderId The Id of the Order to evaluate
     * @param quoteTotal The originating quote total used as a fallback comparison
     * @return True when the order is priced and ready for activation, false otherwise
     */
    @TestVisible
    private static Boolean isPricingReady(Id orderId, Decimal quoteTotal) {
        for (Order o : [
            SELECT CalculationStatus, ValidationResult, TotalAmount
            FROM Order
            WHERE Id = :orderId
        ]) {
            if (o.ValidationResult != null) {
                return false;
            }
            if (o.CalculationStatus == 'CompletedWithPricing') {
                return true;
            }
            return quoteTotal != null && totalsMatch(quoteTotal, o.TotalAmount);
        }
        return false;
    }

    /**
     * @description Returns the total price of the quote associated with the given Order, or null
     * when no quote is linked.
     * @param orderId The Id of the Order whose related quote total is requested
     * @return The related Quote's TotalPrice, or null when there is no quote
     */
    @TestVisible
    private static Decimal resolveQuoteTotal(Id orderId) {
        for (Order o : [SELECT Quote.TotalPrice FROM Order WHERE Id = :orderId LIMIT 1]) {
            return o.Quote != null ? o.Quote.TotalPrice : null;
        }
        return null;
    }

    /**
     * @description Returns the TotalAmount of the given Order, or null when the order is not found.
     * @param orderId The Id of the Order whose total amount is requested
     * @return The Order's TotalAmount, or null when the order is not found
     */
    @TestVisible
    private static Decimal resolveOrderTotal(Id orderId) {
        for (Order o : [SELECT TotalAmount FROM Order WHERE Id = :orderId LIMIT 1]) {
            return o.TotalAmount;
        }
        return null;
    }

    /**
     * @description Compares a quote total and an order total for equality at two-decimal
     * precision (HALF_UP rounding), treating null on either side as not matching.
     * @param quoteTotal The quote total to compare
     * @param orderTotal The order total to compare
     * @return True when both values are non-null and equal at two decimal places, false otherwise
     */
    @TestVisible
    private static Boolean totalsMatch(Decimal quoteTotal, Decimal orderTotal) {
        return quoteTotal != null && orderTotal != null
            && quoteTotal.setScale(2, RoundingMode.HALF_UP) == orderTotal.setScale(2, RoundingMode.HALF_UP);
    }

    /**
     * @description Clears the Order's ValidationResult by updating it to null; does nothing when
     * the supplied Id is null.
     * @param orderId The Id of the Order whose validation result should be cleared
     */
    @TestVisible
    private static void clearOrderValidationResult(Id orderId) {
        if (orderId == null) {
            return;
        }
        update new Order(Id = orderId, ValidationResult = null);
    }
}

/**
 * @description Post-pricing-procedure hook for partner net on quote/order lines.
 *
 *              Why this exists: PartnerPricingPrehookV2 runs before the pricing procedure,
 *              but Rev Mgmt Default Pricing recalculates NetUnitPrice from ListPrice and
 *              wipes pre-hook partner writes. Derived maintenance lines also have
 *              UnitPrice/ListPrice = 0 until DPP formulas run in-procedure.
 *
 *              This hook runs AFTER the procedure to:
 *              1. Stamp PartnerUnitPrice (partner-tier net from Partner_Pricing_Model__c)
 *              2. Apply deferred partner pricing on derived maintenance when needed
 *              3. Preserve procedure NetUnitPrice when it is LOWER than partner net
 *                 (ManualDiscount / ItemDiscountPercentage — discretionary discount)
 *
 *              Commercial net (NetUnitPrice / TotalPrice) = lower of procedure net vs partner net.
 *              Partner net is always stored on PartnerUnitPrice for decomposition / COLA.
 *
 * @author Coastal Cloud
 * @date June 2026
 * @version 1.4 - Apply COLA net + carry forward partner/software discount % on renewal maintenance when procedure leaves NetUnitPrice at zero
 * @version 1.7 - Commit COLACalculatedPrice__c to NetUnitPrice on renewal quotes when DPP
 *                leaves net at zero or stale (subscriptions + New Maintenance on renewal).
 */
global class PartnerNetPricePosthook implements RevSignaling.SignalingApexProcessor {

    private static final String PARTNER_SOURCE_PROCEDURE = 'System Calculated (Procedure)';

    private static final String MODEL_GUARANTEED_MARGIN = 'Guaranteed Margin';
    private static final String MODEL_DISCOUNT = 'Discount';
    private static final String CONTEXT_DEFINITION_NAME = 'SalesTransactionContextExt_v2';

    private static Boolean isProcessing = false;

    @TestVisible
    private class QuoteHeaderData {
        public Id billingPartnerId;
        public String partnerPricingModel;
        public String dealType;
        public Id resellerId;
        public Id distributorId;
        public Id referralPartnerId;

        public Boolean hasPartnerPricing() {
            return billingPartnerId != null && String.isNotBlank(partnerPricingModel);
        }
    }

    @TestVisible
    private class PartnerPriceResult {
        public Decimal currentPrice;
        public Decimal adjustedPrice;
        public Decimal totalPercent;
        public String pricingModel;
    }

    public RevSignaling.TransactionResponse execute(RevSignaling.TransactionRequest request) {
        RevSignaling.TransactionResponse response = new RevSignaling.TransactionResponse();

        if (isProcessing) {
            response.status = RevSignaling.TransactionStatus.SUCCESS;
            response.message = 'Partner net price posthook skipped - already processing';
            return response;
        }

        try {
            isProcessing = true;

            String ctxInstanceId = request.ctxInstanceId;
            if (String.isBlank(ctxInstanceId)) {
                response.status = RevSignaling.TransactionStatus.SUCCESS;
                response.message = 'Partner net price posthook skipped - no context id';
                return response;
            }

            Integer linesUpdated = applyPartnerNetPrices(ctxInstanceId);
            response.status = RevSignaling.TransactionStatus.SUCCESS;
            response.message = 'Partner net price applied to ' + linesUpdated + ' line(s)';
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'PartnerNetPricePosthook error: ' + e.getMessage());
            // D-18: surface the swallowed degrade (fire-and-forget; never throws; status unchanged).
            PricingHookLogger.logPosthook('PartnerNetPricePosthook', request != null ? request.ctxInstanceId : null, e);
            response.status = RevSignaling.TransactionStatus.SUCCESS;
            response.message = 'Partner net price posthook completed with warnings: ' + e.getMessage();
        } finally {
            isProcessing = false;
        }

        return response;
    }

    /**
     * @description After PlaceOrderExecutor, RCA context is no longer updatable in-procedure.
     *              Rebuild context from the Order, apply partner net / TotalPrice, and persist.
     */
    public static Integer applyNetPricesToOrder(Id orderId) {
        if (orderId == null) {
            return 0;
        }

        if ([SELECT COUNT() FROM OrderItem WHERE OrderId = :orderId] == 0) {
            return 0;
        }

        try {
            Context.IndustriesContext ctx = new Context.IndustriesContext();
            Map<String, Object> buildResult = ctx.buildContext(new Map<String, Object>{
                'contextDefinitionName' => CONTEXT_DEFINITION_NAME,
                'sourceRecordId' => orderId
            });

            String contextId = resolveContextId(buildResult);
            if (String.isBlank(contextId)) {
                return 0;
            }

            PartnerNetPricePosthook posthook = new PartnerNetPricePosthook();
            Integer updated = posthook.applyPartnerNetPrices(contextId);
            ctx.persistContext(new Map<String, Object>{ 'contextId' => contextId });
            return updated;
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'applyNetPricesToOrder failed: ' + e.getMessage());
            return 0;
        }
    }

    @TestVisible
    private static String resolveContextId(Map<String, Object> buildResult) {
        if (buildResult == null) {
            return null;
        }
        Object contextId = buildResult.get('contextId');
        if (contextId == null) {
            contextId = buildResult.get('contextInstanceId');
        }
        return contextId != null ? String.valueOf(contextId) : null;
    }

    @TestVisible
    private Integer applyPartnerNetPrices(String ctxInstanceId) {
        Context.IndustriesContext ctx = new Context.IndustriesContext();
        List<Map<String, Object>> lineItems = queryLineItems(ctx, ctxInstanceId);
        System.debug(LoggingLevel.ERROR, 'SC3384-DBG applyPartnerNetPrices ctxId=' + ctxInstanceId
            + ' lineItems=' + (lineItems == null ? -1 : lineItems.size()));
        if (lineItems.isEmpty()) {
            return 0;
        }

        // SC-3384: localize lines whose net was stamped by the currency-blind ABA decision table
        // (0lDa50000007BEuEAM) BEFORE the partner "lower-of" and other net rewrites, so the comparison
        // and every downstream read operate on the localized, same-currency value. Mutates the in-memory
        // tags; the per-line update below carries the write via mergeCurrencyCorrectionIntoUpdate.
        Map<Id, AbaCurrencyCorrectionService.Correction> currencyCorrections =
            applyCurrencyCorrection(lineItems);

        QuoteHeaderData quoteData = queryQuoteHeaderFromContext(ctx, ctxInstanceId);
        Map<Id, Partner_Pricing_Model__c> partnerModels = new Map<Id, Partner_Pricing_Model__c>();
        if (quoteData != null && quoteData.hasPartnerPricing()) {
            partnerModels = PartnerPricingService.getPricingModels(
                collectPartnerIds(quoteData),
                quoteData.partnerPricingModel
            );
        }

        Set<Id> lineItemIds = new Set<Id>();
        for (Map<String, Object> lineItem : lineItems) {
            Id lineItemId = getLineItemRecordId(lineItem);
            if (lineItemId != null) {
                lineItemIds.add(lineItemId);
            }
        }
        Map<Id, String> productTypeByLineId = PartnerPricingService.ensureProductTypesLoaded(
            lineItemIds,
            PartnerPricingService.loadProductTypesForTransactionLines(lineItemIds)
        );
        Map<Id, QuoteLineItem> renewalColaByLineId = loadRenewalColaLines(lineItemIds);
        Map<Id, NewMaintInputs> newMaintenanceByLineId = loadNewMaintenanceLines(lineItemIds);
        Id quoteId = resolveQuoteIdFromContextLineItems(lineItems);
        Boolean isRenewalQuote = isRenewalQuoteId(quoteId, renewalColaByLineId);
        if (quoteId != null && !isRenewalQuote) {
            newMaintenanceByLineId.putAll(loadNewMaintenanceLinesForQuote(quoteId));
        }

        List<Map<String, Object>> itemUpdates = new List<Map<String, Object>>();
        Map<Id, Map<String, Object>> contextLineById = indexContextLinesById(lineItems);

        for (Map<String, Object> lineItem : lineItems) {
            Map<String, Object> itemUpdate = buildNetPriceUpdate(
                lineItem,
                quoteData,
                partnerModels,
                productTypeByLineId,
                renewalColaByLineId,
                newMaintenanceByLineId,
                isRenewalQuote
            );
            if (itemUpdate == null) {
                itemUpdate = buildAttributeListPriceOnlyUpdate(lineItem, productTypeByLineId);
            } else {
                mergeListPriceStampIntoUpdate(itemUpdate, lineItem, productTypeByLineId);
            }
            // SC-3384: ensure ABA-corrected lines carry the localized net/unit/total (creates the write
            // for a pure-ABA line; localizes UnitPrice without clobbering a partner/COLA-owned net).
            itemUpdate = mergeCurrencyCorrectionIntoUpdate(itemUpdate, lineItem, currencyCorrections);
            if (itemUpdate != null) {
                itemUpdates.add(itemUpdate);
            }
        }

        if (quoteId != null && !isRenewalQuote && !newMaintenanceByLineId.isEmpty()) {
            itemUpdates.addAll(buildSupplementalDerivedMaintenanceUpdates(
                quoteId,
                newMaintenanceByLineId,
                contextLineById,
                itemUpdates
            ));
        }

        if (!itemUpdates.isEmpty()) {
            submitContextUpdates(ctx, ctxInstanceId, itemUpdates);
        }

        Id resolvedQuoteId = quoteId != null ? quoteId : resolveQuoteIdFromContextLineItems(lineItems);
        schedulePostPersistPriceStamp(resolvedQuoteId);

        return itemUpdates.size();
    }

    // ===== SC-3384: ABA multi-currency correction ========================================
    // The currency-blind ABA decision table (0lDa50000007BEuEAM) stamps a raw USD Override onto
    // non-USD lines. The pricing procedure snapshots that raw per-unit USD net into ABA_Raw_Net__c
    // (only on an actual ABA match), giving a provenance signal — so a correctly-localized value that
    // coincides with a USD override (the collision cohort) is never re-scaled. Here we scale the
    // snapshot by the static governed rate and localize the net/unit/total. Provenance-scoped
    // (COLA/renewal/new-maintenance lines are priced by other steps and carry no ABA snapshot).

    /** @description Test seam: inject the per-product known-USD-value set so the SOQL gate can be
     *              exercised without real data. Keyed by Product2Id; values are 2-dp plain strings. */
    @TestVisible
    private Map<Id, Set<String>> testKnownUsdValues = null;

    /**
     * @description Localize ABA-stamped raw-USD nets. Mutates the in-memory context tags to the
     *              localized, same-currency values so the partner "lower-of" and every downstream read
     *              are correct; the context write is carried by mergeCurrencyCorrectionIntoUpdate.
     *              GATED: only values that are genuinely one of the product's USD ABA overrides are
     *              localized, so a filtered-but-unmatched line (whose ABA_Raw_Net__c is a pass-through
     *              list value) is never double-localized.
     * @return map of line Id -> Correction for lines that need a localized write.
     */
    @TestVisible
    private Map<Id, AbaCurrencyCorrectionService.Correction> applyCurrencyCorrection(
        List<Map<String, Object>> lineItems
    ) {
        Map<Id, AbaCurrencyCorrectionService.Correction> corrections =
            new Map<Id, AbaCurrencyCorrectionService.Correction>();
        if (lineItems == null || lineItems.isEmpty()) {
            return corrections;
        }

        // Pass 1: collect candidates + resolve the raw net, currency, and product.
        Map<Id, Map<String, Object>> candidateById = new Map<Id, Map<String, Object>>();
        Map<Id, Decimal> rawNetById = new Map<Id, Decimal>();
        Map<Id, String> currencyById = new Map<Id, String>();
        Map<Id, Id> productById = new Map<Id, Id>();
        Set<Id> needLookup = new Set<Id>();
        for (Map<String, Object> lineItem : lineItems) {
            Id lineId = getLineItemRecordId(lineItem);
            if (lineId == null) {
                continue;
            }
            // Raw-override source. QUOTE path: NetUnitPrice is the ESD-freshly-stamped raw override on
            // every reprice — always current, so config changes are honored and a persisted ABA_Raw_Net__c
            // can never go stale. The override-set gate below confirms it is genuine. ORDER path: the ESD
            // did not re-run (NetUnitPrice may already be localized and could coincide with an override —
            // the collision cohort), so use the persisted provenance carried from the quote via convert.
            Decimal rawNet = (lineId.getSObjectType() == QuoteLineItem.SObjectType)
                ? getDecimalFromTag(lineItem, 'NetUnitPrice')
                : getDecimalFromTag(lineItem, 'ABA_Raw_Net__c');
            if (rawNet == null || rawNet <= 0) {
                continue;
            }
            candidateById.put(lineId, lineItem);
            rawNetById.put(lineId, rawNet);
            String cur = getStringFromTag(lineItem, 'STICurrencyIsoCode');
            Id prod = getIdFromTag(lineItem, 'Product');
            if (String.isNotBlank(cur)) {
                currencyById.put(lineId, cur);
            }
            if (prod != null) {
                productById.put(lineId, prod);
            }
            if (String.isBlank(cur) || prod == null) {
                needLookup.add(lineId);
            }
        }
        if (candidateById.isEmpty()) {
            return corrections;
        }

        // Fill any missing currency/product from the persisted records (currency is locked pre-pricing).
        loadLineInfo(needLookup, currencyById, productById);

        // Safety gate: localize a net only when it matches one of the product's known USD-denominated
        // values (USD ABA override, USD PBE list, or USD ATPS tier) — i.e. a raw USD price that leaked
        // onto a non-USD line. A genuinely-localized EUR net or a corrupted value matches none, so is skipped.
        Map<Id, Set<String>> knownUsdByProduct = (testKnownUsdValues != null)
            ? testKnownUsdValues
            : loadKnownUsdValues(new Set<Id>(productById.values()));

        // Pass 2: evaluate + mutate tags for genuine ABA lines that still carry the raw value.
        for (Id lineId : candidateById.keySet()) {
            Map<String, Object> lineItem = candidateById.get(lineId);
            Decimal rawNet = rawNetById.get(lineId);
            Id productId = productById.get(lineId);
            if (productId == null || !isKnownUsdValue(knownUsdByProduct.get(productId), rawNet)) {
                continue;
            }
            Decimal currentNet = getDecimalFromTag(lineItem, 'NetUnitPrice');
            Decimal quantity = getDecimalFromTag(lineItem, 'Quantity');

            AbaCurrencyCorrectionService.Correction corr =
                AbaCurrencyCorrectionService.evaluate(rawNet, currencyById.get(lineId), currentNet, quantity);
            if (!corr.writeNeeded) {
                continue;
            }
            corrections.put(lineId, corr);

            // Mutate the localized net into the in-memory tag so the partner "lower-of" and the
            // COLA/renewal builders (which all read NetUnitPrice) operate on the same-currency value.
            // The actual context write for every price field is emitted by mergeCurrencyCorrectionIntoUpdate.
            lineItem.put('NetUnitPrice', corr.localizedUnit);
        }
        return corrections;
    }

    /** @description True when rawNet matches one of the product's known USD values (2-dp compare). */
    @TestVisible
    private Boolean isKnownUsdValue(Set<String> knownUsd, Decimal rawNet) {
        return knownUsd != null && rawNet != null
            && knownUsd.contains(rawNet.setScale(2, RoundingMode.HALF_UP).toPlainString());
    }

    /**
     * @description Per-product set of the product's USD-denominated configured/list amounts (2-dp plain
     *              strings) — the ground truth for "is this net a raw USD value that should be localized".
     *              Union of: USD ABA overrides, USD PricebookEntry list prices, and USD ATPS tier values.
     *              A non-USD line whose net matches one of these carries a raw USD price (the SC-3384
     *              defect, on any pricing path) and is localized; a genuinely-localized EUR net or a
     *              corrupted value matches none and is safely skipped. Three bulk queries.
     */
    @TestVisible
    private Map<Id, Set<String>> loadKnownUsdValues(Set<Id> productIds) {
        Map<Id, Set<String>> byProduct = new Map<Id, Set<String>>();
        if (productIds != null) {
            productIds.remove(null);
        }
        if (productIds == null || productIds.isEmpty()) {
            return byProduct;
        }
        // (1) USD ABA overrides (attribute / tier / server-discount pricing).
        for (AttributeBasedAdjustment a : [
            SELECT ProductId, AdjustmentValue
            FROM AttributeBasedAdjustment
            WHERE ProductId IN :productIds AND CurrencyIsoCode = 'USD' AND AdjustmentType = 'Override'
        ]) {
            addUsdValue(byProduct, a.ProductId, a.AdjustmentValue);
        }
        // (2) USD PricebookEntry list prices (list / derived-priced lines, e.g. CCM for Servers).
        for (PricebookEntry pbe : [
            SELECT Product2Id, UnitPrice
            FROM PricebookEntry
            WHERE Product2Id IN :productIds AND CurrencyIsoCode = 'USD' AND IsActive = true AND UnitPrice > 0
        ]) {
            addUsdValue(byProduct, pbe.Product2Id, pbe.UnitPrice);
        }
        // (3) USD ATPS tier values (attribute-tier pricing).
        for (Attribute_Tier_Pricing_Storage__c t : [
            SELECT Product__c, Tier_Value__c
            FROM Attribute_Tier_Pricing_Storage__c
            WHERE Product__c IN :productIds AND CurrencyIsoCode = 'USD' AND Tier_Value__c > 0
        ]) {
            addUsdValue(byProduct, t.Product__c, t.Tier_Value__c);
        }
        return byProduct;
    }

    private void addUsdValue(Map<Id, Set<String>> byProduct, Id productId, Decimal value) {
        if (productId == null || value == null || value <= 0) {
            return;
        }
        if (!byProduct.containsKey(productId)) {
            byProduct.put(productId, new Set<String>());
        }
        byProduct.get(productId).add(value.setScale(2, RoundingMode.HALF_UP).toPlainString());
    }

    /**
     * @description Resolve CurrencyIsoCode + Product2Id for candidate lines whose context tags were
     *              absent. Currency is locked before pricing, so the persisted value is authoritative.
     *              One bulk query per object type; fills the passed maps in place (does not overwrite).
     */
    @TestVisible
    private void loadLineInfo(Set<Id> lineIds, Map<Id, String> currencyById, Map<Id, Id> productById) {
        if (lineIds == null || lineIds.isEmpty()) {
            return;
        }
        Set<Id> qliIds = new Set<Id>();
        Set<Id> orderItemIds = new Set<Id>();
        for (Id lineId : lineIds) {
            Schema.SObjectType sot = lineId.getSObjectType();
            if (sot == QuoteLineItem.SObjectType) {
                qliIds.add(lineId);
            } else if (sot == OrderItem.SObjectType) {
                orderItemIds.add(lineId);
            }
        }
        if (!qliIds.isEmpty()) {
            for (QuoteLineItem qli : [SELECT Id, CurrencyIsoCode, Product2Id FROM QuoteLineItem WHERE Id IN :qliIds]) {
                if (!currencyById.containsKey(qli.Id)) {
                    currencyById.put(qli.Id, qli.CurrencyIsoCode);
                }
                if (!productById.containsKey(qli.Id) && qli.Product2Id != null) {
                    productById.put(qli.Id, qli.Product2Id);
                }
            }
        }
        if (!orderItemIds.isEmpty()) {
            for (OrderItem oi : [SELECT Id, CurrencyIsoCode, Product2Id FROM OrderItem WHERE Id IN :orderItemIds]) {
                if (!currencyById.containsKey(oi.Id)) {
                    currencyById.put(oi.Id, oi.CurrencyIsoCode);
                }
                if (!productById.containsKey(oi.Id) && oi.Product2Id != null) {
                    productById.put(oi.Id, oi.Product2Id);
                }
            }
        }
    }

    /**
     * @description Ensure an ABA-corrected line carries its localized net/unit/total in the context
     *              write. Pure-ABA line (no partner/COLA update): emit the full localized write. Otherwise
     *              add only the fields the partner/COLA/list-stamp update did NOT already own — so the
     *              partner "lower-of" net is never clobbered, and the raw-USD Sales Price (UnitPrice) is
     *              localized. (add-if-absent: a present field was computed from the already-localized base.)
     */
    @TestVisible
    private Map<String, Object> mergeCurrencyCorrectionIntoUpdate(
        Map<String, Object> itemUpdate,
        Map<String, Object> lineItem,
        Map<Id, AbaCurrencyCorrectionService.Correction> corrections
    ) {
        if (corrections == null || corrections.isEmpty()) {
            return itemUpdate;
        }
        Id lineId = getLineItemRecordId(lineItem);
        AbaCurrencyCorrectionService.Correction corr = (lineId != null) ? corrections.get(lineId) : null;
        if (corr == null || !corr.writeNeeded) {
            return itemUpdate;
        }

        if (itemUpdate == null) {
            Object updatePath = lineItem.get('_updatePath');
            if (updatePath == null) {
                return null;
            }
            return new Map<String, Object>{
                'nodePath' => new Map<String, Object>{ 'dataPath' => updatePath },
                'attributes' => new List<Map<String, Object>>{
                    currencyAttr('NetUnitPrice', corr.localizedUnit),
                    currencyAttr('UnitPrice', corr.localizedUnit),
                    currencyAttr('NetTotalPrice', corr.localizedTotal),
                    currencyAttr('TotalPrice', corr.localizedTotal),
                    currencyAttr('Subtotal', corr.localizedTotal),
                    currencyAttr('TotalLineAmount', corr.localizedTotal),
                    // Persist the raw override as provenance so the order side (which cannot bootstrap)
                    // can localize from it after convert, and for audit.
                    currencyAttr('ABA_Raw_Net__c', corr.rawNet)
                }
            };
        }

        addAttributeIfAbsent(itemUpdate, 'NetUnitPrice', corr.localizedUnit);
        addAttributeIfAbsent(itemUpdate, 'UnitPrice', corr.localizedUnit);
        addAttributeIfAbsent(itemUpdate, 'NetTotalPrice', corr.localizedTotal);
        addAttributeIfAbsent(itemUpdate, 'TotalPrice', corr.localizedTotal);
        addAttributeIfAbsent(itemUpdate, 'Subtotal', corr.localizedTotal);
        addAttributeIfAbsent(itemUpdate, 'TotalLineAmount', corr.localizedTotal);
        addAttributeIfAbsent(itemUpdate, 'ABA_Raw_Net__c', corr.rawNet);
        return itemUpdate;
    }

    private Map<String, Object> currencyAttr(String attributeName, Object attributeValue) {
        return new Map<String, Object>{
            'attributeName' => attributeName,
            'attributeValue' => attributeValue
        };
    }

    /**
     * @description Add an attribute to an existing update only if not already present (present =>
     *              owned by partner/COLA/list-stamp, already localized via the mutated tags).
     */
    private void addAttributeIfAbsent(Map<String, Object> itemUpdate, String attributeName, Object attributeValue) {
        if (itemUpdate == null || !itemUpdate.containsKey('attributes')) {
            return;
        }
        Object attrsObj = itemUpdate.get('attributes');
        if (!(attrsObj instanceof List<Map<String, Object>>)) {
            return;
        }
        List<Map<String, Object>> attributes = (List<Map<String, Object>>) attrsObj;
        for (Map<String, Object> attribute : attributes) {
            if (attribute != null && attributeName.equals(String.valueOf(attribute.get('attributeName')))) {
                return;
            }
        }
        attributes.add(currencyAttr(attributeName, attributeValue));
    }

    /**
     * @description TLE "Reprice All" uses the signaling posthook before persist. DML stamps must run
     *              after persist commits, so enqueue a follow-up job (falls back to sync when needed).
     */
    /** @description Per-transaction guard so the post-persist stamp enqueues at most once per quote,
     *              even when both applyPartnerNetPrices and the invocable (SC-3544) schedule it. */
    private static Set<Id> scheduledStampQuoteIds = new Set<Id>();

    @TestVisible
    private static void schedulePostPersistPriceStamp(Id quoteId) {
        if (quoteId == null || scheduledStampQuoteIds.contains(quoteId)) {
            return;
        }
        scheduledStampQuoteIds.add(quoteId);

        try {
            if (System.isQueueable() || System.isBatch() || System.isFuture()) {
                PartnerNetPricePosthook.stampAttributeListPricesForQuote(quoteId);
                return;
            }
            System.enqueueJob(new QuotePriceStampQueueable(quoteId));
        } catch (Exception e) {
            System.debug(LoggingLevel.WARN, 'Post-persist price stamp enqueue failed, running sync: ' + e.getMessage());
            stampAttributeListPricesForQuote(quoteId);
        }
    }

    @TestVisible
    private Map<String, Object> buildNetPriceUpdate(Map<String, Object> lineItem) {
        return buildNetPriceUpdate(lineItem, null, null, null);
    }

    @TestVisible
    private Map<String, Object> buildNetPriceUpdate(
        Map<String, Object> lineItem,
        QuoteHeaderData quoteData,
        Map<Id, Partner_Pricing_Model__c> partnerModels
    ) {
        return buildNetPriceUpdate(lineItem, quoteData, partnerModels, null);
    }

    @TestVisible
    private Map<String, Object> buildNetPriceUpdate(
        Map<String, Object> lineItem,
        QuoteHeaderData quoteData,
        Map<Id, Partner_Pricing_Model__c> partnerModels,
        Map<Id, String> productTypeByLineId
