    /**
     * @description Clear all partner pricing fields on every line item in the context.
     *              Called when the hook determines partner pricing should NOT apply
     *              (no billing partner, no model, or no valid partner IDs) so that
     *              stale values from a previous reprice do not persist.
     * @param ctxInstanceId The context instance ID
     * @return Number of line items cleared
     */
    @TestVisible
    private Integer clearPartnerPricingFields(String ctxInstanceId) {
        Integer clearedCount = 0;

        try {
            Context.IndustriesContext ctx = new Context.IndustriesContext();

            Map<String, Object> queryInput = new Map<String, Object>{
                'contextId' => ctxInstanceId,
                'tags' => new List<String>{ 'SalesTransactionItem' }
            };

            Map<String, Object> apiResponse = ctx.queryTags(queryInput);

            if (apiResponse == null) {
                System.debug(LoggingLevel.WARN, 'queryTags returned null for clear operation');
                return 0;
            }

            // Handle nested response structure
            Map<String, Object> queryResult;
            if (apiResponse.containsKey('queryResult')) {
                Object qrObj = apiResponse.get('queryResult');
                if (qrObj instanceof Map<String, Object>) {
                    queryResult = (Map<String, Object>) qrObj;
                } else {
                    System.debug(LoggingLevel.WARN, 'queryResult is not a Map for clear operation');
                    return 0;
                }
            } else if (apiResponse.containsKey('SalesTransactionItem')) {
                queryResult = apiResponse;
            } else {
                System.debug(LoggingLevel.WARN, 'No SalesTransactionItem tag for clear operation');
                return 0;
            }

            if (!queryResult.containsKey('SalesTransactionItem')) {
                System.debug(LoggingLevel.WARN, 'SalesTransactionItem not found for clear operation');
                return 0;
            }

            Object itemsObj = queryResult.get('SalesTransactionItem');
            List<Object> rawLineItems;

            if (itemsObj instanceof List<Object>) {
                rawLineItems = (List<Object>) itemsObj;
            } else {
                rawLineItems = new List<Object>{ itemsObj };
            }

            List<Map<String, Object>> itemUpdates = new List<Map<String, Object>>();

            for (Object rawItem : rawLineItems) {
                if (rawItem instanceof Map<String, Object>) {
                    Map<String, Object> itemWrapper = (Map<String, Object>) rawItem;

                    if (itemWrapper.containsKey('dataPath')) {
                        Object dataPath = itemWrapper.get('dataPath');
                        if (dataPath instanceof List<Object>) {
                            List<Object> pathParts = (List<Object>) dataPath;
                            if (!pathParts.isEmpty()) {
                                List<Object> updatePath = pathParts.clone();
                                updatePath.remove(0);  // Remove context instance ID

                                Map<String, Object> result = new Map<String, Object>();
                                result.put('nodePath', new Map<String, Object>{ 'dataPath' => updatePath });

                                List<Map<String, Object>> attributes = new List<Map<String, Object>>();

                                // Clear all partner pricing output fields
                                for (String fieldName : new List<String>{
                                    'Pre_Partner_Price__c',
                                    'Partner_Adjusted_Price__c',
                                    'Partner_Discount_Percent__c',
                                    'Partner_Pricing_Model_Applied__c',
                                    'Partner_Pricing_Source__c',
                                    'Partner_Margin_Detail__c',
                                    'Partner_Pricing_Warning__c',
                                    'PartnerUnitPrice',
                                    'PartnerDiscountPercent'
                                }) {
                                    attributes.add(new Map<String, Object>{
                                        'attributeName' => fieldName,
                                        'attributeValue' => null
                                    });
                                }

                                result.put('attributes', attributes);
                                itemUpdates.add(result);
                                clearedCount++;
                            }
                        }
                    }
                }
            }

            if (!itemUpdates.isEmpty()) {
                System.debug(LoggingLevel.INFO, 'Clearing partner pricing fields on ' + itemUpdates.size() + ' line items');
                submitContextUpdates(ctx, ctxInstanceId, itemUpdates);
            }

        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error clearing partner pricing fields: ' + e.getMessage());
            System.debug(LoggingLevel.ERROR, 'Stack trace: ' + e.getStackTraceString());
        }

        return clearedCount;
    }

}

/**
 * @description Service class for Partner Pricing business logic.
 *              Provides reusable methods for pricing calculations, model validation,
 *              and partner pricing configuration management.
 * @author Marc DeBrey
 * @date December 2025
 */
public without sharing class PartnerPricingService {
    /**
     * @description Gets the Partner Pricing Model record for a specific partner and model type
     * @param partnerId The Account ID of the partner
     * @param modelType The model type ("Guaranteed Margin" or "Discount")
     * @return Partner_Pricing_Model__c record or null if not found
     */
    public static Partner_Pricing_Model__c getPricingModel(Id partnerId, String modelType) {
        if (partnerId == null || String.isBlank(modelType)) {
            return null;
        }

        List<Partner_Pricing_Model__c> models = [
            SELECT Id, Account__c, Model_Type__c, Is_Active__c, Is_Default__c,
                   Software_Percent__c, New_Maintenance_Percent__c, Renewal_Maintenance_Percent__c,
                   Subscription_Percent__c, Services_Percent__c,
                   Non_Orig_Software_Pct__c, Non_Orig_New_Maint_Pct__c, Non_Orig_Ren_Maint_Pct__c,
                   Non_Orig_Subscription_Pct__c, Non_Orig_Services_Pct__c,
                   Effective_Start_Date__c, Effective_End_Date__c
            FROM Partner_Pricing_Model__c
            WHERE Account__c = :partnerId
            AND Model_Type__c = :modelType
            AND Is_Active__c = true
            AND (Effective_Start_Date__c = null OR Effective_Start_Date__c <= TODAY)
            AND (Effective_End_Date__c = null OR Effective_End_Date__c >= TODAY)
            LIMIT 1
        ];

        return models.isEmpty() ? null : models[0];
    }

    /**
     * @description Gets partner pricing models for multiple partners (bulk operation)
     * @param partnerIds Set of Account IDs
     * @param modelType The model type to retrieve
     * @return Map of Account ID to Partner_Pricing_Model__c
     */
    public static Map<Id, Partner_Pricing_Model__c> getPricingModels(Set<Id> partnerIds, String modelType) {
        Map<Id, Partner_Pricing_Model__c> modelsByPartner = new Map<Id, Partner_Pricing_Model__c>();

        if (partnerIds == null || partnerIds.isEmpty() || String.isBlank(modelType)) {
            return modelsByPartner;
        }

        for (Partner_Pricing_Model__c model : [
            SELECT Id, Account__c, Model_Type__c, Is_Active__c, Is_Default__c,
                   Software_Percent__c, New_Maintenance_Percent__c, Renewal_Maintenance_Percent__c,
                   Subscription_Percent__c, Services_Percent__c,
                   Non_Orig_Software_Pct__c, Non_Orig_New_Maint_Pct__c, Non_Orig_Ren_Maint_Pct__c,
                   Non_Orig_Subscription_Pct__c, Non_Orig_Services_Pct__c,
                   Effective_Start_Date__c, Effective_End_Date__c
            FROM Partner_Pricing_Model__c
            WHERE Account__c IN :partnerIds
            AND Model_Type__c = :modelType
            AND Is_Active__c = true
            AND (Effective_Start_Date__c = null OR Effective_Start_Date__c <= TODAY)
            AND (Effective_End_Date__c = null OR Effective_End_Date__c >= TODAY)
        ]) {
            modelsByPartner.put(model.Account__c, model);
        }

        return modelsByPartner;
    }

    /**
     * @description Resolve Fortra product type for partner margin selection.
     *              Uses the context value when present; otherwise falls back to the
     *              QuoteLineItem field and then Product2 (derived maintenance lines
     *              often have a null line-level copy).
     */
    public static String resolveProductType(String contextProductType, Id quoteLineItemId) {
        if (String.isNotBlank(contextProductType)) {
            return contextProductType;
        }

        if (quoteLineItemId != null) {
            for (QuoteLineItem qli : [
                SELECT Fortra_Product_Type__c, Product2.Fortra_Product_Type__c
                FROM QuoteLineItem
                WHERE Id = :quoteLineItemId
                LIMIT 1
            ]) {
                if (String.isNotBlank(qli.Fortra_Product_Type__c)) {
                    return qli.Fortra_Product_Type__c;
                }
                if (String.isNotBlank(qli.Product2.Fortra_Product_Type__c)) {
                    return qli.Product2.Fortra_Product_Type__c;
                }
            }
        }

        return 'Software';
    }

    /**
     * @description Bulk-load product types for quote lines (avoids per-line SOQL in posthooks).
     */
    public static Map<Id, String> loadProductTypesForLines(Set<Id> quoteLineItemIds) {
        Map<Id, String> productTypeByLineId = new Map<Id, String>();

        if (quoteLineItemIds == null || quoteLineItemIds.isEmpty()) {
            return productTypeByLineId;
        }

        Map<Id, Id> product2IdByLineId = new Map<Id, Id>();
        for (QuoteLineItem qli : [
            SELECT Id, Product2Id, Fortra_Product_Type__c, Product2.Fortra_Product_Type__c
            FROM QuoteLineItem
            WHERE Id IN :quoteLineItemIds
        ]) {
            String productType = String.isNotBlank(qli.Fortra_Product_Type__c)
                ? qli.Fortra_Product_Type__c
                : qli.Product2.Fortra_Product_Type__c;
            if (String.isNotBlank(productType)) {
                productTypeByLineId.put(qli.Id, productType);
            } else if (qli.Product2Id != null) {
                product2IdByLineId.put(qli.Id, qli.Product2Id);
            }
        }

        if (!product2IdByLineId.isEmpty()) {
            Map<Id, Product2> productById = new Map<Id, Product2>([
                SELECT Id, Fortra_Product_Type__c
                FROM Product2
                WHERE Id IN :product2IdByLineId.values()
            ]);
            for (Id qliId : product2IdByLineId.keySet()) {
                Product2 prod = productById.get(product2IdByLineId.get(qliId));
                if (prod != null && String.isNotBlank(prod.Fortra_Product_Type__c)) {
                    productTypeByLineId.put(qliId, prod.Fortra_Product_Type__c);
                }
            }
        }

        return productTypeByLineId;
    }

    /**
     * @description Bulk-load product types keyed by transaction line record Id (QuoteLineItem or OrderItem).
     */
    public static Map<Id, String> loadProductTypesForTransactionLines(Set<Id> lineRecordIds) {
        Map<Id, String> productTypeByLineId = loadProductTypesForLines(lineRecordIds);

        if (lineRecordIds == null || lineRecordIds.isEmpty()) {
            return productTypeByLineId;
        }

        Set<Id> unresolvedOrderItemIds = new Set<Id>();
        for (Id lineRecordId : lineRecordIds) {
            if (!productTypeByLineId.containsKey(lineRecordId)) {
                unresolvedOrderItemIds.add(lineRecordId);
            }
        }
        if (unresolvedOrderItemIds.isEmpty()) {
            return productTypeByLineId;
        }

        Set<Id> quoteLineItemIds = new Set<Id>();
        Map<Id, Id> orderItemIdByQliId = new Map<Id, Id>();

        for (OrderItem oi : [
            SELECT Id, QuoteLineItemId, Fortra_Product_Type__c, Product2.Fortra_Product_Type__c
            FROM OrderItem
            WHERE Id IN :unresolvedOrderItemIds
        ]) {
            String productType = String.isNotBlank(oi.Fortra_Product_Type__c)
                ? oi.Fortra_Product_Type__c
                : oi.Product2.Fortra_Product_Type__c;
            if (String.isNotBlank(productType)) {
                productTypeByLineId.put(oi.Id, productType);
                continue;
            }
            if (oi.QuoteLineItemId != null) {
                quoteLineItemIds.add(oi.QuoteLineItemId);
                orderItemIdByQliId.put(oi.QuoteLineItemId, oi.Id);
            }
        }

        if (!quoteLineItemIds.isEmpty()) {
            Map<Id, String> productTypeByQliId = loadProductTypesForLines(quoteLineItemIds);
            for (Id qliId : productTypeByQliId.keySet()) {
                Id orderItemId = orderItemIdByQliId.get(qliId);
                if (orderItemId != null) {
                    productTypeByLineId.put(orderItemId, productTypeByQliId.get(qliId));
                }
            }
        }

        return productTypeByLineId;
    }

    /**
     * @description Batch-resolves any line ids missing from a pre-loaded product type map.
     *              Call once before per-line resolveProductType(..., map) to avoid N fallback SOQL.
     */
    public static Map<Id, String> ensureProductTypesLoaded(
        Set<Id> lineRecordIds,
        Map<Id, String> productTypeByLineId
    ) {
        if (productTypeByLineId == null) {
            productTypeByLineId = new Map<Id, String>();
        }
        if (lineRecordIds == null || lineRecordIds.isEmpty()) {
            return productTypeByLineId;
        }

        Set<Id> missingIds = new Set<Id>();
        for (Id lineRecordId : lineRecordIds) {
            if (lineRecordId != null && !productTypeByLineId.containsKey(lineRecordId)) {
                missingIds.add(lineRecordId);
            }
        }
        if (missingIds.isEmpty()) {
            return productTypeByLineId;
        }

        productTypeByLineId.putAll(loadProductTypesForTransactionLines(missingIds));
        return productTypeByLineId;
    }

    /**
     * @description Resolve product type using an optional bulk-loaded map from loadProductTypesForLines.
     *              On map miss, falls through to the single-arg overload (QLI field + Product2 lookup).
     */
    public static String resolveProductType(
        String contextProductType,
        Id quoteLineItemId,
        Map<Id, String> productTypeByLineId
    ) {
        if (String.isNotBlank(contextProductType)) {
            return contextProductType;
        }

        if (quoteLineItemId != null && productTypeByLineId != null) {
            if (productTypeByLineId.containsKey(quoteLineItemId)) {
                return productTypeByLineId.get(quoteLineItemId);
            }
            return resolveProductType(contextProductType, quoteLineItemId);
        }

        return resolveProductType(contextProductType, quoteLineItemId);
    }

    /**
     * @description Gets the margin percentage for a specific product type from a pricing model
     * @param model The Partner Pricing Model record
     * @param productType The Fortra_Product_Type__c value (e.g., "Software", "Subscription")
     * @return Decimal percentage (e.g., 15.00 for 15%)
     */
    public static Decimal getMarginForProductType(Partner_Pricing_Model__c model, String productType) {
        // Wave-3a consolidation: the single margin implementation lives in PartnerPricingServiceV2.
        // Passing dealType=null keeps this (deal-blind) 2-arg method behavior-identical — V2 with a
        // non-'Fortra Originated' dealType reads the same standard percent fields with the same null->0
        // and shares the same null-model / blank-type guard.
        return PartnerPricingServiceV2.getMarginForProductType(model, productType, null);
    }

    /**
     * @description Calculate Guaranteed Margin price using ADDITIVE formula.
     *              Formula: List Price x (1 - SUM(all partner margins%))
     *              Example: $1000 with margins [15%, 10%] = $1000 × (1 - 0.25) = $750
     * @param listPrice Original list price
     * @param partnerMargins List of margin percentages from all partners (as decimals, e.g., 15 for 15%)
     * @return Adjusted price after all margins applied
     */
    public static Decimal calculateGuaranteedMarginPrice(Decimal listPrice, List<Decimal> partnerMargins) {
        if (listPrice == null || listPrice <= 0) {
            return listPrice;
        }

        if (partnerMargins == null || partnerMargins.isEmpty()) {
            return listPrice;
        }

        // SUM all margins (ADDITIVE approach)
        Decimal totalMarginPercent = 0;
        for (Decimal marginPercent : partnerMargins) {
            if (marginPercent != null && marginPercent > 0) {
                totalMarginPercent += marginPercent;
            }
        }

        // Cap at 100% to avoid negative prices
        if (totalMarginPercent > 100) {
            totalMarginPercent = 100;
        }

        // Apply: Price × (1 - totalMargin%)
        Decimal multiplier = 1 - (totalMarginPercent / 100);
        return (listPrice * multiplier).setScale(2, RoundingMode.HALF_UP);
    }

    /**
     * @description Calculate Discount Model price
     *              Formula: List Price x (1 - Billing Partner's Discount%)
     * @param listPrice Original list price
     * @param discountPercent Billing partner's discount percentage (as decimal, e.g., 20 for 20%)
     * @return Adjusted price after discount applied
     */
    public static Decimal calculateDiscountPrice(Decimal listPrice, Decimal discountPercent) {
        if (listPrice == null || listPrice <= 0) {
            return listPrice;
        }

        if (discountPercent == null || discountPercent <= 0) {
            return listPrice;
        }

        Decimal multiplier = 1 - (discountPercent / 100);
        return (listPrice * multiplier).setScale(2, RoundingMode.HALF_UP);
    }

    private static final String MODEL_GUARANTEED_MARGIN = 'Guaranteed Margin';
    private static final String MODEL_DISCOUNT = 'Discount';

    /**
     * @description Resolve total partner discount percent for a line from Partner_Pricing_Model__c
     *              records. Discount model uses billing partner only; Guaranteed Margin sums all partners.
     */
    public static Decimal resolveTotalPartnerPercent(
        String partnerPricingModel,
        Id billingPartnerId,
        Map<Id, Partner_Pricing_Model__c> partnerModels,
        String productType
    ) {
        if (String.isBlank(partnerPricingModel) || partnerModels == null || partnerModels.isEmpty()) {
            return null;
        }

        if (partnerPricingModel == MODEL_DISCOUNT) {
            Partner_Pricing_Model__c billingModel = partnerModels.get(billingPartnerId);
            if (billingModel == null) {
                return null;
            }
            Decimal discountPercent = getMarginForProductType(billingModel, productType);
            return (discountPercent != null && discountPercent > 0) ? discountPercent : null;
        }

        if (partnerPricingModel == MODEL_GUARANTEED_MARGIN) {
            Decimal totalPercent = 0;
            for (Partner_Pricing_Model__c model : partnerModels.values()) {
                Decimal margin = getMarginForProductType(model, productType);
                if (margin != null && margin > 0) {
                    totalPercent += margin;
                }
            }
            return totalPercent > 0 ? totalPercent : null;
        }

        return null;
    }

    /**
     * @description Build JSON audit detail for partner margin breakdown on a line.
     */
    public static String buildPartnerMarginDetailJson(
        String partnerPricingModel,
        Id billingPartnerId,
        Id resellerId,
        Id distributorId,
        Id referralPartnerId,
        Map<Id, Partner_Pricing_Model__c> partnerModels,
        Map<Id, String> partnerNames,
        String productType
    ) {
        if (partnerModels == null || partnerModels.isEmpty()) {
            return null;
        }

        List<Map<String, Object>> detailMaps = new List<Map<String, Object>>();

        if (partnerPricingModel == MODEL_DISCOUNT) {
            Partner_Pricing_Model__c billingModel = partnerModels.get(billingPartnerId);
            if (billingModel != null) {
                Decimal margin = getMarginForProductType(billingModel, productType);
                if (margin != null && margin > 0) {
                    detailMaps.add(new Map<String, Object>{
                        'partnerId' => billingPartnerId,
                        'partnerName' => partnerNames != null ? partnerNames.get(billingPartnerId) : null,
                        'partnerRole' => 'Billing Partner',
                        'marginPercent' => margin
                    });
                }
            }
        } else if (partnerPricingModel == MODEL_GUARANTEED_MARGIN) {
            for (Id partnerId : partnerModels.keySet()) {
                Partner_Pricing_Model__c model = partnerModels.get(partnerId);
                Decimal margin = getMarginForProductType(model, productType);
                if (margin != null && margin > 0) {
                    detailMaps.add(new Map<String, Object>{
                        'partnerId' => partnerId,
                        'partnerName' => partnerNames != null ? partnerNames.get(partnerId) : null,
                        'partnerRole' => resolvePartnerRole(
                            partnerId, billingPartnerId, resellerId, distributorId, referralPartnerId
                        ),
                        'marginPercent' => margin
                    });
                }
            }
        }

        return detailMaps.isEmpty() ? null : JSON.serialize(detailMaps);
    }

    public static String resolvePartnerRole(
        Id partnerId,
        Id billingPartnerId,
        Id resellerId,
        Id distributorId,
        Id referralPartnerId
    ) {
        if (partnerId == billingPartnerId) {
            return 'Billing Partner';
        }
        if (partnerId == resellerId) {
            return 'Reseller';
        }
        if (partnerId == distributorId) {
            return 'Distributor';
        }
        if (partnerId == referralPartnerId) {
            return 'Referral Partner';
        }
        return 'Unknown';
    }

}

/**
 * @description Service class for Partner Pricing business logic.
 *              Provides reusable methods for pricing calculations, model validation,
 *              and partner pricing configuration management.
 * @author Marc DeBrey
 * @date December 2025
 */
public without sharing class PartnerPricingServiceV2 {

    private static final String DEAL_TYPE_FORTRA_ORIGINATED = 'Fortra Originated';

    /**
     * @description Gets all valid pricing model candidates for multiple partners (bulk operation)
     * @param partnerIds Set of Account IDs
     * @param modelType The model type to retrieve
     * @return Map of Account ID to ordered list of Partner_Pricing_Model__c candidates
     */
    public static Map<Id, List<Partner_Pricing_Model__c>> getPricingModelCandidates(Set<Id> partnerIds, String modelType) {
        Map<Id, List<Partner_Pricing_Model__c>> modelsByPartner = new Map<Id, List<Partner_Pricing_Model__c>>();

        if (partnerIds == null || partnerIds.isEmpty() || String.isBlank(modelType)) {
            return modelsByPartner;
        }

        for (Partner_Pricing_Model__c model : [
            SELECT Id, Account__c, Model_Type__c, Is_Active__c, Is_Default__c, CreatedDate,
                   Software_Percent__c, New_Maintenance_Percent__c, Renewal_Maintenance_Percent__c,
                   Subscription_Percent__c, Services_Percent__c,
                   Non_Orig_New_Maint_Pct__c, Non_Orig_Ren_Maint_Pct__c, Non_Orig_Services_Pct__c,
                   Non_Orig_Software_Pct__c, Non_Orig_Subscription_Pct__c,
                   Unit__c, Solution_Group__c, Solution_Category__c,
                   Effective_Start_Date__c, Effective_End_Date__c
            FROM Partner_Pricing_Model__c
            WHERE Account__c IN :partnerIds
            AND Model_Type__c = :modelType
            AND Is_Active__c = true
            AND (Effective_Start_Date__c = null OR Effective_Start_Date__c <= TODAY)
            AND (Effective_End_Date__c = null OR Effective_End_Date__c >= TODAY)
            ORDER BY Account__c, CreatedDate DESC
        ]) {
            if (!modelsByPartner.containsKey(model.Account__c)) {
                modelsByPartner.put(model.Account__c, new List<Partner_Pricing_Model__c>());
            }
            modelsByPartner.get(model.Account__c).add(model);
        }

        return modelsByPartner;
    }

    /**
     * @description Selects the best matching model for a quote line based on hierarchy specificity
     * @param models Candidate pricing models for a single partner, ordered newest first
     * @param unit Product Unit value
     * @param solutionGroup Product Solution Group value
     * @param solutionCategory Product Solution Category value
     * @return Best matching Partner_Pricing_Model__c or null if none applies
     */
    public static Partner_Pricing_Model__c selectBestModelForLine(
        List<Partner_Pricing_Model__c> models,
        String unit,
        String solutionGroup,
        String solutionCategory
    ) {
        if (models == null || models.isEmpty()) {
            return null;
        }

        if (String.isNotBlank(solutionCategory)) {
            for (Partner_Pricing_Model__c model : models) {
                if (model.Solution_Category__c == solutionCategory) {
                    return model;
                }
            }
        }

        if (String.isNotBlank(solutionGroup)) {
            for (Partner_Pricing_Model__c model : models) {
                if (String.isBlank(model.Solution_Category__c) &&
                    model.Solution_Group__c == solutionGroup) {
                    return model;
                }
            }
        }

        if (String.isNotBlank(unit)) {
            for (Partner_Pricing_Model__c model : models) {
                if (String.isBlank(model.Solution_Category__c) &&
                    String.isBlank(model.Solution_Group__c) &&
                    model.Unit__c == unit) {
                    return model;
                }
            }
        }

        for (Partner_Pricing_Model__c model : models) {
            if (String.isBlank(model.Solution_Category__c) &&
                String.isBlank(model.Solution_Group__c) &&
                String.isBlank(model.Unit__c)) {
                return model;
            }
        }

        return null;
    }

    /**
     * @description Gets the margin percentage for a specific product type from a pricing model
     *              and deal type specific discount set.
     * @param model The Partner Pricing Model record
     * @param productType The Fortra_Product_Type__c value (e.g., "Software", "Subscription")
     * @param dealType The Quote Deal_Type__c value
     * @return Decimal percentage (e.g., 15.00 for 15%)
     */
    public static Decimal getMarginForProductType(
        Partner_Pricing_Model__c model,
        String productType,
        String dealType
    ) {
        if (model == null || String.isBlank(productType)) {
            return 0;
        }

        Boolean useNonOriginating = dealType == DEAL_TYPE_FORTRA_ORIGINATED;

        // Non_Orig_* is read ONLY inside the useNonOriginating branch (ternary short-circuits), so callers
        // whose SOQL did not load those fields (the deal-blind path) never hit an SObjectException.
        switch on productType {
            when 'Software', 'Perpetual' {
                return useNonOriginating
                    ? effectivePct(model.Non_Orig_Software_Pct__c, model.Software_Percent__c)
                    : effectivePct(model.Software_Percent__c, null);
            }
            when 'New Maintenance' {
                return useNonOriginating
                    ? effectivePct(model.Non_Orig_New_Maint_Pct__c, model.New_Maintenance_Percent__c)
                    : effectivePct(model.New_Maintenance_Percent__c, null);
            }
            when 'Renewal Maintenance' {
                return useNonOriginating
                    ? effectivePct(model.Non_Orig_Ren_Maint_Pct__c, model.Renewal_Maintenance_Percent__c)
                    : effectivePct(model.Renewal_Maintenance_Percent__c, null);
            }
            when 'Subscription', 'SaaS Subscription' {
                return useNonOriginating
                    ? effectivePct(model.Non_Orig_Subscription_Pct__c, model.Subscription_Percent__c)
                    : effectivePct(model.Subscription_Percent__c, null);
            }
            when 'Services', 'Professional Service', 'Renewal Services' {
                return useNonOriginating
                    ? effectivePct(model.Non_Orig_Services_Pct__c, model.Services_Percent__c)
                    : effectivePct(model.Services_Percent__c, null);
            }
            when else {
                return 0;
            }
        }
    }

    /**
     * @description First non-null percent, else 0. For a Fortra-Originated deal the Non-Originating percent
     *              is preferred, falling back to the standard "catalog" percent when it is NULL (E-04 fix,
     *              Wave 3b "catalog" decision -- never silently 0% due to missing Non_Orig data).
     */
    @TestVisible
    private static Decimal effectivePct(Decimal preferred, Decimal fallback) {
        if (preferred != null) {
            return preferred;
        }
        return fallback != null ? fallback : 0;
    }

    /**
     * @description Calculate Guaranteed Margin price using ADDITIVE formula.
     *              Formula: List Price x (1 - SUM(all partner margins%))
     *              Example: $1000 with margins [15%, 10%] = $1000 × (1 - 0.25) = $750
     * @param listPrice Original list price
     * @param partnerMargins List of margin percentages from all partners (as decimals, e.g., 15 for 15%)
     * @return Adjusted price after all margins applied
     */
    public static Decimal calculateGuaranteedMarginPrice(Decimal listPrice, List<Decimal> partnerMargins) {
        if (listPrice == null || listPrice <= 0) {
            return listPrice;
        }

        if (partnerMargins == null || partnerMargins.isEmpty()) {
            return listPrice;
        }

        Decimal totalMarginPercent = 0;
        for (Decimal marginPercent : partnerMargins) {
            if (marginPercent != null && marginPercent > 0) {
                totalMarginPercent += marginPercent;
            }
        }

        if (totalMarginPercent > 100) {
            totalMarginPercent = 100;
        }

        Decimal multiplier = 1 - (totalMarginPercent / 100);
        return (listPrice * multiplier).setScale(2, RoundingMode.HALF_UP);
    }

    /**
     * @description Calculate Discount Model price
     *              Formula: List Price x (1 - Billing Partner's Discount%)
     * @param listPrice Original list price
     * @param discountPercent Billing partner's discount percentage (as decimal, e.g., 20 for 20%)
     * @return Adjusted price after discount applied
     */
    public static Decimal calculateDiscountPrice(Decimal listPrice, Decimal discountPercent) {
        if (listPrice == null || listPrice <= 0) {
            return listPrice;
        }

        if (discountPercent == null || discountPercent <= 0) {
            return listPrice;
        }

        Decimal multiplier = 1 - (discountPercent / 100);
        return (listPrice * multiplier).setScale(2, RoundingMode.HALF_UP);
    }

}

/**
 * @description Service class for splitting Power order lines during Quote-to-Order conversion.
 * When a Power product order line has quantity > 1, this service splits it into individual
 * lines (qty=1 each) and handles associated Hardware and Partition records according to
 * the product's Power Split Type configuration.
 *
 * Split Types:
 * - "Order Line Only": Order lines split, Hardware SHARED, Partitions CLONED
 * - "Order Line and Hardware": Order lines split, Hardware CLONED, Partitions CLONED
 *
 * Bulk-safe: any number of Orders passed in one invocable call are processed together with a
 * fixed SOQL/DML budget (queries use IN :orderIds, each phase DMLs once across all orders).
 * No SOQL or DML runs inside a loop.
 */
public with sharing class PowerOrderSplittingService {

    private static final String SPLIT_TYPE_ORDER_LINE_ONLY = 'Order Line Only';
    private static final String SPLIT_TYPE_ORDER_LINE_AND_HARDWARE = 'Order Line and Hardware';
    private static final String SOLUTION_GROUP_POWER = 'Power';

    // SC-3447 guardrail: the maximum number of split OrderItem clones the synchronous Quote-to-Order
    // convert can safely create (across all orders in one invocable call) before it risks the Apex
    // CPU / 10,000-DML-row governor limits and rolls the whole convert back. Above this we fail fast
    // with a clear message instead of a governor crash. High Power quantities are usually seat/site
    // license counts (often thousands, or an "unlimited" sentinel like 999,999) that should NOT be
    // split into per-unit lines at all; the largest split that has ever succeeded org-wide is single
    // digits, so 200 is generous headroom. Adjust this one value if the business sets a different cap.
    private static final Integer MAX_SYNC_CLONES = 200;

    // Cached field describe for OrderItem
    private static Map<String, Schema.SObjectField> orderItemFieldMap;

    @InvocableMethod(
        label='Split Power Order Lines'
        description='Splits Power order lines with qty > 1 into individual lines and handles hardware/partition cloning'
        category='Order Management'
    )
    public static List<SplitResult> splitPowerOrderLines(List<SplitRequest> requests) {
        List<SplitResult> results = new List<SplitResult>();
        Map<Id, SplitResult> resultByOrderId = new Map<Id, SplitResult>();
        Set<Id> orderIds = new Set<Id>();

        for (SplitRequest request : requests) {
            SplitResult result = new SplitResult();
            results.add(result);
            if (request.orderId == null) {
                result.success = false;
                result.errorMessage = 'Order ID is required';
                continue;
            }
            orderIds.add(request.orderId);
            resultByOrderId.put(request.orderId, result);
        }

        if (!orderIds.isEmpty()) {
            processOrders(orderIds, resultByOrderId);
        }

        return results;
    }

    public class SplitRequest {
        @InvocableVariable(label='Order ID' description='The Order ID to process for Power line splitting' required=true)
        public Id orderId;
    }

    public class SplitResult {
        @InvocableVariable(label='Success' description='Whether the splitting operation succeeded')
        public Boolean success;

        @InvocableVariable(label='Lines Created' description='Number of new order lines created from splitting')
        public Integer linesCreated;

        @InvocableVariable(label='Hardware Cloned' description='Number of hardware records cloned')
        public Integer hardwareCloned;

        @InvocableVariable(label='Partitions Cloned' description='Number of partition records cloned')
        public Integer partitionsCloned;

        @InvocableVariable(label='Error Message' description='Error message if the operation failed')
        public String errorMessage;

        public SplitResult() {
            this.success = true;
            this.linesCreated = 0;
            this.hardwareCloned = 0;
            this.partitionsCloned = 0;
            this.errorMessage = '';
        }
    }

    /**
     * @description Backward-compatible single-order entry point. Delegates to the bulk path so
     * existing callers and tests keep working while the invocable stays bulk-safe.
     */
    public static SplitResult processOrder(Id orderId) {
        SplitRequest request = new SplitRequest();
        request.orderId = orderId;
        return splitPowerOrderLines(new List<SplitRequest>{ request })[0];
    }

    /**
     * @description Bulk Power-line splitting across many Orders in one transaction. Preserves the
     * per-order phase logic and index lockstep; only the SOQL/DML are batched across orders.
     * Order.ValidationResult (the RC activation gate) is captured per order and restored to null
     * for any order we actually split that was clean beforehand.
     */
    private static void processOrders(Set<Id> orderIds, Map<Id, SplitResult> resultByOrderId) {
        // Capture pre-existing ValidationResult per order (RC activation gate). ANY OrderItem DML
        // flips a null ValidationResult to 'TransactionIncomplete', blocking activation with the
        // misleading "prices aren't updated" error; we restore null at the end for orders we split.
        Map<Id, String> preValidationResultByOrder = new Map<Id, String>();
        for (Order ord : [SELECT Id, OrderNumber, ValidationResult FROM Order WHERE Id IN :orderIds]) {
            preValidationResultByOrder.put(ord.Id, ord.ValidationResult);
        }

        Savepoint sp = Database.setSavepoint();

        try {
            // Qualifying order items across all orders, with ALL accessible fields, deterministically ordered.
            List<OrderItem> itemsToSplit = queryOrderItemsToSplit(orderIds);
            System.debug('PowerOrderSplittingService: Qualifying items to split: ' + itemsToSplit.size());

            if (itemsToSplit.isEmpty()) {
                return;
            }

            // SC-3447 guardrail: count the clones this split would create (Σ(qty-1) across all
            // qualifying lines). If it exceeds the supported synchronous maximum, stop now and
            // return a clear, catchable error instead of expanding into thousands of OrderItems and
            // breaching the Apex CPU / DML-row limits (which would silently roll the convert back).
            // No DML has run yet, so the savepoint above is a harmless no-op on this path.
            Integer totalClones = 0;
            for (OrderItem oi : itemsToSplit) {
                totalClones += (Integer.valueOf(oi.Quantity) - 1);
            }
            if (totalClones > MAX_SYNC_CLONES) {
                String msg = 'This quote has a Power line quantity too large to split into individual '
                    + 'order lines (' + totalClones + ' lines would be created; the supported maximum '
                    + 'is ' + MAX_SYNC_CLONES + '). High Power quantities usually represent seat or '
                    + 'site licenses and should be kept on a single line. Please contact your '
                    + 'administrator.';
                for (SplitResult result : resultByOrderId.values()) {
                    result.success = false;
                    result.errorMessage = msg;
                }
                return;
            }

            // Collect related record IDs across all orders
            Set<Id> partitionIds = new Set<Id>();
            Set<Id> hardwareIds = new Set<Id>();
            for (OrderItem oi : itemsToSplit) {
                if (oi.Partition_Record__c != null) {
                    partitionIds.add(oi.Partition_Record__c);
                }
                if (oi.Hardware__c != null) {
                    hardwareIds.add(oi.Hardware__c);
                }
            }

            Map<Id, Partition__c> partitionMap = queryPartitions(partitionIds);
            Map<Id, Hardware__c> hardwareMap = queryHardware(hardwareIds);

            // Phase 1: Build clone OrderItems in memory (qty-1 clones per original).
            // The original OrderItem is KEPT and updated in place to count as the first slot.
            List<OrderItem> newItems = new List<OrderItem>();
            List<Hardware__c> newHardwareRecords = new List<Hardware__c>();

            for (OrderItem original : itemsToSplit) {
                SplitResult result = resultByOrderId.get(original.OrderId);
                Integer qty = Integer.valueOf(original.Quantity);
                String splitType = original.Product2.Power_Split_Type__c;
                if (String.isBlank(splitType)) {
                    splitType = SPLIT_TYPE_ORDER_LINE_ONLY;
                }
                Boolean cloneHw = (splitType == SPLIT_TYPE_ORDER_LINE_AND_HARDWARE);

                Decimal manualDiscountPer = original.Manual_Discount__c != null ?
                    original.Manual_Discount__c / qty : null;
                Decimal displacedARRPer = original.Displaced_ARR__c != null ?
                    original.Displaced_ARR__c / qty : null;
                Decimal orderLineARRPer = original.Order_Line_ARR__c != null ?
                    original.Order_Line_ARR__c / qty : null;

                Hardware__c origHw = original.Hardware__c != null ?
                    hardwareMap.get(original.Hardware__c) : null;

                // Create (qty - 1) clones. The original counts as slot 0; clones are slots 1..qty-1.
                for (Integer i = 1; i < qty; i++) {
                    OrderItem splitItem = createFullClone(original);
                    splitItem.Quantity = 1;
                    splitItem.Manual_Discount__c = manualDiscountPer;
                    splitItem.Displaced_ARR__c = displacedARRPer;
                    splitItem.Order_Line_ARR__c = orderLineARRPer;
                    splitItem.Is_Split_Line__c = true;
                    splitItem.Original_Order_Item__c = original.Id;

                    if (cloneHw && original.Hardware__c != null) {
                        splitItem.Hardware__c = null;
                    }

                    newItems.add(splitItem);
                }

                // Clone hardware for clones (slots 1..qty-1) if "Order Line and Hardware"
                if (cloneHw && origHw != null) {
                    for (Integer i = 1; i < qty; i++) {
                        newHardwareRecords.add(cloneHardwareRecord(origHw, i));
                        if (result != null) {
                            result.hardwareCloned++;
                        }
                    }
                }

                if (result != null) {
                    result.linesCreated += (qty - 1);
                }
            }

            // Phase 2: Insert cloned hardware (all orders)
            if (!newHardwareRecords.isEmpty()) {
                insert newHardwareRecords;
            }

            // Phase 3: Assign cloned hardware IDs to clone OrderItems (slots 1..qty-1)
            Integer hwIdx = 0;
            Integer itemIdx = 0;
            for (OrderItem original : itemsToSplit) {
                Integer qty = Integer.valueOf(original.Quantity);
                String splitType = original.Product2.Power_Split_Type__c;
                if (String.isBlank(splitType)) {
                    splitType = SPLIT_TYPE_ORDER_LINE_ONLY;
                }
                Boolean cloneHw = (splitType == SPLIT_TYPE_ORDER_LINE_AND_HARDWARE);

                for (Integer i = 1; i < qty; i++) {
                    if (cloneHw && original.Hardware__c != null && hwIdx < newHardwareRecords.size()) {
                        newItems[itemIdx].Hardware__c = newHardwareRecords[hwIdx].Id;
                        hwIdx++;
                    }
                    itemIdx++;
                }
            }

            // Phase 4: Insert clone OrderItems (all orders)
            if (!newItems.isEmpty()) {
                insert newItems;
                System.debug('PowerOrderSplittingService: Inserted ' + newItems.size() + ' new OrderItems');
            }

            // Phase 5: Update originals in place (Quantity=1, distribute amounts, unmark split)
            List<OrderItem> originalsToUpdate = new List<OrderItem>();
            for (OrderItem original : itemsToSplit) {
                Integer qty = Integer.valueOf(original.Quantity);

                Decimal manualDiscountPer = original.Manual_Discount__c != null ?
                    original.Manual_Discount__c / qty : null;
                Decimal displacedARRPer = original.Displaced_ARR__c != null ?
                    original.Displaced_ARR__c / qty : null;
                Decimal orderLineARRPer = original.Order_Line_ARR__c != null ?
                    original.Order_Line_ARR__c / qty : null;

                originalsToUpdate.add(new OrderItem(
                    Id = original.Id,
                    Quantity = 1,
                    Manual_Discount__c = manualDiscountPer,
                    Displaced_ARR__c = displacedARRPer,
                    Order_Line_ARR__c = orderLineARRPer,
                    Is_Split_Line__c = false,
                    Original_Order_Item__c = null
                ));
            }
            if (!originalsToUpdate.isEmpty()) {
                update originalsToUpdate;
            }

            // Phase 6: Create cloned partitions (one per clone slot 1..qty-1).
            List<Partition__c> newPartitions = new List<Partition__c>();
            hwIdx = 0;
            for (OrderItem original : itemsToSplit) {
                SplitResult result = resultByOrderId.get(original.OrderId);
                Integer qty = Integer.valueOf(original.Quantity);
                String splitType = original.Product2.Power_Split_Type__c;
                if (String.isBlank(splitType)) {
                    splitType = SPLIT_TYPE_ORDER_LINE_ONLY;
                }
                Boolean cloneHw = (splitType == SPLIT_TYPE_ORDER_LINE_AND_HARDWARE);
                Partition__c origPartition = original.Partition_Record__c != null ?
                    partitionMap.get(original.Partition_Record__c) : null;

                if (origPartition != null) {
                    for (Integer i = 1; i < qty; i++) {
                        Id hwIdForPartition;
                        if (cloneHw && hwIdx < newHardwareRecords.size()) {
                            hwIdForPartition = newHardwareRecords[hwIdx].Id;
                            hwIdx++;
                        } else {
                            hwIdForPartition = original.Hardware__c;
                        }
                        newPartitions.add(clonePartitionRecord(origPartition, hwIdForPartition, i));
                        if (result != null) {
                            result.partitionsCloned++;
                        }
                    }
                }
            }

            if (!newPartitions.isEmpty()) {
                insert newPartitions;
            }

            // Phase 7: Update clone OrderItems with their cloned partition references
            List<OrderItem> itemsToUpdatePartition = new List<OrderItem>();
            Integer partIdx = 0;
            itemIdx = 0;
            for (OrderItem original : itemsToSplit) {
                Integer qty = Integer.valueOf(original.Quantity);
                Partition__c origPartition = original.Partition_Record__c != null ?
                    partitionMap.get(original.Partition_Record__c) : null;

                for (Integer i = 1; i < qty; i++) {
                    if (origPartition != null && partIdx < newPartitions.size()) {
                        newItems[itemIdx].Partition_Record__c = newPartitions[partIdx].Id;
                        itemsToUpdatePartition.add(newItems[itemIdx]);
                        partIdx++;
                    }
                    itemIdx++;
                }
            }

            if (!itemsToUpdatePartition.isEmpty()) {
                update itemsToUpdatePartition;
            }

            // Phase 8: Restore Order.ValidationResult to null for each order we actually split
            // that was clean beforehand (never mask a pre-existing validation issue).
            List<Order> ordersToClear = new List<Order>();
            for (Id orderId : orderIds) {
                SplitResult result = resultByOrderId.get(orderId);
                if (result != null && result.linesCreated > 0 && preValidationResultByOrder.get(orderId) == null) {
                    ordersToClear.add(new Order(Id = orderId, ValidationResult = null));
                }
            }
            if (!ordersToClear.isEmpty()) {
                update ordersToClear;
                System.debug('PowerOrderSplittingService: Cleared Order.ValidationResult on ' + ordersToClear.size() + ' order(s)');
            }

        } catch (Exception e) {
            Database.rollback(sp);
            String msg = e.getMessage() + ' at line ' + e.getLineNumber();
            for (Id orderId : orderIds) {
                SplitResult result = resultByOrderId.get(orderId);
                if (result != null) {
                    result.success = false;
                    result.errorMessage = msg;
                    result.linesCreated = 0;
                    result.hardwareCloned = 0;
                    result.partitionsCloned = 0;
                }
            }
            System.debug('PowerOrderSplittingService ERROR: ' + msg);
        }
    }

    /**
     * @description Query order items to split (across many orders) using dynamic SOQL with ALL
     * accessible fields, so createFullClone() copies every attribute to the split items.
     */
    private static List<OrderItem> queryOrderItemsToSplit(Set<Id> orderIds) {
        Map<String, Schema.SObjectField> fieldMap = getOrderItemFieldMap();
        List<String> queryFields = new List<String>();
        for (String fieldName : fieldMap.keySet()) {
            Schema.DescribeFieldResult dfr = fieldMap.get(fieldName).getDescribe();
            if (dfr.isAccessible()) {
                queryFields.add(fieldName);
            }
        }

        // Add parent relationship fields needed for split logic
        queryFields.add('Product2.Power_Split_Type__c');
        queryFields.add('Product2.Solution_Group__c');
        queryFields.add('Product2.Name');

        String solGroup = SOLUTION_GROUP_POWER;
        String splitTypeOLH = SPLIT_TYPE_ORDER_LINE_AND_HARDWARE;
        // SC-3447 (P3): only split lines that have a genuine PER-MACHINE artifact to clone — a
        // Partition (the dominant "Order Line Only" path clones one Partition per unit) or, for the
        // "Order Line and Hardware" split type, a Hardware record. A high Power Quantity is a
        // seat/site license count (routinely thousands, or an "unlimited" sentinel such as 999,999),
        // NOT a machine count, and those lines carry no Partition/Hardware. Such lines must stay as a
        // single Quantity=N OrderItem (which Workday and RLM accept natively) instead of exploding
        // into one line per unit and breaching the Apex CPU / 10,000-DML-row governor limits.
        String soql = 'SELECT ' + String.join(queryFields, ', ')
            + ' FROM OrderItem'
            + ' WHERE OrderId IN :orderIds'
            + ' AND Product2.Solution_Group__c = :solGroup'
            + ' AND Quantity > 1'
            + ' AND (Partition_Record__c != null'
            + '      OR (Product2.Power_Split_Type__c = :splitTypeOLH AND Hardware__c != null))'
            + ' ORDER BY OrderId, Id';

        return Database.query(soql);
    }

    /**
     * @description Create a full clone of an OrderItem, copying all createable fields.
     */
    private static OrderItem createFullClone(OrderItem original) {
        OrderItem clone = new OrderItem();
        Map<String, Schema.SObjectField> fieldMap = getOrderItemFieldMap();
        for (String fieldName : fieldMap.keySet()) {
            Schema.DescribeFieldResult dfr = fieldMap.get(fieldName).getDescribe();
            if (dfr.isCreateable()) {
                try {
                    Object val = original.get(fieldName);
                    if (val != null) {
                        clone.put(fieldName, val);
                    }
                } catch (Exception e) {
                    // Skip fields that can't be read from the queried record
                }
            }
        }
        return clone;
    }

    private static Map<String, Schema.SObjectField> getOrderItemFieldMap() {
        if (orderItemFieldMap == null) {
            orderItemFieldMap = Schema.SObjectType.OrderItem.fields.getMap();
        }
        return orderItemFieldMap;
    }

    private static Map<Id, Partition__c> queryPartitions(Set<Id> partitionIds) {
        if (partitionIds.isEmpty()) {
            return new Map<Id, Partition__c>();
        }
        return new Map<Id, Partition__c>([
            SELECT Id, Name, Hardware__c, Partition_ID__c, Partition_Name__c,
                   Partition_Number__c, Number_of_Processors__c,
                   License_Key__c, Status__c, Activation_Date__c,
                   Expiration_Date__c, Notes__c
            FROM Partition__c
            WHERE Id IN :partitionIds
        ]);
    }

    private static Map<Id, Hardware__c> queryHardware(Set<Id> hardwareIds) {
        if (hardwareIds.isEmpty()) {
            return new Map<Id, Hardware__c>();
        }
        return new Map<Id, Hardware__c>([
            SELECT Id, Name, Account__c, Primary_Contact__c, Parent_Hardware__c,
                   Location__c, Primary_Quote__c, Primary_Order__c, Primary_Asset__c,
                   Serial_Number__c, Model_Number__c, Manufacturer__c, Hardware_Type__c
            FROM Hardware__c
            WHERE Id IN :hardwareIds
        ]);
    }

    private static Hardware__c cloneHardwareRecord(Hardware__c original, Integer index) {
        Hardware__c cloned = new Hardware__c();
        cloned.Account__c = original.Account__c;
        cloned.Primary_Contact__c = original.Primary_Contact__c;
        cloned.Parent_Hardware__c = original.Parent_Hardware__c;
        cloned.Location__c = original.Location__c;
        cloned.Serial_Number__c = original.Serial_Number__c != null ?
            original.Serial_Number__c + '-SPLIT-' + index : null;
        cloned.Model_Number__c = original.Model_Number__c;
        cloned.Manufacturer__c = original.Manufacturer__c;
        cloned.Hardware_Type__c = original.Hardware_Type__c;
        return cloned;
    }

    private static Partition__c clonePartitionRecord(Partition__c original, Id hardwareId, Integer index) {
        Partition__c cloned = new Partition__c();
        cloned.Hardware__c = hardwareId;
        cloned.Partition_ID__c = original.Partition_ID__c != null ?
            original.Partition_ID__c + '-SPLIT-' + index : null;
        cloned.Partition_Name__c = original.Partition_Name__c != null ?
            original.Partition_Name__c + ' (Split ' + index + ')' : null;
        cloned.Partition_Number__c = original.Partition_Number__c;
        cloned.Number_of_Processors__c = original.Number_of_Processors__c;
        cloned.Status__c = original.Status__c;
        cloned.Activation_Date__c = original.Activation_Date__c;
        cloned.Expiration_Date__c = original.Expiration_Date__c;
        cloned.Notes__c = original.Notes__c;
        return cloned;
    }
}

/**
 * @description Shared test fixtures for the Fortra pricing-prehook test suite.
 * @author Marc DeBrey
 */
@isTest
public class PricingPrehookTestFixtures {

    public static Account account(String name) {
        Account a = new Account(Name = name + ' ' + String.valueOf(Crypto.getRandomLong()).right(8));
        Database.DMLOptions dml = new Database.DMLOptions();
        dml.DuplicateRuleHeader.allowSave = true;
        Database.insert(a, dml);
        return a;
    }

    public static Hardware__c hardware(String pGroup, String serverType, Decimal users) {
        Hardware__c hw = new Hardware__c(
            Account__c = account('HW Acct').Id,
            P_Group_List__c = pGroup, Server_Type__c = serverType,
            Users_Per_Partition__c = users, Model_Number__c = 'TEST-MODEL',
            Serial_Number__c = 'SN-' + String.valueOf(Crypto.getRandomLong()).right(10));
        insert hw;
        return hw;
    }

    public static Map<String, Object> tag(Object v) {
        return new Map<String, Object>{ 'tagValue' => v };
    }

    public static Map<String, Object> itemNode(Map<String, Object> tagValues, List<Object> dataPath) {
        return new Map<String, Object>{ 'tagValue' => tagValues, 'dataPath' => dataPath };
    }

    /**
     * Most recent contract created by assetWithActivatedContractOverride(). Lets callers assert on /
     * re-query the activated Contract (COLA override fields) directly, since the AssetContractRelationship
     * link is NOT reliably insertable on this org (see below).
     */
    public static Id lastContractId { get; private set; }

    /**
     * True iff the AssetContractRelationship link row was successfully inserted by the most recent call to
     * assetWithActivatedContractOverride(). On Revenue Cloud orgs this is typically FALSE: the link requires
     * an Asset with HasLifecycleManagement=true, which is a platform-owned (createable=false, updateable=false)
     * field that direct test DML cannot set. The Account + activated Contract + COLA override + Asset are
     * always created; only the ACR link is best-effort. Downstream code (AssetContractQueryHelper) already
     * tolerates an absent ACR via try/catch + CMDT fallback, so this fixture mirrors that contract.
     */
    public static Boolean lastAcrLinked { get; private set; }

    /**
     * @description Builds the Asset + Activated Contract (with COLA override) data graph used by the COLA
     *              uplift tests and asset-contract query helper. Returns the Asset Id.
     *
     * Contract: inserted Draft (the org's only RecordType is ContractLifecycleManagement, so we do NOT
     * specify a RecordType) then promoted to Status='Activated' via update -- this transition is permitted;
     * only POST-activation Status writes are platform-blocked.
     *
     * AssetContractRelationship: attempted best-effort and wrapped in try/catch. The platform requires the
     * related Asset to have Lifecycle Management enabled (HasLifecycleManagement=true), which is set only by
     * the order-to-asset pipeline and cannot be set by direct DML. When the link cannot be created the method
     * still returns a valid Asset Id and sets lastAcrLinked=false; callers needing the Contract should read
     * lastContractId. NOTE: StartDate is required on AssetContractRelationship -- omitting it turns the DML
     * error into an uncatchable platform UNKNOWN_EXCEPTION, so it is always supplied.
     */
    public static Id assetWithActivatedContractOverride(Decimal overridePercent, Date persistUntil) {
        Account acct = account('Contract Acct');
        Contract c = new Contract(AccountId = acct.Id, Status = 'Draft',
            StartDate = Date.today().addMonths(-1), ContractTerm = 12,
            COLA_Override_Percent__c = overridePercent, COLA_Override_Persist_Until__c = persistUntil);
        insert c;
        c.Status = 'Activated';
        update c;
        lastContractId = c.Id;

        Asset a = new Asset(Name = 'Test Asset', AccountId = acct.Id,
            Price = 1000, Quantity = 1, Status = 'Installed');
        insert a;

        lastAcrLinked = false;
        try {
            AssetContractRelationship acr = new AssetContractRelationship(
                AssetId = a.Id, ContractId = c.Id, StartDate = System.now());
            insert acr;
            lastAcrLinked = true;
        } catch (Exception e) {
            // Expected on Revenue Cloud orgs: "Asset must have Lifecycle Management enabled."
            // The Asset's HasLifecycleManagement flag is platform-owned and not settable via test DML.
            System.debug(LoggingLevel.WARN,
                'AssetContractRelationship link not created (expected on RC orgs): ' + e.getMessage());
        }
        return a.Id;
    }

    /**
     * @description Self-test proving the asset-contract fixture executes. Downstream tasks depend on it.
     *              Asserts the reliably-creatable graph (Asset + Activated Contract + COLA override); the
     *              AssetContractRelationship link is best-effort and asserted only when lastAcrLinked is true,
     *              matching how AssetContractQueryHelper tolerates an absent ACR.
     */
    @isTest
    static void testAssetWithActivatedContractOverride() {
        Test.startTest();
        Id assetId = assetWithActivatedContractOverride(7.5, null);
        Test.stopTest();

        System.assertNotEquals(null, assetId, 'Fixture should return a non-null Asset Id');
        System.assertNotEquals(null, lastContractId, 'Fixture should record the Contract Id');

        Asset a = [SELECT Id, AccountId FROM Asset WHERE Id = :assetId];
        System.assertEquals(assetId, a.Id, 'Asset row should exist');

        Contract c = [
            SELECT Id, Status, COLA_Override_Percent__c
            FROM Contract WHERE Id = :lastContractId
        ];
        System.assertEquals('Activated', c.Status, 'Contract should be Activated');
        System.assertEquals(7.5, c.COLA_Override_Percent__c, 'COLA override percent should be persisted');

        // ACR link is best-effort: assert it only when it actually got created.
        if (lastAcrLinked) {
            List<AssetContractRelationship> acrs = [
                SELECT Id, AssetId, ContractId FROM AssetContractRelationship WHERE AssetId = :assetId
            ];
            System.assertEquals(1, acrs.size(),
                'When lastAcrLinked is true exactly one AssetContractRelationship row should exist');
            System.assertEquals(lastContractId, acrs[0].ContractId, 'ACR should point at the activated Contract');
        }
    }
}

/**
 * @description Apex Prehook for Revenue Cloud Quote pricing that auto-generates
 *              QuoteLineItem.Description from a fixed, hardcoded list of
 *              configuration attributes.
 *
 *              Output format (per "Text Population in the Line Description.pdf"):
 *
 *                Combine a list of values using " | " as a separator, ignoring
 *                empty ones. Single-line. No labels (except the special-case
 *                Unit Type segment described below).
 *
 *              The output is the Product Name followed by up to 10
 *              attribute segments, all joined by " | ":
 *
 *                  0.  Product Name (Product2.Name on the line)
 *                  1.  Unit Type    (special logic, depends on Unit Quantity attribute)
 *                  2.  License Type
 *                  3.  PS Service Type
 *                  4.  Feature      (UAT attribute label "Feature Options")
 *                  5.  Maintenance Type (UAT label "Maintenance Type Defn")
 *                  6.  Deployment Type  (UAT label "Deployment Option")
 *                  7.  Server Location Type
 *                  8.  Power License Type
 *                  9.  Server Type
 *                  10. Group Number
 *
 *              Unit Type rules:
 *                - If Unit Type is blank → skip the segment entirely.
 *                - If Unit Type = "Per Users":
 *                    - With Unit Quantity attribute value → "Users: <qty>"
 *                    - Without Unit Quantity attribute       → "Per User"
 *                - Any other Unit Type value (e.g., "Flat Fee", "Devices"):
 *                    - With Unit Quantity attribute value → "<Unit Type>: <qty>"
 *                    - Without Unit Quantity attribute       → "<Unit Type>" as-is
 *
 *              The Unit Quantity used in the rendering above is the value of
 *              a configuration attribute on the line — NOT the standard
 *              QuoteLineItem.Quantity field. Attribute_Volume is preferred;
 *              when absent, Number_of_Units is used (e.g. beSECURE device
 *              ranges). Either is consulted for ANY Unit Type value (not only
 *              "Per Users"); the "Per Users" branch is a special case that
 *              translates to a "Users:" prefix and the "Per User" wording
 *              for the no-quantity case. Lines whose product exposes neither
 *              attribute simply omit the count.
 *
 *              Behavior:
 *              - Overwrites Description on every Quote pricing run for any line
 *                that produces at least one non-empty segment. The Product Name
 *                is always the leading segment, so every line with a product
 *                gets at least a product-name description.
 *              - Lines with no SalesTransactionItemAttribute records still
 *                receive a product-name-only Description (attribute-less
 *                products such as flat license fees no longer land blank).
 *                Only a line with neither a product name nor any attribute
 *                segment is skipped.
 *              - Description is written via Context.IndustriesContext
 *                .updateContextAttributes targeting the SalesTrxnItemDescription
 *                hydration-mapped attribute. Direct DML is FORBIDDEN inside
 *                the pricing prehook context (the runtime DML limit is 0
 *                — any DML throws "Too many DML statements: 1").
 *
 * @note Quote pricing only. Orders do not allow product/configuration
 *       changes after conversion, so Description is fixed at conversion time
 *       and does not need regeneration in the Order pricing context. If the
 *       prehook is somehow invoked from a non-Quote context, it bails safely.
 *
 * @note Register LAST in the Quote pricing prehook chain.
 *
 * @note OPEN ITEMS to confirm with Fortra before go-live:
 *       - Confirm exact AttributeDefinition.DeveloperName for each of the 10
 *         attributes (the deck shows display labels, not API names — the
 *         constants below are best-guess and need verification).
 *       - Confirm the literal value emitted by the configurator for the
 *         Unit Type "Per Users" case ("Per Users" vs "Users").
 *       - Confirm the deck's sample output discrepancy: page 4 logic says
 *         "Users: 10" but page 8 sample shows "User: 15" — the code uses
 *         "Users:" (plural, matching the logic).
 *
 * @author Marc DeBrey
 * @date April 2026
 * @version 8.0 — Product Name prepended as the leading segment. Adds a
 *                bulk SOQL on QuoteLineItem to read each line's Product Name.
 *                SOQL is permitted in prehooks (only DML is forbidden).
 *
 *                v7.0 — Description writeback via updateContextAttributes;
 *                direct DML rejected with "Too many DML statements: 1".
 *                v6.0 — Unit Quantity attribute applies to ANY Unit Type.
 *                v5.0 — Unit Quantity from configuration attribute.
 */
global class QLDescriptionGeneratorPrehook implements RevSignaling.SignalingApexProcessor {

    // ============================================================
    // SPEC CONSTANTS — single source of truth for the description
    // ============================================================

    /** Separator between non-empty segments. */
    @TestVisible private static final String SEPARATOR = ' | ';

    /**
     * @description Truncation marker appended when the joined string exceeds
     *              the Description Text(4000) limit. Uses the same separator
     *              shape so the truncated output remains readable.
     */
    @TestVisible private static final String TRUNCATION_MARKER = ' | [truncated]';

    @TestVisible private static final Integer DESCRIPTION_MAX_LENGTH = 4000;

    /**
     * @description Configuration attribute DeveloperNames in render order,
     *              AFTER the special Unit Type segment. Empty values are
     *              skipped silently. NOTE: these names are best-guess from
     *              the UAT labels on page 5 of the deck and must be confirmed
     *              against AttributeDefinition.DeveloperName in fortrauat.
     */
    @TestVisible private static final List<String> ATTRIBUTE_ORDER = new List<String>{
        // PLACEHOLDER — License Type is in scope per the deck (page 7) but
        // no AttributeDefinition with this DeveloperName exists in fortrauat
        // as of 2026-04-27. The deck flagged the UAT name as "?" indicating
        // the attribute may not be created yet. Leaving the constant here is
        // forward-compatible: when the attribute is created with
        // DeveloperName "License_Type" the code will pick it up
        // automatically (missing attribute values are silently skipped).
        'License_Type',
        'PS_Service_Type',           // verified in fortrauat 2026-04-27
        'Feature_Options',           // verified in fortrauat 2026-04-27 (deck logic "Feature")
        'Maintenance_Type_Defn',     // verified in fortrauat 2026-04-27 (deck logic "Maintenance Type")
        'Deployment_Option',         // verified in fortrauat 2026-04-27 (deck logic "Deployment Type")
        'Server_Location_Type',      // verified in fortrauat 2026-04-27
        'Power_License_Type',        // verified in fortrauat 2026-04-27
        'Server_Type',               // verified in fortrauat 2026-04-27
        'Group_Number'               // verified in fortrauat 2026-04-27 (NOT the same as PGroup, which is excluded)
    };

    /** Attribute that drives the special-case Unit Type segment. */
    @TestVisible private static final String UNIT_TYPE_ATTR = 'Unit_Type';

    /**
     * @description Configuration attribute carrying the unit count used in
     *              the Unit Type segment rendering. Read from the runtime
     *              context attribute map — NOT from QuoteLineItem.Quantity.
     *              Products that don't expose this attribute simply omit
     *              the count from their Unit Type segment.
     *
     *              The deck refers to this attribute as "Unit Quantity"
     *              (its display Label). The actual AttributeDefinition
     *              DeveloperName in fortrauat is "Attribute_Volume" with
     *              Name "Unit Volume" — verified 2026-04-27.
     */
    @TestVisible private static final String UNIT_QUANTITY_ATTR = 'Attribute_Volume';

    /**
     * @description Fallback unit-count attribute when Attribute_Volume is not
     *              exposed on the product. Verified on beSECURE QLI
     *              0QLWC000003bIvV4AU (Number of Units picklist, e.g. "36-65").
     */
    @TestVisible private static final String NUMBER_OF_UNITS_ATTR = 'Number_of_Units';

    /**
     * @description Unit Type AttributeValue that triggers "Users: <qty>" /
     *              "Per User" rendering. The deck calls this value "Per Users"
     *              (plural) but the configurator actually emits "Per User"
     *              (singular) — verified in fortrauat 2026-04-27 against
     *              QLI 0QLWC00000311rZ4AQ.
     */
    @TestVisible private static final String UNIT_TYPE_PER_USERS = 'Per User';

    /**
     * @description Hydration-mapped context attribute name that writes back
     *              to QuoteLineItem.Description (verified in
     *              SalesTransactionContextExt.contextDefinition-meta.xml
     *              line 5003, fieldType=inputoutput).
     */
    @TestVisible private static final String CONTEXT_DESCRIPTION_ATTR = 'SalesTrxnItemDescription';

    @TestVisible private static final String ROLE_SEGMENT = 'Segment';
    @TestVisible private static final String ROLE_UNIT_TYPE = 'Unit Type';
    @TestVisible private static final String ROLE_UNIT_QTY = 'Unit Quantity';
    @TestVisible private static final String ROLE_UNIT_QTY_FALLBACK = 'Unit Quantity Fallback';

    /** @description Test seam: when non-null, used instead of the live SOQL. */
    @TestVisible private static List<QL_Description_Attribute__mdt> configOverride;

    private static Boolean isProcessing = false;

    // ============================================================
    // RESOLVED CONFIG
    // ============================================================

    /**
     * @description Resolved, runtime-ready description configuration. Built
     *              either from active QL_Description_Attribute__mdt rows or,
     *              when none exist, from the in-code defaults (today's list).
     */
    public class ResolvedConfig {
        // Fields are public so the extracted QLDescriptionCalculator can read them (Wave-2 thinning).
        public List<String> segmentNames = new List<String>();
        public String unitTypeAttr;
        public String unitTypeTrigger;
        public String unitQtyPrimary;
        public String unitQtyFallback;
    }

    /** @description Default config equal to the legacy hard-coded behavior. */
    @TestVisible
    private ResolvedConfig defaultConfig() {
        ResolvedConfig cfg = new ResolvedConfig();
        cfg.segmentNames = ATTRIBUTE_ORDER.clone();
        cfg.unitTypeAttr = UNIT_TYPE_ATTR;
        cfg.unitTypeTrigger = UNIT_TYPE_PER_USERS;
        cfg.unitQtyPrimary = UNIT_QUANTITY_ATTR;
        cfg.unitQtyFallback = NUMBER_OF_UNITS_ATTR;
        return cfg;
    }

    /**
     * @description Resolve runtime config: the override (tests) or active
     *              QL_Description_Attribute__mdt rows; empty -> defaults.
     */
    @TestVisible
    private ResolvedConfig loadConfig() {
        List<QL_Description_Attribute__mdt> rows = (configOverride != null)
            ? configOverride
            : queryActiveConfig();
        if (rows == null || rows.isEmpty()) {
            return defaultConfig();
        }
        return buildResolvedConfig(rows);
    }

    private List<QL_Description_Attribute__mdt> queryActiveConfig() {
        return [
            SELECT Attribute_API_Name__c, Role__c, Sort_Order__c, Match_Value__c
            FROM QL_Description_Attribute__mdt
            WHERE Active__c = true
            ORDER BY Sort_Order__c NULLS LAST
        ];
    }

    /**
     * @description Build a ResolvedConfig from rows. Segment rows are ordered
     *              by Sort_Order__c (nulls last, ties keep encounter order).
     *              The first active row of each unit role wins.
     */
    @TestVisible
    private ResolvedConfig buildResolvedConfig(List<QL_Description_Attribute__mdt> rows) {
        ResolvedConfig cfg = new ResolvedConfig();
        Map<Decimal, List<String>> segmentsByOrder = new Map<Decimal, List<String>>();

        for (QL_Description_Attribute__mdt r : rows) {
            String apiName = r.Attribute_API_Name__c;
            if (String.isBlank(apiName)) {
                continue;
            }
            String role = r.Role__c;
            if (role == ROLE_SEGMENT) {
                Decimal ord = (r.Sort_Order__c == null) ? 999999 : r.Sort_Order__c;
                if (!segmentsByOrder.containsKey(ord)) {
                    segmentsByOrder.put(ord, new List<String>());
                }
                segmentsByOrder.get(ord).add(apiName);
            } else if (role == ROLE_UNIT_TYPE && cfg.unitTypeAttr == null) {
                cfg.unitTypeAttr = apiName;
                cfg.unitTypeTrigger = r.Match_Value__c;
            } else if (role == ROLE_UNIT_QTY && cfg.unitQtyPrimary == null) {
                cfg.unitQtyPrimary = apiName;
            } else if (role == ROLE_UNIT_QTY_FALLBACK && cfg.unitQtyFallback == null) {
                cfg.unitQtyFallback = apiName;
            }
        }

        List<Decimal> orders = new List<Decimal>(segmentsByOrder.keySet());
        orders.sort();
        for (Decimal o : orders) {
            cfg.segmentNames.addAll(segmentsByOrder.get(o));
        }
        return cfg;
    }

    // ============================================================
    // ENTRY POINT
    // ============================================================

    public RevSignaling.TransactionResponse execute(RevSignaling.TransactionRequest request) {
        RevSignaling.TransactionResponse response = new RevSignaling.TransactionResponse();

        if (isProcessing) {
            response.status = RevSignaling.TransactionStatus.SUCCESS;
            response.message = 'QLDescriptionGeneratorPrehook skipped - already processing';
            return response;
        }

        try {
            isProcessing = true;
            String contextId = request != null ? request.ctxInstanceId : null;

            if (String.isBlank(contextId)) {
                response.status = RevSignaling.TransactionStatus.FAILED;
                response.message = 'Context instance ID is required';
                return response;
            }

            Context.IndustriesContext ctx = new Context.IndustriesContext();

            // Step 1 — discover line items and their dataPaths (needed for
            // updateContextAttributes node-path targeting).
            Map<Id, List<Object>> dataPathByLineId = queryLineItemDataPaths(ctx, contextId);
            if (dataPathByLineId.isEmpty()) {
                response.status = RevSignaling.TransactionStatus.SUCCESS;
                response.message = 'No SalesTransactionItem records — nothing to generate';
                return response;
            }

            // Quote-only scope guard. If a non-QuoteLineItem context invokes
            // this prehook (e.g., a misconfigured Order pricing procedure),
            // bail safely without touching anything.
            if (!isQuoteLineSet(dataPathByLineId.keySet())) {
                response.status = RevSignaling.TransactionStatus.SUCCESS;
                response.message = 'Non-Quote context — Description generation skipped';
                return response;
            }

            // Step 2 — read configured attributes for each line. Lines with no
            // attributes are NOT short-circuited: they still receive a
            // product-name-only description (spec: Product Name is always the
            // leading segment). Attribute-less products (e.g. flat license fees)
            // otherwise land blank on the quote, order, and asset.
            Map<Id, Map<String, String>> attrsByLineId = queryConfiguredAttributes(ctx, contextId);

            // Step 3 — read the Product Name for EVERY line in scope (not only
            // lines that have attributes), since the product name is the leading
            // description segment for every line.
            Map<Id, String> productNameByLineId = queryProductNames(dataPathByLineId.keySet());

            // Step 4 — build a context update payload for every line that
            // produces a non-null description (product name and/or attributes).
            ResolvedConfig cfg = loadConfig();
            List<Map<String, Object>> contextUpdates =
                buildContextUpdates(attrsByLineId, dataPathByLineId, productNameByLineId, cfg);

            // Step 5 — submit all updates in one call.
            Integer updated = submitContextUpdates(ctx, contextId, contextUpdates);

            response.status = RevSignaling.TransactionStatus.SUCCESS;
            response.message = 'Generated descriptions for ' + updated + ' of ' + dataPathByLineId.size() + ' lines';

        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'QLDescriptionGeneratorPrehook error: ' + e.getMessage());
            System.debug(LoggingLevel.ERROR, 'Stack: ' + e.getStackTraceString());
            // D-18: surface the swallowed degrade (fire-and-forget; never throws; status unchanged).
            PricingHookLogger.logPrehook('QLDescriptionGeneratorPrehook', request != null ? request.ctxInstanceId : null, e);
            response.status = RevSignaling.TransactionStatus.SUCCESS;
            response.message = 'Description generation completed with warnings: ' + e.getMessage();
        } finally {
            isProcessing = false;
        }

        return response;
    }

    // ============================================================
    // SCOPE GUARD — Quote only
    // ============================================================

    /**
     * @description True iff the first Id in the set is a QuoteLineItem.
     *              Used to bail out safely if the prehook is invoked from a
     *              non-Quote pricing context.
     */
    @TestVisible
    private Boolean isQuoteLineSet(Set<Id> lineIds) {
        if (lineIds == null || lineIds.isEmpty()) {
            return false;
        }
        Schema.SObjectType firstType = (new List<Id>(lineIds))[0].getSObjectType();
        return firstType == QuoteLineItem.SObjectType;
    }

    // ============================================================
    // CONTEXT ATTRIBUTE QUERY
    // ============================================================

    /**
     * @description Mirror of HardwareAttributePricingPrehook.queryConfiguredAttributes
     *              (force-app/main/default/classes/HardwareAttributePricingPrehook.cls:331-444).
     */
    @TestVisible
    private Map<Id, Map<String, String>> queryConfiguredAttributes(Context.IndustriesContext ctx, String contextId) {
        Map<Id, Map<String, String>> result = new Map<Id, Map<String, String>>();
        try {
            Map<String, Object> queryInput = new Map<String, Object>{
                'contextId' => contextId,
                'tags' => new List<String>{ 'SalesTransactionItemAttribute' }
            };
            // NOTE: this live queryTags call MUST stay inside this try/catch. The original behavior
            // swallows any queryTags failure and returns an empty map (the caller then short-circuits
            // execute() with "No SalesTransactionItemAttribute records"). The response PARSE logic is
            // extracted to parseConfiguredAttributes(Map) so it can be unit-tested with a hand-built
            // response, but the swallow-and-continue contract is preserved byte-for-byte.
            Map<String, Object> apiResponse = ctx.queryTags(queryInput);
            result = parseConfiguredAttributes(apiResponse);
        } catch (Exception e) {
            System.debug(LoggingLevel.WARN, 'queryConfiguredAttributes error: ' + e.getMessage());
        }
        return result;
    }

    /**
     * @description Parse a queryTags(SalesTransactionItemAttribute) response into a map of
     *              line-item Id -> (attribute name -> attribute value). Pure of any live-context
     *              dependency, so it can be unit-tested with a hand-built response map. Handles the
     *              nested {queryResult:{SalesTransactionItemAttribute:[...]}} and the flatter
     *              {SalesTransactionItemAttribute:...} shapes, the nested-tagValue vs flat node
     *              layouts, the ParentReference vs dataPath-parent resolution, the Attribute vs
     *              AttributeKeyName fallback, and the bad-id Id.valueOf guard.
     * @param apiResponse Raw response map from queryTags
     * @return Map of parent line Id -> attribute map (empty when nothing parses)
     */
    @TestVisible
    private Map<Id, Map<String, String>> parseConfiguredAttributes(Map<String, Object> apiResponse) {
        return QLDescriptionCalculator.parseConfiguredAttributes(apiResponse);
    }

    // ============================================================
    // DESCRIPTION BUILDING
    // ============================================================

    /**
     * @description Build the pipe-separated Description for one line.
     *              Output shape: "<Product Name> | <Unit Type segment> |
     *              <attr 2> | ... | <attr 10>", with empty values skipped.
     *              The Product Name is always the leading segment; attribute
     *              segments are appended only when the line has attributes, so
     *              attribute-less products (e.g. flat license fees) render as
     *              the product name alone.
     * @return Joined string on success.
     *         null only when there is neither a product name nor any attribute
     *         segment to render.
     */
    @TestVisible
    private String buildDescription(String productName, Map<String, String> attrs) {
        return buildDescription(productName, attrs, defaultConfig());
    }

    @TestVisible
    private String buildDescription(String productName, Map<String, String> attrs, ResolvedConfig cfg) {
        return QLDescriptionCalculator.buildDescription(productName, attrs, cfg);
    }

    /**
     * @description Compute the leading Unit Type segment.
     *              Returns null when the segment should be omitted.
     *              The Unit Quantity used in the rendering is read from the
     *              configuration attribute map for ANY Unit Type value —
     *              never from the standard QuoteLineItem.Quantity field.
     */
    @TestVisible
    private String computeUnitTypeSegment(Map<String, String> attrs) {
        return computeUnitTypeSegment(attrs, defaultConfig());
    }

    @TestVisible
    private String computeUnitTypeSegment(Map<String, String> attrs, ResolvedConfig cfg) {
        return QLDescriptionCalculator.computeUnitTypeSegment(attrs, cfg);
    }

    /**
     * @description Resolve the unit count for the Unit Type segment.
     *              Attribute_Volume wins when present; otherwise Number_of_Units.
     * @return Trimmed quantity string, or null when neither attribute has a value.
     */
    @TestVisible
    private String resolveUnitQuantity(Map<String, String> attrs) {
        return resolveUnitQuantity(attrs, defaultConfig());
    }

    @TestVisible
    private String resolveUnitQuantity(Map<String, String> attrs, ResolvedConfig cfg) {
        return QLDescriptionCalculator.resolveUnitQuantity(attrs, cfg);
    }

    // ============================================================
    // LINE ITEM DATAPATH QUERY
    // ============================================================

    /**
     * @description Query SalesTransactionItem from the runtime context and
     *              return a map of line item Id → dataPath. The dataPath is
     *              required by updateContextAttributes to target each line's
     *              node in the context tree. Mirrors the queryTags pattern
     *              used elsewhere in this codebase.
     */
    @TestVisible
    private Map<Id, List<Object>> queryLineItemDataPaths(Context.IndustriesContext ctx, String contextId) {
        Map<Id, List<Object>> result = new Map<Id, List<Object>>();
        try {
            Map<String, Object> queryInput = new Map<String, Object>{
                'contextId' => contextId,
                'tags' => new List<String>{ 'SalesTransactionItem' }
            };
            // NOTE: this live queryTags call MUST stay inside this try/catch. The original behavior
            // swallows any queryTags failure and returns an empty map (the caller then short-circuits
            // execute() with "No SalesTransactionItem records"). The response PARSE logic is extracted
            // to parseLineItemDataPaths(Map) so it can be unit-tested with a hand-built response, but
            // the swallow-and-continue contract is preserved byte-for-byte.
            Map<String, Object> apiResponse = ctx.queryTags(queryInput);
            result = parseLineItemDataPaths(apiResponse);
        } catch (Exception e) {
            System.debug(LoggingLevel.WARN, 'queryLineItemDataPaths error: ' + e.getMessage());
        }
        return result;
    }

