/**
 * @description Apex Hook for Revenue Cloud pricing that applies regional
 *              pricing adjustments based on country multipliers.
 *
 *              Reads: ListPrice or UnitPrice from context
 *              Writes: UnitPrice (regional-adjusted base price)
 *                      RegionalNetUnitPrice__c (audit field for TLE display)
 *
 * @author Marc DeBrey
 * @date January 2026
 *
 * @version 13.3 - Independent hook (no direct dependencies on other hooks)
 */
global class RegionalServicesPricingPrehook implements RevSignaling.SignalingApexProcessor {

    // Recursion guard (normalized to the other prehooks): prevents re-entrant execution.
    private static Boolean isProcessing = false;

    // Default multiplier when no matching regional pricing found
    private static final Decimal DEFAULT_MULTIPLIER = 1.0;

    /**
     * @description Execute method called by Revenue Cloud pricing orchestration
     * @param request The transaction request containing pricing context
     * @return TransactionResponse indicating success or failure
     */
    public RevSignaling.TransactionResponse execute(RevSignaling.TransactionRequest request) {
        System.debug(LoggingLevel.INFO, '==========================================================');
        System.debug(LoggingLevel.INFO, '=== RegionalServicesPricingPrehook v13.3 START ===');
        System.debug(LoggingLevel.INFO, '=== Applies regional pricing multipliers ===');
        System.debug(LoggingLevel.INFO, '==========================================================');

        String contextId = request.ctxInstanceId;
        System.debug(LoggingLevel.INFO, 'Context ID: ' + contextId);

        String message = '';
        Integer updatedCount = 0;

        // Skip on re-entry so a context write that re-triggers pricing cannot recurse.
        if (isProcessing) {
            RevSignaling.TransactionResponse skip = new RevSignaling.TransactionResponse();
            skip.status = RevSignaling.TransactionStatus.SUCCESS;
            skip.message = 'Regional pricing skipped (re-entrant call)';
            return skip;
        }
        isProcessing = true;

        try {
            // Step 1: Load regional pricing multipliers from Custom Metadata
            Map<String, Decimal> countryMultipliers = loadRegionalPricingMultipliers();
            System.debug(LoggingLevel.INFO, 'Loaded ' + countryMultipliers.size() + ' regional pricing records');

            if (countryMultipliers.isEmpty()) {
                message = 'No regional pricing multipliers configured';
            } else {
                // Step 2: Create Context API instance
                Context.IndustriesContext industriesContext = new Context.IndustriesContext();

                // Step 3: Query for SalesTransaction (Quote header) to get country
                String country = getShippingCountry(industriesContext, contextId);
                System.debug(LoggingLevel.INFO, 'Shipping country: ' + country);

                if (String.isBlank(country)) {
                    message = 'No shipping country found';
                } else {
                    // Step 4: Get multiplier for country
                    Decimal multiplier = getMultiplierForCountry(countryMultipliers, country);
                    System.debug(LoggingLevel.INFO, 'Multiplier for ' + country + ': ' + multiplier);

                    if (multiplier == DEFAULT_MULTIPLIER) {
                        message = 'Country ' + country + ' uses default multiplier (1.0)';
                    } else {
                        // Step 5: Query line items and apply regional pricing
                        updatedCount = processLineItems(industriesContext, contextId, multiplier, country);
                        message = updatedCount + ' items updated with regional pricing (multiplier=' + multiplier + ')';
                    }
                }
            }
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error: ' + e.getMessage());
            System.debug(LoggingLevel.ERROR, 'Stack: ' + e.getStackTraceString());
            message = 'Error: ' + e.getMessage();
            // D-18: surface the swallowed degrade (fire-and-forget; never throws; status unchanged).
            PricingHookLogger.logPrehook('RegionalServicesPricingPrehook', contextId, e);
        } finally {
            isProcessing = false;
        }

        System.debug(LoggingLevel.INFO, '=== RegionalServicesPricingPrehook v13.3 END ===');
        System.debug(LoggingLevel.INFO, 'Result: ' + message);

        RevSignaling.TransactionResponse response = new RevSignaling.TransactionResponse();
        response.status = RevSignaling.TransactionStatus.SUCCESS;
        response.message = message;
        return response;
    }

    /**
     * @description Load regional pricing multipliers from Custom Metadata Type
     * @return Map of country name/code to multiplier
     */
    public Map<String, Decimal> loadRegionalPricingMultipliers() {
        Map<String, Decimal> multipliers = new Map<String, Decimal>();

        // SDD Rule 14 / BR-007: honor effective dating in ADDITION to Is_Active__c ("Only load ACTIVE
        // multipliers" + "Support effective dating"). CMDT SOQL rejects OR disjunctions, so the
        // null-safe start/end window is evaluated in memory via RegionalPricingCalculator.isEffectiveOn
        // (this also keeps the date rule unit-testable — __mdt rows cannot be inserted in a test).
        // Rows with null start AND null end have no time bound and always load (prior behavior).
        Date today = Date.today();

        for (Services_Regional_Pricing__mdt record : [
            SELECT Country__c, Country_Code__c, Multiplier__c,
                Effective_Start_Date__c, Effective_End_Date__c
            FROM Services_Regional_Pricing__mdt
            WHERE Is_Active__c = true
        ]) {
            if (!RegionalPricingCalculator.isEffectiveOn(record.Effective_Start_Date__c, record.Effective_End_Date__c, today)) {
                continue;
            }
            if (record.Country__c != null) {
                multipliers.put(record.Country__c, record.Multiplier__c);
            }
            if (record.Country_Code__c != null) {
                multipliers.put(record.Country_Code__c, record.Multiplier__c);
            }
        }

        return multipliers;
    }

    // Wave-2: implementation moved to RegionalPricingCalculator; thin wrapper preserves the existing test API.
    public Decimal getMultiplierForCountry(Map<String, Decimal> multipliers, String country) {
        return RegionalPricingCalculator.getMultiplierForCountry(multipliers, country);
    }

    /**
     * @description Get shipping country from SalesTransaction context
     * @param industriesContext Context API instance
     * @param contextId Context instance ID
     * @return Country name or null
     */
    @TestVisible
    private String getShippingCountry(Context.IndustriesContext industriesContext, String contextId) {
        // NOTE: the live queryTags call MUST stay inside this try/catch. The original behavior
        // swallows any queryTags failure and returns null (callers then short-circuit to
        // "No shipping country found"). The parse logic is extracted to parseShippingCountry()
        // so it can be unit-tested with a hand-built response, but the swallow-and-continue
        // contract is preserved byte-for-byte.
        try {
            Map<String, Object> queryInput = new Map<String, Object>{
                'contextId' => contextId,
                'tags' => new List<String>{ 'SalesTransaction' }
            };

            Map<String, Object> queryOutput = industriesContext.queryTags(queryInput);
            return parseShippingCountry(queryOutput);
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Error getting shipping country: ' + e.getMessage());
        }
        return null;
    }

    /**
     * @description Parse the shipping country out of a queryTags(SalesTransaction) response.
     *              Tries ShipToPlace_Country__c first, then falls back to ShippingCountry.
     * @param queryOutput Raw response map from queryTags
     * @return Country name or null
     */
    @TestVisible
    private String parseShippingCountry(Map<String, Object> queryOutput) {
        Map<String, Object> queryResult = (Map<String, Object>) queryOutput.get('queryResult');

        if (queryResult != null) {
            List<Object> transactionData = (List<Object>) queryResult.get('SalesTransaction');
            if (transactionData != null && !transactionData.isEmpty()) {
                Map<String, Object> transNode = (Map<String, Object>) transactionData[0];
                Map<String, Object> tagMap = (Map<String, Object>) transNode.get('tagValue');

                // Try ShipToPlace_Country__c first
                String country = getStringFromTag(tagMap, 'ShipToPlace_Country__c');
                if (String.isNotBlank(country)) {
                    return country;
                }

                // Fall back to ShippingCountry
                return getStringFromTag(tagMap, 'ShippingCountry');
            }
        }
        return null;
    }

    /**
     * @description Process line items and write regional price to context
     * @param industriesContext Context API instance
     * @param contextId Context instance ID
     * @param multiplier Regional pricing multiplier
     * @param country The shipping country for explainer text
     * @return Number of items updated
     */
    @TestVisible
    private Integer processLineItems(Context.IndustriesContext industriesContext, String contextId, Decimal multiplier, String country) {
        // Query for SalesTransactionItem (Quote Line Items)
        Map<String, Object> queryInput = new Map<String, Object>{
            'contextId' => contextId,
            'tags' => new List<String>{ 'SalesTransactionItem' }
        };

        // NOTE: this queryTags call is intentionally NOT wrapped in a try/catch -- the original
        // implementation let a queryTags failure propagate up to execute()'s outer try/catch
        // (which sets message = 'Error: ...'). That behavior is preserved: only the parse +
        // build loop is extracted to buildItemUpdates(), and the submit retains its own
        // try/catch in submitContextUpdates().
        Map<String, Object> queryOutput = industriesContext.queryTags(queryInput);
        Map<String, Object> queryResult = (Map<String, Object>) queryOutput.get('queryResult');

        if (queryResult == null) {
            System.debug(LoggingLevel.INFO, 'No queryResult in response');
            return 0;
        }

        List<Object> lineItemData = (List<Object>) queryResult.get('SalesTransactionItem');
        if (lineItemData == null || lineItemData.isEmpty()) {
            System.debug(LoggingLevel.INFO, 'No line items found');
            return 0;
        }

        System.debug(LoggingLevel.INFO, 'Found ' + lineItemData.size() + ' line items');

        List<Map<String, Object>> itemNodeUpdates = buildItemUpdates(lineItemData, multiplier, country);

        // Submit context update
        if (!itemNodeUpdates.isEmpty()) {
            submitContextUpdates(industriesContext, contextId, itemNodeUpdates);
        }

        return itemNodeUpdates.size();
    }

    /**
     * @description Build the list of context node updates for a list of already-parsed line-item
     *              nodes. Pure of any live-context dependency, so it can be unit-tested with
     *              hand-built {tagValue, dataPath} maps. Lines with no valid price (null or <= 0)
     *              are skipped. For each kept line a node update is built via buildNodeUpdate().
     * @param lineItemData Parsed SalesTransactionItem node list (each a {tagValue, dataPath} map)
     * @param multiplier Regional pricing multiplier
     * @param country The shipping country for explainer text
     * @return List of node-update maps (one per line item that produced an update)
     */
    @TestVisible
    private List<Map<String, Object>> buildItemUpdates(List<Object> lineItemData, Decimal multiplier, String country) {
        List<Map<String, Object>> itemNodeUpdates = new List<Map<String, Object>>();

        for (Object itemObj : lineItemData) {
            Map<String, Object> itemNode = (Map<String, Object>) itemObj;
            List<Object> dataPath = (List<Object>) itemNode.get('dataPath');
            Map<String, Object> tagMap = (Map<String, Object>) itemNode.get('tagValue');

            // Get current price (ListPrice or UnitPrice)
            Decimal listPrice = getDecimalFromTag(tagMap, 'ListPrice');
            Decimal unitPrice = getDecimalFromTag(tagMap, 'UnitPrice');
            Decimal currentPrice = listPrice != null ? listPrice : unitPrice;

            String productId = getStringFromTag(tagMap, 'ProductId');
            System.debug(LoggingLevel.INFO, 'Item: ProductId=' + productId + ', Price=' + currentPrice);

            if (currentPrice == null || currentPrice <= 0) {
                System.debug(LoggingLevel.INFO, '  Skipping - no valid price');
                continue;
            }

            itemNodeUpdates.add(buildNodeUpdate(dataPath, currentPrice, multiplier, country));
        }

        return itemNodeUpdates;
    }

    /**
     * @description Build a single context node-update map for one priced line item.
     *              Clones dataPath and drops its first element (the context-root segment) so the
     *              update path is relative; an empty dataPath is left empty (no remove).
     * @param dataPath The line-item node's dataPath
     * @param currentPrice Resolved pre-regional price (ListPrice or UnitPrice)
     * @param multiplier Regional pricing multiplier
     * @param country The shipping country for explainer text
     * @return Node-update map with nodePath + attributes
     */
    @TestVisible
    private Map<String, Object> buildNodeUpdate(List<Object> dataPath, Decimal currentPrice, Decimal multiplier, String country) {
        // Calculate regional price
        Decimal regionalPrice = calculateAdjustedPrice(currentPrice, multiplier);
        System.debug(LoggingLevel.INFO, '  Regional price: ' + currentPrice + ' x ' + multiplier + ' = ' + regionalPrice);

        // Build update path
        List<Object> updatePath = dataPath.clone();
        if (!updatePath.isEmpty()) {
            updatePath.remove(0);
        }

        // Create attribute updates for context
        List<Object> attributes = new List<Object>();

        // UnitPrice - regional-adjusted base price
        // Available to subsequent pricing steps in the waterfall
        attributes.add(new Map<String, Object>{
            'attributeName' => 'UnitPrice',
            'attributeValue' => regionalPrice
        });

        // RegionalNetUnitPrice__c - audit field for TLE display
        attributes.add(new Map<String, Object>{
            'attributeName' => 'RegionalNetUnitPrice__c',
            'attributeValue' => regionalPrice
        });

        // === Pricing Procedure Waterfall Visibility Tags ===

        // PrehookRSNetUnitPrice__c - calculated price for Assignment element
        attributes.add(new Map<String, Object>{
            'attributeName' => 'PrehookRSNetUnitPrice__c',
            'attributeValue' => regionalPrice
        });

        // RegionalPricingExplainer__c - human-readable text for waterfall display
        String explainerText = 'Regional Services Multiplier: ' + multiplier.setScale(2) + ' (' + country + ')';
        attributes.add(new Map<String, Object>{
            'attributeName' => 'RegionalPricingExplainer__c',
            'attributeValue' => explainerText
        });

        // RegionalPricingApplied__c - flag for conditional Assignment element
        attributes.add(new Map<String, Object>{
            'attributeName' => 'RegionalPricingApplied__c',
            'attributeValue' => true
        });

        // Pre_Regional_Price__c - original price before regional adjustment
        attributes.add(new Map<String, Object>{
            'attributeName' => 'Pre_Regional_Price__c',
            'attributeValue' => currentPrice
        });

        // Regional_Multiplier__c - the multiplier applied
        attributes.add(new Map<String, Object>{
            'attributeName' => 'Regional_Multiplier__c',
            'attributeValue' => multiplier
        });

        return new Map<String, Object>{
            'nodePath' => new Map<String, Object>{ 'dataPath' => updatePath },
            'attributes' => attributes
        };
    }

    /**
     * @description Submit context attribute updates. Preserves the original swallow contract:
     *              a "not in updatable state" failure is swallowed (degrade gracefully); any
     *              other failure is re-thrown so execute()'s outer try/catch reports it.
     * @param industriesContext Context API instance
     * @param contextId Context instance ID
     * @param itemNodeUpdates List of node-update maps to submit
     */
    @TestVisible
    private void submitContextUpdates(Context.IndustriesContext industriesContext, String contextId, List<Map<String, Object>> itemNodeUpdates) {
        System.debug(LoggingLevel.INFO, 'Submitting ' + itemNodeUpdates.size() + ' updates');

        Map<String, Object> updateInput = new Map<String, Object>{
            'contextId' => contextId,
            'nodePathAndAttributes' => itemNodeUpdates
        };

        try {
            Map<String, Object> updateResult = industriesContext.updateContextAttributes(updateInput);
            System.debug(LoggingLevel.INFO, 'Update result: ' + JSON.serializePretty(updateResult));
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Update error: ' + e.getMessage());
            if (!e.getMessage().containsIgnoreCase('not in updatable state')) {
                throw e;
            }
        }
    }

    // Wave-2: implementation moved to RegionalPricingCalculator; thin wrapper preserves the existing test API.
    public Decimal calculateAdjustedPrice(Decimal listPrice, Decimal multiplier) {
        return RegionalPricingCalculator.calculateAdjustedPrice(listPrice, multiplier);
    }

    /**
     * @description Extract string value from tag map
     */
    @TestVisible
    private String getStringFromTag(Map<String, Object> tagMap, String attributeName) {
        if (tagMap == null || !tagMap.containsKey(attributeName)) {
            return null;
        }

        Object attrObj = tagMap.get(attributeName);

        if (attrObj instanceof Map<String, Object>) {
            Map<String, Object> attrMap = (Map<String, Object>) attrObj;
            if (attrMap.containsKey('tagValue')) {
                Object value = attrMap.get('tagValue');
                return value != null ? String.valueOf(value) : null;
            }
        }

        return attrObj != null ? String.valueOf(attrObj) : null;
    }

    /**
     * @description Extract decimal value from tag map
     */
    @TestVisible
    private Decimal getDecimalFromTag(Map<String, Object> tagMap, String attributeName) {
        if (tagMap == null || !tagMap.containsKey(attributeName)) {
            return null;
        }

        try {
            Object attrObj = tagMap.get(attributeName);

            if (attrObj instanceof Map<String, Object>) {
                Map<String, Object> attrMap = (Map<String, Object>) attrObj;
                if (attrMap.containsKey('tagValue')) {
                    Object value = attrMap.get('tagValue');
                    if (value != null) {
                        return Decimal.valueOf(String.valueOf(value));
                    }
                }
            }

            if (attrObj != null) {
                return Decimal.valueOf(String.valueOf(attrObj));
            }
        } catch (Exception e) {
            System.debug(LoggingLevel.DEBUG, 'Could not parse decimal: ' + e.getMessage());
        }

        return null;
    }
}

/**
 * @description Normalizes asset-copied maintenance lines so billing Quantity matches the
 *              source asset entitlement. Platform Asset Renew/Amend often creates No Change /
 *              Amend lines with Quantity 0 while StartQuantity/EndQuantity reflect the asset;
 *              DPP and persist require billing Quantity from the asset.
 *
 *              Covers BOTH Renewal Maintenance (renewal quotes) and New Maintenance
 *              (new-business amend / asset-copy quotes — SC-3346). Renewal Maintenance
 *              flips No Change -> Renew; New Maintenance flips No Change -> Amend so the
 *              platform permits the normalized Quantity (SC-3412/SC-3413, 2026-06-16).
 *
 *              Runs in a Queueable after QuoteLineItem insert so updates do not conflict
 *              with Place Sales Transaction persist during Asset Renew/Amend.
 */
public with sharing class RenewalAssetQuantityHandler {

    public static final String QUOTE_ACTION_RENEW = 'Renew';
    public static final String QUOTE_ACTION_NO_CHANGE = 'No Change';
    public static final String QUOTE_ACTION_AMEND = 'Amend';
    public static final String PRODUCT_TYPE_RENEWAL_MAINTENANCE =
        RenewalQuoteLineHandler.PRODUCT_TYPE_RENEWAL_MAINTENANCE;
    public static final String PRODUCT_TYPE_NEW_MAINTENANCE = 'New Maintenance';

    // Asset-copy maintenance product types this handler normalizes (renewal + new business).
    private static final Set<String> MAINTENANCE_PRODUCT_TYPES = new Set<String>{
        PRODUCT_TYPE_RENEWAL_MAINTENANCE,
        PRODUCT_TYPE_NEW_MAINTENANCE
    };

    /**
     * @description Called from QuoteLineItem after insert. Defers normalization until PST completes.
     */
    public static void enqueueQuantityNormalization(List<QuoteLineItem> newLines) {
        if (RenewalMaintenanceProvisionService.bypass) {
            return; // suppress re-entrant enqueue while the provisioner is replacing carryover lines
        }
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        Set<Id> quoteIds = collectQuoteIds(newLines);
        if (quoteIds.isEmpty()) {
            return;
        }

        if (Test.isRunningTest()) {
            applyAssetQuantitiesForQuotes(quoteIds);
            return;
        }

        System.enqueueJob(new RenewalAssetQuantityQueueable(quoteIds));
    }

    /**
     * @description Direct entry for tests and manual invocation.
     */
    public static void applyAssetQuantitiesForQuotes(Set<Id> quoteIds) {
        if (quoteIds == null || quoteIds.isEmpty()) {
            return;
        }

        // Scope is the asset-copy line itself (QuoteAction present + maintenance type + qty <= 0),
        // not the quote type — covers renewal AND new-business amend/asset-copy quotes (SC-3346).
        List<QuoteLineItem> candidates = [
            SELECT Id, QuoteId, Quantity, StartQuantity, EndQuantity, QuoteActionId,
                   QuoteAction.Type, QuoteAction.SourceAssetId, QuoteAction.SourceAsset.Quantity,
                   Fortra_Product_Type__c
            FROM QuoteLineItem
            WHERE QuoteId IN :quoteIds
              AND Fortra_Product_Type__c IN :MAINTENANCE_PRODUCT_TYPES
              AND QuoteActionId != null
              AND (Quantity = null OR Quantity <= 0)
        ];

        if (candidates.isEmpty()) {
            return;
        }

        applyNormalizationUpdates(buildNormalizationUpdates(candidates));
    }

    @TestVisible
    private static NormalizationUpdates buildNormalizationUpdates(List<QuoteLineItem> candidates) {
        NormalizationUpdates updates = new NormalizationUpdates();

        if (candidates == null || candidates.isEmpty()) {
            return updates;
        }

        for (QuoteLineItem qli : candidates) {
            Decimal sourceQuantity = resolveSourceQuantity(qli);
            if (!needsQuantityNormalization(qli, sourceQuantity)) {
                continue;
            }

            String actionType = qli.QuoteAction?.Type;
            if (qli.Fortra_Product_Type__c == PRODUCT_TYPE_RENEWAL_MAINTENANCE) {
                // Renewal path (unchanged): No Change flips to Renew; only Renew/No Change normalize.
                if (actionType == QUOTE_ACTION_NO_CHANGE) {
                    updates.quoteActionsById.put(
                        qli.QuoteActionId,
                        new QuoteAction(Id = qli.QuoteActionId, Type = QUOTE_ACTION_RENEW)
                    );
                } else if (actionType != QUOTE_ACTION_RENEW) {
                    continue;
                }
            } else {
                // New Maintenance (SC-3346): asset-copy Amend/No Change/Renew -> normalize quantity.
                // The platform forbids a non-zero Quantity on a No Change line ("Specify 0 in
                // Quantity of the Quote Line Item record with the action of type No Change"), so
                // flip No Change -> Amend (the canonical new-business action that permits qty > 0)
                // before setting Quantity. Mirrors the renewal branch's No Change -> Renew flip.
                // Do NOT flip a new-business line to Renew. (SC-3412/SC-3413 regression 2026-06-16.)
                if (actionType != QUOTE_ACTION_AMEND
                    && actionType != QUOTE_ACTION_NO_CHANGE
                    && actionType != QUOTE_ACTION_RENEW) {
                    continue;
                }
                if (actionType == QUOTE_ACTION_NO_CHANGE) {
                    updates.quoteActionsById.put(
                        qli.QuoteActionId,
                        new QuoteAction(Id = qli.QuoteActionId, Type = QUOTE_ACTION_AMEND)
                    );
                }
            }

            updates.linesToUpdate.add(new QuoteLineItem(
                Id = qli.Id,
                Quantity = sourceQuantity,
                StartQuantity = 0
            ));
        }

        return updates;
    }

    private static void applyNormalizationUpdates(NormalizationUpdates updates) {
        if (updates == null) {
            return;
        }
        if (!updates.quoteActionsById.isEmpty()) {
            update updates.quoteActionsById.values();
        }
        if (!updates.linesToUpdate.isEmpty()) {
            update updates.linesToUpdate;
        }
    }

    @TestVisible
    private class NormalizationUpdates {
        public Map<Id, QuoteAction> quoteActionsById { get; private set; }
        public List<QuoteLineItem> linesToUpdate { get; private set; }

        private NormalizationUpdates() {
            quoteActionsById = new Map<Id, QuoteAction>();
            linesToUpdate = new List<QuoteLineItem>();
        }
    }

    @TestVisible
    private static Boolean needsQuantityNormalization(QuoteLineItem qli, Decimal sourceQuantity) {
        if (qli == null || sourceQuantity == null || sourceQuantity <= 0) {
            return false;
        }
        if (!MAINTENANCE_PRODUCT_TYPES.contains(qli.Fortra_Product_Type__c)) {
            return false;
        }
        if (qli.QuoteActionId == null) {
            return false;
        }

        Decimal quantity = qli.Quantity == null ? 0 : qli.Quantity;
        return quantity <= 0;
    }

    @TestVisible
    private static Decimal resolveSourceQuantity(QuoteLineItem qli) {
        if (qli == null) {
            return null;
        }

        return resolveSourceQuantity(
            qli.QuoteAction?.SourceAsset?.Quantity,
            qli.EndQuantity,
            qli.StartQuantity
        );
    }

    @TestVisible
    private static Decimal resolveSourceQuantity(
        Decimal assetQuantity,
        Decimal endQuantity,
        Decimal startQuantity
    ) {
        if (assetQuantity != null && assetQuantity > 0) {
            return assetQuantity;
        }
        if (endQuantity != null && endQuantity > 0) {
            return endQuantity;
        }
        if (startQuantity != null && startQuantity > 0) {
            return startQuantity;
        }
        return null;
    }

    private static Set<Id> collectQuoteIds(List<QuoteLineItem> lines) {
        Set<Id> quoteIds = new Set<Id>();
        for (QuoteLineItem line : lines) {
            if (line.QuoteId != null) {
                quoteIds.add(line.QuoteId);
            }
        }
        return quoteIds;
    }

    /**
     * @description Retained for existing tests / potential reuse. No longer called by
     *              applyAssetQuantitiesForQuotes — scoping is now done at the line level
     *              (QuoteAction + maintenance product type + Quantity), which covers both
     *              renewal and new-business asset-copy quotes.
     */
    @TestVisible
    private static Set<Id> resolveRenewalQuoteIds(Set<Id> quoteIds) {
        Set<Id> renewalQuoteIds = new Set<Id>();
        for (Quote quote : [
            SELECT Id
            FROM Quote
            WHERE Id IN :quoteIds
              AND (
                  OriginalActionType = :QuoteRenewalTypeHandler.ORIGINAL_ACTION_RENEW
                  OR Quote_Type__c = :QuoteRenewalTypeHandler.QUOTE_TYPE_RENEWAL
              )
        ]) {
            renewalQuoteIds.add(quote.Id);
        }
        return renewalQuoteIds;
    }
}

/**
 * @description Defers renewal maintenance quantity normalization until after Place Sales
 *              Transaction completes during Asset Renew.
 */
public with sharing class RenewalAssetQuantityQueueable implements Queueable {

    private final Set<Id> quoteIds;

    public RenewalAssetQuantityQueueable(Set<Id> quoteIds) {
        this.quoteIds = quoteIds == null ? new Set<Id>() : quoteIds.clone();
    }

    public void execute(QueueableContext context) {
        RenewalAssetQuantityHandler.applyAssetQuantitiesForQuotes(quoteIds);
        // Chain the maintenance provisioner in this same async transaction rather than enqueue a
        // competing queueable — the asset-renewal context permits only one queued job.
        RenewalMaintenanceProvisionService.provision(quoteIds);
    }
}

/**
 * @description Programmatic fallback for Year 2 BoKS config rule: when a renewal quote has
 *              BoKS perpetual and no Renewal Maintenance line, add RRM then run carryover cleanup.
 *
 *              Production trigger path no longer calls this handler. RRM must be added by the
 *              Year 2 Product Configuration Rule when perpetual is configured in TLE; carryover
 *              cleanup runs only after that configured RRM line exists.
 */
public with sharing class RenewalMaintenanceAutoAddHandler {

    @TestVisible
    private static final String BOKS_PERPETUAL_PRODUCT_CODE = 'PIA-PIA-NRPS-PIAP';
    @TestVisible
    private static final String RENEWAL_MAINTENANCE_PRODUCT_CODE = 'PIA-PIA-RRM-PIAM';
    @TestVisible
    private static final String RENEWAL_MAINTENANCE_BILLING_FREQUENCY = 'Annual';

    /**
     * @description Defers carryover cleanup until after Place Sales Transaction completes.
     *              RRM must be added by the Year 2 Product Configuration Rule in TLE, not here.
     */
    public static void enqueueIfNeeded(List<QuoteLineItem> lines) {
        if (RenewalMaintenanceProvisionService.bypass) {
            return; // suppress re-entrant enqueue while the provisioner is replacing carryover lines
        }
        if (shouldSkipCarryoverCleanupForTriggerContext()) {
            return;
        }
        RenewalQuoteLineHandler.enqueueCarryoverCleanup(lines);
    }

    @TestVisible
    private static Boolean shouldSkipCarryoverCleanupForTriggerContext() {
        return Trigger.isExecuting && !Trigger.isInsert;
    }

    /**
     * @description Adds RRM when BoKS perpetual is on a renewal quote without renewal maintenance.
     */
    public static void ensureRenewalMaintenancePresent(Set<Id> quoteIds) {
        if (quoteIds == null || quoteIds.isEmpty()) {
            return;
        }

        Set<Id> renewalQuoteIds = RenewalQuoteLineHandler.resolveRenewalQuoteIds(quoteIds);
        if (renewalQuoteIds.isEmpty()) {
            return;
        }

        Map<Id, QuoteContext> contextByQuoteId = loadQuoteContexts(renewalQuoteIds);
        List<QuoteAction> newActions = new List<QuoteAction>();
        List<PendingLine> pendingLines = new List<PendingLine>();

        for (Id quoteId : renewalQuoteIds) {
            QuoteContext context = contextByQuoteId.get(quoteId);
            if (context == null || context.hasRenewalMaintenance || !context.hasBoksPerpetual) {
                continue;
            }
            if (context.renewalMaintenancePbeId == null) {
                continue;
            }

            QuoteAction action = new QuoteAction(
                QuoteId = quoteId,
                Type = 'Add'
            );
            newActions.add(action);
            pendingLines.add(new PendingLine(quoteId, context.renewalMaintenancePbeId));
        }

        if (newActions.isEmpty()) {
            return;
        }

        insert newActions;

        List<QuoteLineItem> inserts = new List<QuoteLineItem>();
        for (Integer i = 0; i < newActions.size(); i++) {
            inserts.add(new QuoteLineItem(
                QuoteId = pendingLines[i].quoteId,
                QuoteActionId = newActions[i].Id,
                PricebookEntryId = pendingLines[i].pricebookEntryId,
                Quantity = 1,
                BillingFrequency = RENEWAL_MAINTENANCE_BILLING_FREQUENCY
            ));
        }
        insert inserts;
    }

    @TestVisible
    private static Map<Id, QuoteContext> loadQuoteContexts(Set<Id> quoteIds) {
        Map<Id, QuoteContext> contextByQuoteId = new Map<Id, QuoteContext>();
        for (Quote quote : [
            SELECT Id, Pricebook2Id, CurrencyIsoCode
            FROM Quote
            WHERE Id IN :quoteIds
        ]) {
            contextByQuoteId.put(
                quote.Id,
                new QuoteContext(quote.Id, quote.Pricebook2Id, quote.CurrencyIsoCode)
            );
        }

        Set<Id> pricebookIds = new Set<Id>();
        for (QuoteContext context : contextByQuoteId.values()) {
            if (context.pricebook2Id != null) {
                pricebookIds.add(context.pricebook2Id);
            }
        }

        Map<String, Id> renewalPbeByPricebookAndCurrency = new Map<String, Id>();
        if (!pricebookIds.isEmpty()) {
            for (PricebookEntry pbe : [
                SELECT Id, Pricebook2Id, CurrencyIsoCode, Product2.ProductCode
                FROM PricebookEntry
                WHERE Pricebook2Id IN :pricebookIds
                  AND Product2.ProductCode = :RENEWAL_MAINTENANCE_PRODUCT_CODE
                  AND IsActive = true
                ORDER BY CurrencyIsoCode ASC, Id ASC
            ]) {
                String pbeKey = renewalPbeKey(pbe.Pricebook2Id, pbe.CurrencyIsoCode);
                if (!renewalPbeByPricebookAndCurrency.containsKey(pbeKey)) {
                    renewalPbeByPricebookAndCurrency.put(pbeKey, pbe.Id);
                }
            }
        }

        for (QuoteLineItem line : [
            SELECT QuoteId, Product2.ProductCode, Product2.Fortra_Product_Type__c
            FROM QuoteLineItem
            WHERE QuoteId IN :quoteIds
        ]) {
            QuoteContext context = contextByQuoteId.get(line.QuoteId);
            if (context == null) {
                continue;
            }
            if (line.Product2?.ProductCode == BOKS_PERPETUAL_PRODUCT_CODE) {
                context.hasBoksPerpetual = true;
            }
            if (line.Product2?.ProductCode == RENEWAL_MAINTENANCE_PRODUCT_CODE
                || line.Product2?.Fortra_Product_Type__c == RenewalQuoteLineHandler.PRODUCT_TYPE_RENEWAL_MAINTENANCE) {
                context.hasRenewalMaintenance = true;
            }
        }

        for (QuoteContext context : contextByQuoteId.values()) {
            if (context.pricebook2Id != null) {
                context.renewalMaintenancePbeId = renewalPbeByPricebookAndCurrency.get(
                    renewalPbeKey(context.pricebook2Id, context.currencyIsoCode)
                );
            }
        }

        return contextByQuoteId;
    }

    @TestVisible
    private static String renewalPbeKey(Id pricebook2Id, String currencyIsoCode) {
        return String.valueOf(pricebook2Id) + '|' + String.valueOf(currencyIsoCode);
    }

    @TestVisible
    private class QuoteContext {
        public Id quoteId;
        public Id pricebook2Id;
        public String currencyIsoCode;
        public Id renewalMaintenancePbeId;
        public Boolean hasBoksPerpetual = false;
        public Boolean hasRenewalMaintenance = false;

        public QuoteContext(Id quoteId, Id pricebook2Id, String currencyIsoCode) {
            this.quoteId = quoteId;
            this.pricebook2Id = pricebook2Id;
            this.currencyIsoCode = currencyIsoCode;
        }
    }

    private class PendingLine {
        public Id quoteId;
        public Id pricebookEntryId;

        public PendingLine(Id quoteId, Id pricebookEntryId) {
            this.quoteId = quoteId;
            this.pricebookEntryId = pricebookEntryId;
        }
    }
}

/**
 * @description Flips owned New-Maintenance renewal carryover lines from a 'No Change' QuoteAction to
 *              'Renew' and sets the renew quantity from the source asset, so a subsequent reprice
 *              applies the COLA uplift to last year's net and commits the correct renewal-maintenance
 *              price instead of freezing at zero. Exposes a Flow-invocable entry point and a bulk-safe
 *              Apex method; the caller reprices the quote afterward to commit the net.
 * @author Liam Jeong <liam.jeong@coastalcloud.us>
 */
public with sharing class RenewalMaintenanceFlip {

    @TestVisible private static final String PRODUCT_TYPE_NEW_MAINTENANCE = 'New Maintenance';
    @TestVisible private static final String QA_TYPE_NO_CHANGE = 'No Change';
    @TestVisible private static final String QA_TYPE_RENEW = 'Renew';
    private static final String QUOTE_TYPE_RENEWAL = 'Renewal';
    private static final String ORIGINAL_ACTION_RENEW = 'Renew';

    /**
     * @description Flow request wrapper (one renewal quote per call; bulk-safe across calls).
     */
    public class FlipRequest {
        @InvocableVariable(label='Renewal Quote Id' required=true)
        public Id quoteId;
    }

    /**
     * @description Flow entry point — flip the owned-maintenance carryover on the given renewal quotes
     *              to Renew so the subsequent reprice commits the COLA uplift.
     * @param requests Flow request wrappers, each naming one renewal quote to flip
     */
    @InvocableMethod(
        label='Renew Maintenance Carryover'
        description='Flip No-Change owned-maintenance renewal carryover lines to Renew so they price the COLA uplift. Reprice the quote after.'
    )
    public static void flipInvocable(List<FlipRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }
        Set<Id> quoteIds = new Set<Id>();
        for (FlipRequest req : requests) {
            if (req != null && req.quoteId != null) {
                quoteIds.add(req.quoteId);
            }
        }
        flipToRenew(quoteIds);
    }

    /**
     * @description Flip No-Change New-Maintenance carryover lines on renewal quotes to Renew, set the
     *              renew quantity from the source asset. Bulk-safe; idempotent (only touches No-Change).
     * @param quoteIds Ids of the renewal quotes whose carryover maintenance lines should be flipped
     */
    public static void flipToRenew(Set<Id> quoteIds) {
        if (quoteIds == null || quoteIds.isEmpty()) {
            return;
        }

        Set<Id> renewalQuoteIds = new Set<Id>();
        for (Quote q : [
            SELECT Id FROM Quote
            WHERE Id IN :quoteIds
              AND (Quote_Type__c = :QUOTE_TYPE_RENEWAL OR OriginalActionType = :ORIGINAL_ACTION_RENEW)
        ]) {
            renewalQuoteIds.add(q.Id);
        }
        if (renewalQuoteIds.isEmpty()) {
            return;
        }

        List<QuoteLineItem> lines = [
            SELECT Id, QuoteActionId, QuoteAction.SourceAsset.Quantity
            FROM QuoteLineItem
            WHERE QuoteId IN :renewalQuoteIds
              AND Product2.Fortra_Product_Type__c = :PRODUCT_TYPE_NEW_MAINTENANCE
              AND QuoteActionId != NULL
              AND QuoteAction.Type = :QA_TYPE_NO_CHANGE
        ];
        if (lines.isEmpty()) {
            return;
        }

        List<QuoteAction> qaUpdates = new List<QuoteAction>();
        List<QuoteLineItem> lineUpdates = new List<QuoteLineItem>();
        for (QuoteLineItem line : lines) {
            qaUpdates.add(new QuoteAction(Id = line.QuoteActionId, Type = QA_TYPE_RENEW));
            Decimal renewQty = (line.QuoteAction.SourceAsset != null
                                && line.QuoteAction.SourceAsset.Quantity != null
                                && line.QuoteAction.SourceAsset.Quantity > 0)
                ? line.QuoteAction.SourceAsset.Quantity : 1;
            // A Renew line requires StartQuantity=0/null; the renew quantity is the asset quantity.
            lineUpdates.add(new QuoteLineItem(Id = line.Id, StartQuantity = 0, Quantity = renewQty));
        }
        update qaUpdates;
        update lineUpdates;
    }
}

/**
 * @description Applies COLA uplift net price to renewal maintenance quote lines when DPP
 *              leaves NetUnitPrice at zero. Updates pricing context before persist.
 */
public with sharing class RenewalMaintenancePricingService {

    private static final String CONTEXT_DEFINITION_NAME = 'SalesTransactionContextExt_v2';

    // ---------------------------------------------------------------------
    // Test seams. These are inert in production: every guard additionally
    // requires Test.isRunningTest(), and each override defaults to null, so a
    // production execution takes the exact same Context.IndustriesContext call
    // path as before. They exist only so a unit test can substitute a fabricated
    // queryTags response / context id for the live pricing-context I/O, which
    // throws (NoDataFoundException / UnexpectedException gack) outside a real
    // pricing transaction and is otherwise unreachable from an Apex test.
    @TestVisible
    private static Map<String, Object> testQueryTagsResponse;
    @TestVisible
    private static String testContextIdOverride;

    public class RepriceRequest {
        @InvocableVariable(required=true label='Quote Id')
        public String quoteId;

        @InvocableVariable(label='Context Instance Id')
        public String contextInstanceId;

        @InvocableVariable(label='Finalize COLA Net After DPP')
        public Boolean finalizeAfterPricing;
    }

    public class RepriceResult {
        @InvocableVariable(label='COLA-Only Persist Completed')
        public Boolean colaOnlyPersistComplete;
    }

    @TestVisible
    public static Boolean usesColaOnlyReprice(Id quoteId) {
        if (quoteId == null) {
            return false;
        }

        List<Quote> quotes = [
            SELECT Id, Quote_Type__c, OriginalActionType
            FROM Quote
            WHERE Id = :quoteId
            LIMIT 1
        ];
        if (quotes.isEmpty()) {
            return false;
        }

        List<QuoteLineItem> lines = [
            SELECT Id, Fortra_Product_Type__c, Product2.Fortra_Product_Type__c,
                   Base_Price__c, NetUnitPrice, TotalPrice
            FROM QuoteLineItem
            WHERE QuoteId = :quoteId
        ];

        return usesColaOnlyRepriceForLines(quotes[0], lines);
    }

    @TestVisible
    public static Boolean usesColaOnlyRepriceForLines(Quote quote, List<QuoteLineItem> lines) {
        if (quote == null || lines == null || lines.isEmpty()) {
            return false;
        }

        Boolean isRenewal = quote.Quote_Type__c == QuoteRenewalTypeHandler.QUOTE_TYPE_RENEWAL
            || quote.OriginalActionType == QuoteRenewalTypeHandler.ORIGINAL_ACTION_RENEW;
        if (!isRenewal) {
            return false;
        }

        Boolean hasRenewalMaintenance = false;
        for (QuoteLineItem qli : lines) {
            String productType = qli.Fortra_Product_Type__c != null
                ? qli.Fortra_Product_Type__c
                : qli.Product2?.Fortra_Product_Type__c;

            if (productType == 'Renewal Maintenance') {
                hasRenewalMaintenance = qli.Base_Price__c != null && qli.Base_Price__c > 0;
                continue;
            }

            if (productType == 'Perpetual' || productType == 'Software') {
                return false;
            }

            if (qli.TotalPrice != null && qli.TotalPrice > 0) {
                return false;
            }
        }

        return hasRenewalMaintenance;
    }

    @InvocableMethod(
        label='Apply Renewal Maintenance COLA Net'
        description='Writes COLA net into pricing context for renewal maintenance lines before persist'
    )
    public static List<RepriceResult> applyRenewalMaintenanceNetPrices(List<RepriceRequest> requests) {
        List<RepriceResult> results = new List<RepriceResult>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        for (RepriceRequest request : requests) {
            RepriceResult result = new RepriceResult();
            result.colaOnlyPersistComplete = false;

            if (request == null || String.isBlank(request.quoteId)) {
                results.add(result);
                continue;
            }

            Id quoteId = Id.valueOf(request.quoteId);
            try {
                if (String.isNotBlank(request.contextInstanceId)) {
                    if (request.finalizeAfterPricing == true) {
                        applyColaNetFinalizeToContext(quoteId, request.contextInstanceId);
                    } else {
                        applyToContext(quoteId, request.contextInstanceId);
                    }
                } else {
                    finalizeRenewalMaintenanceAfterPricing(quoteId);
                }
            } catch (Exception e) {
                System.debug(LoggingLevel.WARN, 'Renewal maintenance COLA net skipped: ' + e.getMessage());
            }

            results.add(result);
        }

        return results;
    }

    /**
     * @description Rebuild context after main pricing persist and write COLA net for renewal maintenance.
     */
    public static void finalizeRenewalMaintenanceAfterPricing(Id quoteId) {
        if (quoteId == null) {
            return;
        }

        List<QuoteLineItem> candidates = queryRenewalMaintenanceCandidates(quoteId);
        if (candidates.isEmpty()) {
            return;
        }

        Context.IndustriesContext ctx = new Context.IndustriesContext();
        String contextId;
        if (Test.isRunningTest() && testContextIdOverride != null) {
            contextId = testContextIdOverride;
        } else {
            Map<String, Object> buildResult = ctx.buildContext(new Map<String, Object>{
                'contextDefinitionName' => CONTEXT_DEFINITION_NAME,
                'sourceRecordId' => quoteId
            });
            contextId = buildResult != null ? String.valueOf(buildResult.get('contextId')) : null;
        }
        if (String.isBlank(contextId)) {
            return;
        }

        applyToContext(quoteId, contextId);
        try {
            if (!(Test.isRunningTest() && testContextIdOverride != null)) {
                ctx.persistContext(new Map<String, Object>{ 'contextId' => contextId });
            }
        } catch (Exception e) {
            System.debug(LoggingLevel.WARN, 'Renewal maintenance context persist failed: ' + e.getMessage());
        }
    }

    @TestVisible
    private static void applyToContext(Id quoteId, String contextInstanceId) {
        List<QuoteLineItem> candidates = filterLinesNeedingColaNet(queryRenewalMaintenanceCandidates(quoteId));

        if (candidates.isEmpty()) {
            return;
        }

        Map<Id, Decimal> colaNetByLineId = new Map<Id, Decimal>();
        for (QuoteLineItem qli : candidates) {
            Decimal colaNet = computeColaNet(qli);
            if (colaNet != null && colaNet > 0) {
                colaNetByLineId.put(qli.Id, colaNet);
            }
        }

        if (colaNetByLineId.isEmpty()) {
            return;
        }

        Context.IndustriesContext ctx = new Context.IndustriesContext();
        Map<Id, Map<String, Object>> lineItemById = mapLineItemsById(
            queryLineItems(ctx, contextInstanceId)
        );

        System.debug(LoggingLevel.INFO, 'RenewalMaintenancePricingService updating ' + colaNetByLineId.size() + ' line(s)');

        List<Map<String, Object>> itemUpdates = new List<Map<String, Object>>();
        for (QuoteLineItem qli : candidates) {
            if (!colaNetByLineId.containsKey(qli.Id)) {
                continue;
            }

            Map<String, Object> lineItem = lineItemById.get(qli.Id);
            Object updatePath = resolveUpdatePath(lineItem, qli.QuoteId, qli.Id);
            if (updatePath == null) {
                continue;
            }

            Decimal colaNet = colaNetByLineId.get(qli.Id);

            itemUpdates.add(new Map<String, Object>{
                'nodePath' => new Map<String, Object>{ 'dataPath' => updatePath },
                'attributes' => new List<Map<String, Object>>{
                    new Map<String, Object>{ 'attributeName' => 'COLACalculatedPrice__c', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'InputUnitPrice', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'SalesTransactionActionType', 'attributeValue' => 'Renew' }
                }
            });
        }

        if (itemUpdates.isEmpty()) {
            return;
        }

        Map<String, Object> updateResult = (Test.isRunningTest() && testQueryTagsResponse != null)
            ? new Map<String, Object>{ 'isSuccess' => true }
            : ctx.updateContextAttributes(new Map<String, Object>{
                'contextId' => contextInstanceId,
                'nodePathAndAttributes' => itemUpdates
            });
        System.debug(LoggingLevel.INFO, 'RenewalMaintenancePricingService update result=' + updateResult);
    }

    /**
     * @description After DPP, write stamped COLA net into pricing context so persist
     *              does not keep a stale Last Transaction asset price on renewal maintenance.
     */
    @TestVisible
    private static void applyColaNetFinalizeToContext(Id quoteId, String contextInstanceId) {
        List<QuoteLineItem> candidates = filterLinesNeedingColaNet(queryRenewalMaintenanceCandidates(quoteId));
        if (candidates.isEmpty()) {
            return;
        }

        Context.IndustriesContext ctx = new Context.IndustriesContext();
        Map<Id, Map<String, Object>> lineItemById = mapLineItemsById(
            queryLineItems(ctx, contextInstanceId)
        );

        List<Map<String, Object>> itemUpdates = new List<Map<String, Object>>();
        for (QuoteLineItem qli : candidates) {
            Decimal colaNet = computeColaNet(qli);
            if (colaNet == null || colaNet <= 0) {
                continue;
            }

            Map<String, Object> lineItem = lineItemById.get(qli.Id);
            Object updatePath = resolveUpdatePath(lineItem, qli.QuoteId, qli.Id);
            if (updatePath == null) {
                continue;
            }

            Decimal lineTotal = resolveColaLineTotal(qli, colaNet);
            itemUpdates.add(new Map<String, Object>{
                'nodePath' => new Map<String, Object>{ 'dataPath' => updatePath },
                'attributes' => new List<Map<String, Object>>{
                    new Map<String, Object>{ 'attributeName' => 'COLACalculatedPrice__c', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'InputUnitPrice', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'UnitPrice', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'NetUnitPrice', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'NetTotalPrice', 'attributeValue' => lineTotal },
                    new Map<String, Object>{ 'attributeName' => 'TotalPrice', 'attributeValue' => lineTotal },
                    new Map<String, Object>{ 'attributeName' => 'PartnerUnitPrice', 'attributeValue' => colaNet }
                }
            });
        }

        if (itemUpdates.isEmpty()) {
            return;
        }

        System.debug(LoggingLevel.INFO, 'RenewalMaintenancePricingService finalizing ' + itemUpdates.size() + ' line(s)');

        Map<String, Object> updateResult = (Test.isRunningTest() && testQueryTagsResponse != null)
            ? new Map<String, Object>{ 'isSuccess' => true }
            : ctx.updateContextAttributes(new Map<String, Object>{
                'contextId' => contextInstanceId,
                'nodePathAndAttributes' => itemUpdates
            });
        System.debug(LoggingLevel.INFO, 'RenewalMaintenancePricingService finalize result=' + updateResult);
    }

    public static Decimal computeColaNet(QuoteLineItem qli) {
        if (qli == null || qli.Base_Price__c == null || qli.Base_Price__c <= 0) {
            return null;
        }
        // Single-sourced onto the canonical stamped-maintenance calculator to eliminate formula drift.
        // The null/base guard above is retained (canonical is guard-free by design); the arithmetic is
        // byte-identical, so this delegation preserves behavior (see COLAUpliftCalculatorParityTest).
        return COLAUpliftCalculator.computeStampedMaintenanceColaNet(qli);
    }

    /**
     * @description Platform No Change asset-renew lines keep Quantity 0 on the record.
     *              Pricing context uses flat COLA net as the line total in that case.
     */
    @TestVisible
    public static Decimal resolveColaLineTotal(QuoteLineItem qli, Decimal colaNet) {
        if (colaNet == null) {
            return null;
        }
        Decimal quantity = qli != null ? qli.Quantity : null;
        if (quantity == null || quantity <= 0) {
            return colaNet;
        }
        return (colaNet * quantity).setScale(2, RoundingMode.HALF_UP);
    }

    @TestVisible
    private static List<QuoteLineItem> queryRenewalMaintenanceCandidates(Id quoteId) {
        return [
            SELECT Id, QuoteId, Base_Price__c, Prior_Partner_Discount__c, Prior_Discretionary_Discount__c,
                   PartnerDiscountPercent, Discount, COLA_Uplift_Percent__c, Quantity, NetUnitPrice
            FROM QuoteLineItem
            WHERE QuoteId = :quoteId
            AND Fortra_Product_Type__c = 'Renewal Maintenance'
            AND Base_Price__c > 0
        ];
    }

    @TestVisible
    private static List<QuoteLineItem> filterLinesNeedingColaNet(List<QuoteLineItem> lines) {
        List<QuoteLineItem> results = new List<QuoteLineItem>();
        if (lines == null || lines.isEmpty()) {
            return results;
        }

        for (QuoteLineItem qli : lines) {
            if (needsColaNetCorrection(qli)) {
                results.add(qli);
            }
        }
        return results;
    }

    @TestVisible
    private static Boolean needsColaNetCorrection(QuoteLineItem qli) {
        return needsColaNetCorrectionForValues(computeColaNet(qli), qli?.NetUnitPrice);
    }

    @TestVisible
    private static Boolean needsColaNetCorrectionForValues(Decimal colaNet, Decimal netUnitPrice) {
        if (colaNet == null || colaNet <= 0) {
            return false;
        }
        if (netUnitPrice == null || netUnitPrice == 0) {
            return true;
        }
        return netUnitPrice.setScale(2, RoundingMode.HALF_UP) != colaNet;
    }


    private static Map<Id, Map<String, Object>> mapLineItemsById(List<Map<String, Object>> lineItems) {
        Map<Id, Map<String, Object>> lineItemById = new Map<Id, Map<String, Object>>();
        if (lineItems == null || lineItems.isEmpty()) {
            return lineItemById;
        }

        for (Map<String, Object> lineItem : lineItems) {
            Id lineItemId = getLineItemRecordId(lineItem);
            if (lineItemId != null) {
                lineItemById.put(lineItemId, lineItem);
            }
        }
        return lineItemById;
    }

    private static List<Map<String, Object>> queryLineItems(Context.IndustriesContext ctx, String contextInstanceId) {
        List<Map<String, Object>> lineItems = new List<Map<String, Object>>();
        Map<String, Object> apiResponse = (Test.isRunningTest() && testQueryTagsResponse != null)
            ? testQueryTagsResponse
            : ctx.queryTags(new Map<String, Object>{
                'contextId' => contextInstanceId,
                'tags' => new List<String>{ 'SalesTransactionItem' }
            });
        if (apiResponse == null) {
            return lineItems;
        }

        Map<String, Object> queryResult;
        if (apiResponse.containsKey('queryResult')) {
            Object qrObj = apiResponse.get('queryResult');
            queryResult = (qrObj instanceof Map<String, Object>) ? (Map<String, Object>) qrObj : null;
        } else if (apiResponse.containsKey('SalesTransactionItem')) {
            queryResult = apiResponse;
        } else {
            return lineItems;
        }

        if (queryResult == null || !queryResult.containsKey('SalesTransactionItem')) {
            return lineItems;
        }

        Object itemsObj = queryResult.get('SalesTransactionItem');
        List<Object> rawLineItems = (itemsObj instanceof List<Object>)
            ? (List<Object>) itemsObj
            : new List<Object>{ itemsObj };

        for (Object rawItem : rawLineItems) {
            if (!(rawItem instanceof Map<String, Object>)) {
                continue;
            }
            Map<String, Object> itemWrapper = (Map<String, Object>) rawItem;
            if (!itemWrapper.containsKey('tagValue')) {
                continue;
            }
            Object tagValue = itemWrapper.get('tagValue');
            if (!(tagValue instanceof Map<String, Object>)) {
                continue;
            }
            Map<String, Object> lineItemData = new Map<String, Object>();
            lineItemData.putAll((Map<String, Object>) tagValue);
            if (itemWrapper.containsKey('dataPath') && itemWrapper.get('dataPath') instanceof List<Object>) {
                List<Object> pathParts = (List<Object>) itemWrapper.get('dataPath');
                if (!pathParts.isEmpty()) {
                    lineItemData.put('_recordId', String.valueOf(pathParts[pathParts.size() - 1]));
                    List<Object> updatePath = pathParts.clone();
                    if (!updatePath.isEmpty()) {
                        updatePath.remove(0);
                    }
                    lineItemData.put('_updatePath', updatePath);
                }
            }
            lineItems.add(lineItemData);
        }

        return lineItems;
    }

    @TestVisible
    private static Object resolveUpdatePath(Map<String, Object> lineItem, Id quoteId, Id lineItemId) {
        if (lineItem != null && lineItem.get('_updatePath') != null) {
            return lineItem.get('_updatePath');
        }
        if (quoteId == null || lineItemId == null) {
            return null;
        }
        return new List<Object>{ String.valueOf(quoteId), String.valueOf(lineItemId) };
    }

    private static Id getLineItemRecordId(Map<String, Object> lineItem) {
        String lineItemId = (String) lineItem.get('_recordId');
        if (String.isBlank(lineItemId)) {
            return null;
        }
        try {
            return Id.valueOf(lineItemId);
        } catch (Exception e) {
            return null;
        }
    }
